{"command": "cd /workspace && python3 -c "
import json
with open('contracts/openapi.contract.json') as f:
    spec = json.load(f)
print('=== ALL PATHS ===')
for path, methods in spec['paths'].items():
    for method, op in methods.items():
        if method in ['get','post','put','patch','delete']:
            oid = op.get('operationId','')
            print(f'{method.upper():6} {path:55} {oid}')
"", "summary": "List all API paths and operationIds"}

