    print('RESPONSES:')
    for code, resp in op['responses'].items():
        print(' ', code, '-', resp.get('description','')[:60])
        if 'content' in resp:
            print('   ', json.dumps(resp['content']['application/json']['schema'], indent=2))
    print()
" > /tmp/ops_detail.txt && wc -l /tmp/ops_detail.txt

