    for p in op.get('parameters',[]):
        print('PARAM:', p['name'], p.get('in'), 'required=', p.get('required'), 'schema=', json.dumps(p.get('schema',{})))
    for code in ['200','201']:
        if code in op['responses']:
            resp = op['responses'][code]
            print(f'RESP {code}:', json.dumps(resp['content']['application/json']['schema'], indent=2))
    # error codes
    ecodes = {}
    for code, resp in op['responses'].items():
        if 'content' in resp:
            sch = resp['content']['application/json']['schema']
            c = sch.get('properties',{}).get('code',{})
            ecodes[code] = c.get('enum', [])
    print('ERROR CODES:', json.dumps(ecodes, indent=2))
" > /tmp/ops_compact.txt && wc -l /tmp/ops_compact.txt

