package config

import (
	"fmt"
	"os"
	"strings"
)

type Config struct {
	HTTPAddr      string
	DatabaseURL   string
	MongoURI      string
	JWTSecret     string
	AdminUsername string
	AdminPassword string
	MapAssetsDir  string
	FrontendDir   string
	StaleMinutes   int
	OfferTimeoutSec int
}

func Load() (*Config, error) {
	c := &Config{
		HTTPAddr:        envOr("HTTP_ADDR", "127.0.0.1:8080"),
		DatabaseURL:     envOr("DATABASE_URL", "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"),
		MongoURI:        envOr("MONGODB_URI", "mongodb://127.0.0.1:27017/arena"),
		JWTSecret:       envOr("JWT_SECRET", "lablogistics-dev-secret-change-me"),
		AdminUsername:   os.Getenv("ADMIN_USERNAME"),
		AdminPassword:   os.Getenv("ADMIN_PASSWORD"),
		MapAssetsDir:    envOr("MAP_ASSETS_DIR", "/opt/arena/map-assets"),
		FrontendDir:     envOr("FRONTEND_DIR", "/workspace/frontend/dist"),
		StaleMinutes:    30,
		OfferTimeoutSec: 300,
	}
	if c.AdminUsername == "" {
		c.AdminUsername = "admin"
	}
	if c.AdminPassword == "" {
		c.AdminPassword = "admin"
	}
	// Normalize mongodb:// vs mongo db typo from env display
	c.MongoURI = strings.TrimSpace(c.MongoURI)
	return c, nil
}

func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func (c *Config) Validate() error {
	if c.HTTPAddr == "" {
		return fmt.Errorf("HTTP_ADDR empty")
	}
	return nil
}

