package storemongo

import (
	"context"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

const (
	DBName          = "arena_lab_logistics"
	CollAudit       = "audit_trail"
	CollRealtime    = "realtime_events"
)

type Store struct {
	Client *mongo.Client
	DB     *mongo.Database
}

func New(ctx context.Context, uri string) (*Store, error) {
	cl, err := mongo.Connect(options.Client().ApplyURI(uri))
	if err != nil {
		return nil, err
	}
	if err := cl.Ping(ctx, nil); err != nil {
		_ = cl.Disconnect(ctx)
		return nil, err
	}
	return &Store{Client: cl, DB: cl.Database(DBName)}, nil
}

// EnsureCollections materializes all collections and indexes required by the app,
// so reset produces a complete structure (no lazy creation on first write).
func (s *Store) EnsureCollections(ctx context.Context) error {
	// Create collections explicitly.
	for _, name := range []string{CollAudit, CollRealtime} {
		if err := s.DB.CreateCollection(ctx, name); err != nil {
			// ignore already-exists
			if !isNamespaceExists(err) {
				return err
			}
		}
	}
	// Audit indexes
	audit := s.DB.Collection(CollAudit)
	_, _ = audit.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "entityId", Value: 1}}},
		{Keys: bson.D{{Key: "actorId", Value: 1}}},
		{Keys: bson.D{{Key: "action", Value: 1}}},
		{Keys: bson.D{{Key: "role", Value: 1}}},
		{Keys: bson.D{{Key: "success", Value: 1}}},
		{Keys: bson.D{{Key: "occurredAt", Value: -1}}},
	})
	// Realtime indexes (event id sequence handled in PG; mirror here)
	rt := s.DB.Collection(CollRealtime)
	_, _ = rt.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "seq", Value: 1}}},
		{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "entityId", Value: 1}}},
		{Keys: bson.D{{Key: "createdAt", Value: 1}}},
	})
	return nil
}

// DropAll drops all application-owned data for reset.
func (s *Store) DropAll(ctx context.Context) error {
	for _, name := range []string{CollAudit, CollRealtime} {
		_ = s.DB.Collection(name).Drop(ctx)
	}
	return nil
}

func isNamespaceExists(err error) bool {
	if err == nil {
		return false
	}
	cmdErr, ok := err.(mongo.CommandError)
	if !ok {
		return false
	}
	return cmdErr.Code == 48 || cmdErr.Name == "NamespaceExists"
}

