package storepg

import (
	"context"
	"embed"
	"fmt"
	"strings"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
)

//go:embed schema.sql
var SchemaFS embed.FS

type DB struct {
	Pool *pgxpool.Pool
}

func New(ctx context.Context, databaseURL string) (*DB, error) {
	cfg, err := pgxpool.ParseConfig(databaseURL)
	if err != nil {
		return nil, fmt.Errorf("parse db url: %w", err)
	}
	cfg.MaxConns = 10
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("connect db: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		return nil, fmt.Errorf("ping db: %w", err)
	}
	return &DB{Pool: pool}, nil
}

// Migrate runs the schema (idempotent DROP+CREATE) and seeds defaults.
func (d *DB) Migrate(ctx context.Context) error {
	sqlBytes, err := SchemaFS.ReadFile("schema.sql")
	if err != nil {
		return err
	}
	_, err = d.Pool.Exec(ctx, string(sqlBytes))
	return err
}

// Reset drops everything and recreates structure, then seeds.
func (d *DB) Reset(ctx context.Context) error {
	return d.Migrate(ctx)
}

// IsUniqueViolation reports a Postgres unique constraint violation.
func IsUniqueViolation(err error) bool {
	if err == nil {
		return false
	}
	var pgErr *pgconn.PgError
	if strings.Contains(err.Error(), "unique") {
		_ = pgErr
	}
	// pgx v5: use pgconn.PgError
	if e, ok := err.(*pgconn.PgError); ok {
		return e.Code == "23505"
	}
	return false
}

// IsNoRows is the sentinel for no rows.
func IsNoRows(err error) bool {
	return err == pgx.ErrNoRows
}

