package auth

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base64"
	"fmt"
	"strings"
	"sync"
	"time"
)

// Simple salted SHA-256 password hashing (avoids extra bcrypt dependency).
func HashPassword(password string) (string, error) {
	salt := make([]byte, 16)
	if _, err := rand.Read(salt); err != nil {
		return "", err
	}
	return hashWithSalt(password, salt), nil
}

func hashWithSalt(password string, salt []byte) string {
	// format: sha256$base64(salt)$base64(hash)
	h := sha256Sum(append(salt, []byte(password)...))
	return fmt.Sprintf("sha256$%s$%s", base64.StdEncoding.EncodeToString(salt), base64.StdEncoding.EncodeToString(h))
}

func VerifyPassword(password, stored string) bool {
	parts := strings.Split(stored, "$")
	if len(parts) != 3 || parts[0] != "sha256" {
		return false
	}
