package audit

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/options"

	"lablogistics/internal/domain"
	smongo "lablogistics/internal/storemongo"
)

// Service writes audit records to both PG (fast timeline) and MongoDB (searchable audit).
type Service struct {
	pool  *pgxpool.Pool
	mongo *smongo.Store
}

func New(pool *pgxpool.Pool, mongo *smongo.Store) *Service {
	return &Service{pool: pool, mongo: mongo}
}

// Record writes an audit entry. Returns the PG event id (timeline eventId).
func (s *Service) Record(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) (int64, error) {
	if details == nil {
		details = map[string]interface{}{}
	}
	detailsJSON, _ := json.Marshal(details)
	var eventID int64
	occurredAt := time.Now().UTC()
	err := s.pg.QueryRow(ctx,
		`INSERT INTO audit_events (actor_id, actor_role, action, entity_type, entity_id, success, occurred_at, details)
		 VALUES ($1,$2,$3,$4,$5,$6,$7,$8) RETURNING event_id`,
		nilIfEmpty(actorID), role, action, entityType, entityID, success, occurredAt, detailsJSON,
	).Scan(&eventID)
	if err != nil {
		return 0, fmt.Errorf("audit pg insert: %w", err)
	}
	// Mirror to MongoDB
	if s.mongo != nil {
		doc := smongo.AuditDoc{
			AuditID:    fmt.Sprintf("%d", eventID),
			ActorID:    actorID,
			Role:       role,
			Action:     action,
			EntityType: entityType,
			EntityID:   entityID,
			Success:    success,
			OccurredAt: occurredAt,
			Details:    details,
		}
		_, _ = s.mongo.DB.Collection(smongo.CollAudit).InsertOne(ctx, doc)
	}
	return eventID, nil
}

func nilIfEmpty(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

// Timeline returns ordered timeline entries for an entity from PG.
func (s *Service) Timeline(ctx context.Context, entityType, entityID string, limit int) ([]domain.TimelineEntry, error) {
	if limit <= 0 {
		limit = 100
	}
	rows, err := s.pgQueryRows(ctx,
		`SELECT event_id, COALESCE(actor_id::text,''), actor_role, action, entity_type, entity_id, success, occurred_at, details
		 FROM audit_events WHERE entity_type=$1 AND entity_id=$2 ORDER BY event_id ASC LIMIT $3`,
		entityType, entityID, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []domain.TimelineEntry
	for rows.Next() {
		var e domain.TimelineEntry
		var occurredAt time.Time
		var details []byte
		if err := rows.Scan(&e.EventID, &e.ActorID, &e.Role, &e.Action, &e.EntityType, &e.EntityID, &e.Success, &occurredAt, &details); err != nil {
			return nil, err
		}
		e.OccurredAt = occurredAt.UTC().Format(time.RFC3339Nano)
		if len(details) > 0 {
			_ = json.Unmarshal(details, &e.Details)
		}
		if e.Details == nil {
			e.Details = map[string]interface{}{}
		}
		out = append(out, e)
	}
	return out, rows.Err()
}

// Search searches the audit trail via MongoDB.
func (s *Service) Search(ctx context.Context, q AuditQuery) (domain.AuditSearchResult, error) {
	res := domain.AuditSearchResult{
		Entries: []domain.AuditEntry{},
		Offset:  q.Offset,
		Limit:   q.Limit,
		Order:   q.Order,
	}
	if s.mongo == nil {
		return res, nil
	}
	filter := bson.D{}
	addFilter := func(key string, val interface{}) {
		filter = append(filter, bson.E{Key: key, Value: val})
	}
	if q.ActorID != "" {
		addFilter("actorId", q.ActorID)
	}
	if q.EntityType != "" {
		addFilter("entityType", q.EntityType)
	}
	if q.EntityID != "" {
		addFilter("entityId", q.EntityID)
	}
	if q.Action != "" {
		addFilter("action", q.Action)
	}
	if q.Role != "" {
		addFilter("role", q.Role)
	}
	if q.Success != nil {
		addFilter("success", *q.Success)
	}
	if q.Query != "" {
		filter = append(filter, bson.E{Key: "$text", Value: bson.D{{Key: "$search", Value: q.Query}}})
	}
	if !q.FromTime.IsZero() || !q.ToTime.IsZero() {
		rng := bson.D{}
		if !q.FromTime.IsZero() {
			rng = append(rng, bson.E{Key: "$gte", Value: q.FromTime})
		}
		if !q.ToTime.IsZero() {
			rng = append(rng, bson.E{Key: "$lte", Value: q.ToTime})
		}
		filter = append(filter, bson.E{Key: "occurredAt", Value: rng})
	}

	coll := s.mongo.DB.Collection(smongo.CollAudit)
	total, err := coll.CountDocuments(ctx, filter)
	if err != nil {
		return res, err
	}
	res.Total = int(total)

	opts := optionsFind()
	if q.Order == "oldest_first" {
		opts = optsSetSort(opts, bson.D{{Key: "occurredAt", Value: 1}})
	} else {
		opts = optsSetSort(opts, bson.D{{Key: "occurredAt", Value: -1}})
	}
	opts = optsSetSkip(opts, int64(q.Offset))
	opts = optsSetLimit(opts, int64(q.Limit))

	cursor, err := coll.Find(ctx, filter, opts)
	if err != nil {
		return res, err
	}
	defer cursor.Close(ctx)
	for cursor.Next(ctx) {
		var doc smongo.AuditDoc
		if err := cursor.Decode(&doc); err != nil {
			continue
		}
		res.Entries = append(res.Entries, domain.AuditEntry{
			AuditID:    doc.AuditID,
			ActorID:    doc.ActorID,
			Role:       doc.Role,
			ActorRole:  doc.Role,
			Action:     doc.Action,
			EntityType: doc.EntityType,
			EntityID:   doc.EntityID,
			Success:    doc.Success,
			OccurredAt: doc.OccurredAt.UTC().Format(time.RFC3339Nano),
			Details:    doc.Details,
		})
	}
	res.Returned = len(res.Entries)
	res.HasMore = (q.Offset + res.Returned) < res.Total
	if res.HasMore {
		n := q.Offset + res.Returned
		res.NextOffset = &n
	}
	return res, cursor.Err()
}

type AuditQuery struct {
	Query    string
	ActorID  string
	EntityType string
	EntityID string
	Action   string
	Role     string
	Success  *bool
	FromTime time.Time
	ToTime   time.Time
	Limit    int
	Offset   int
	Order    string
}

// helper row scanner for pgxpool rows
type pgxRows interface {
	Next() bool
	Scan(...interface{}) error
	Close() error
	Err() error
}

func (s *Service) pgQueryRows(ctx context.Context, sql string, args ...interface{}) (pgxRows, error) {
	// Use the pool directly via the Querier adapter.
	q := s.pg.(*pgPoolQuerier)
	rows, err := q.pool.Query(ctx, sql, args...)
	if err != nil {
		return nil, err
	}
	return &pgxRowsAdapter{rows: rows}, nil
}

type pgxRowsAdapter struct {
	rows pgx.Rows
}

func (r *pgxRowsAdapter) Next() bool       { return r.rows.Next() }
func (r *pgxRowsAdapter) Close() error     { r.rows.Close(); return nil }
func (r *pgxRowsAdapter) Err() error       { return r.rows.Err() }
func (r *pgxRowsAdapter) Scan(dest ...interface{}) error { return r.rows.Scan(dest...) }

