// Service writes audit records to both PG (fast timeline) and MongoDB (searchable audit).
type Service struct {
	pool  *pgxpool.Pool
	mongo *smongo.Store
}

func New(pool *pgxpool.Pool, mongo *smongo.Store) *Service {
	return &Service{pool: pool, mongo: mongo}
}

// Record writes an audit entry. Returns the PG event id (timeline eventId).
func (s *Service) Record(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) (int64, error) {
	if details == nil {
		details = map[string]interface{}{}
	}
	detailsJSON, _ := json.Marshal(details)
	var eventID int64
	occurredAt := time.Now().UTC()
	err := s.pool.QueryRow(ctx,
		`INSERT INTO audit_events (actor_id, actor_role, action, entity_type, entity_id, success, occurred_at, details)
		 VALUES ($1,$2,$3,$4,$5,$6,$7,$8) RETURNING event_id`,
		nilIfEmpty(actorID), role, action, entityType, entityID, success, occurredAt, detailsJSON,
	).Scan(&eventID)
	if err != nil {
		return 0, fmt.Errorf("audit pg insert: %w", err)
	}
	// Mirror to MongoDB
	if s.mongo != nil {
		doc := smongo.AuditDoc{
			AuditID:    fmt.Sprintf("%d", eventID),
			ActorID:    actorID,
			Role:       role,
			Action:     action,
			EntityType: entityType,
			EntityID:   entityID,
			Success:    success,
			OccurredAt: occurredAt,
			Details:    details,
		}
		_, _ = s.mongo.DB.Collection(smongo.CollAudit).InsertOne(ctx, doc)
	}
	return eventID, nil
}

func nilIfEmpty(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

// Timeline returns ordered timeline entries for an entity from PG.
func (s *Service) Timeline(ctx context.Context, entityType, entityID string, limit int) ([]domain.TimelineEntry, error) {
	if limit <= 0 {
		limit = 100
	}
	rows, err := s.pool.Query(ctx,
		`SELECT event_id, COALESCE(actor_id::text,''), actor_role, action, entity_type, entity_id, success, occurred_at, details
		 FROM audit_events WHERE entity_type=$1 AND entity_id=$2 ORDER BY event_id ASC LIMIT $3`,
		entityType, entityID, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []domain.TimelineEntry
	for rows.Next() {
		var e domain.TimelineEntry
		var occurredAt time.Time
		var details []byte
		if err := rows.Scan(&e.EventID, &e.ActorID, &e.Role, &e.Action, &e.EntityType, &e.EntityID, &e.Success, &occurredAt, &details); err != nil {
