// Service manages durable realtime events (PG sequence + Mongo mirror) and an
// in-process pub/sub fan-out for WebSocket subscribers.
type Service struct {
	pool  *pgxpool.Pool
	mongo *smongo.Store
	mu    sync.RWMutex
	subs  map[int64]chan domain.RealtimeEvent // keyed by subscriber id
	nextSub int64
}

func New(pool *pgxpool.Pool, mongo *smongo.Store) *Service {
	return &Service{pool: pool, mongo: mongo, subs: map[int64]chan domain.RealtimeEvent{}}
}

// Publish appends a durable event and fans it out to subscribers.
func (s *Service) Publish(ctx context.Context, eventType, entityType, entityID string, payload map[string]interface{}) (domain.RealtimeEvent, error) {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	payloadJSON, _ := json.Marshal(payload)
	var id int64
	now := time.Now().UTC()
	err := s.pool.QueryRow(ctx,
		`INSERT INTO realtime_events (type, entity_type, entity_id, payload, created_at)
		 VALUES ($1,$2,$3,$4,$5) RETURNING event_id`,
		eventType, entityType, entityID, payloadJSON, now,
	).Scan(&id)
	if err != nil {
		return domain.RealtimeEvent{}, err
	}
	ev := domain.RealtimeEvent{
		ID:         id,
		Type:       eventType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  now.Format(time.RFC3339Nano),
	}
	if s.mongo != nil {
		doc := smongo.RealtimeDoc{
			Seq:        id,
			Type:       eventType,
			EntityType: entityType,
			EntityID:   entityID,
			Payload:    payload,
			CreatedAt:  now,
		}
		_, _ = s.mongo.DB.Collection(smongo.CollRealtime).InsertOne(ctx, doc)
	}
	s.fanout(ev)
	return ev, nil
}

func (s *Service) fanout(ev domain.RealtimeEvent) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	for _, ch := range s.subs {
		select {
		case ch <- ev:
		default:
		}
	}
}

// Subscribe registers a subscriber. Returns the channel and an unsubscribe func.
func (s *Service) Subscribe() (chan domain.RealtimeEvent, func()) {
	s.mu.Lock()
	id := s.nextSub
	s.nextSub++
	ch := make(chan domain.RealtimeEvent, 64)
	s.subs[id] = ch
	s.mu.Unlock()
	return ch, func() {
		s.mu.Lock()
		delete(s.subs, id)
		close(ch)
		s.mu.Unlock()
	}
}

// Replay returns durable events after the given sequence.
func (s *Service) Replay(ctx context.Context, since int64, limit int) ([]domain.RealtimeEvent, int64, error) {
	if limit <= 0 {
		limit = 200
	}
	rows, err := s.pool.Query(ctx,
		`SELECT event_id, type, entity_type, entity_id, payload, created_at
		 FROM realtime_events WHERE event_id > $1 ORDER BY event_id ASC LIMIT $2`, since, limit)
	if err != nil {
		return nil, since, err
	}
	defer rows.Close()
	var out []domain.RealtimeEvent
	cursor := since
	for rows.Next() {
		var e domain.RealtimeEvent
		var payload []byte
		var ct time.Time
		if err := rows.Scan(&e.ID, &e.Type, &e.EntityType, &e.EntityID, &payload, &ct); err != nil {
			return nil, cursor, err
		}
		e.CreatedAt = ct.UTC().Format(time.RFC3339Nano)
		if len(payload) > 0 {
			_ = json.Unmarshal(payload, &e.Payload)
		}
		if e.Payload == nil {
			e.Payload = map[string]interface{}{}
		}
		cursor = e.ID
		out = append(out, e)
	}
	return out, cursor, rows.Err()
}

// suppress unused import for bson in case of refactor
var _ = bson.D

