}

// Load builds a fresh network snapshot from the database and publishes it as a
// new complete version (keeping the previous complete version served in the meantime).
func (s *Service) Load(ctx context.Context) (*Snapshot, error) {
	net, accepted, activeCP, err := s.buildNetwork(ctx)
	if err != nil {
		return nil, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	s.networkRevision++
	version := s.networkRevision
	regions := make([]domain.ServiceabilityRegion, 0, activeCP)
	for _, loc := range net.Locations {
		if loc.Active && loc.CollectionPoint {
			regions = append(regions, domain.ServiceabilityRegion{
				LocationID: loc.LocationID, Name: loc.Name,
				Latitude: loc.Latitude, Longitude: loc.Longitude, CoverageKm: loc.CoverageKm,
			})
		}
	}
	snap := &Snapshot{
