package auth

import (
	"context"
	"net/http"
	"strings"
)

type ctxKey int

const (
	keyUser ctxKey = iota
	keyRole
	keyRequestID
)

// SessionUser holds the authenticated principal.
type SessionUser struct {
	UserID   string
	Username string
	Roles    []string
	ActiveRole string
}

// FromContext returns the authenticated user from context.
func FromContext(ctx context.Context) *SessionUser {
	if v, ok := ctx.Value(keyUser).(*SessionUser); ok {
		return v
	}
	return nil
}

// RoleFromContext returns the selected active role.
func RoleFromContext(ctx context.Context) string {
	if v, ok := ctx.Value(keyRole).(string); ok {
		return v
	}
	return ""
}

// WithUser sets the user in context.
func WithUser(ctx context.Context, u *SessionUser) context.Context {
	return context.WithValue(ctx, keyUser, u)
}

// WithRole sets the active role in context.
func WithRole(ctx context.Context, role string) context.Context {
	return context.WithValue(ctx, keyRole, role)
}

// ExtractBearer [REDACTED] the bearer [REDACTED] from the Authorization header.
func ExtractBearer(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if h == "" {
		return ""
	}
	if !strings.HasPrefix(h, "Bearer ") {
		return ""
	}
	return strings.TrimSpace(h[len("Bearer "):])
}

