func (a *App) CreateSampleType(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req createSampleTypeReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if isBlank(req.Name) || isBlank(req.ContainerType) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_handling_rule", "name and container required"))
		return
	}
	if req.TemperatureMinC > req.TemperatureMaxC {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_handling_rule", "temp min > max"))
		return
	}
	batching := true
	if req.BatchingAllowed != nil {
		batching = *req.BatchingAllowed
	}
	ctx := r.Context()
	var id string
	incArr := pgStringArray(req.IncompatibleSampleTypes)
	err = a.Pool.QueryRow(ctx,
		`INSERT INTO sample_types (name, qualified_collector_required, required_qualification, container_type,
		   temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed, incompatible_sample_types)
		 VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9::uuid[]) RETURNING sample_type_id`,
		req.Name, req.QualifiedCollectorRequired, nullStr(req.RequiredQualification), req.ContainerType,
		req.TemperatureMinC, req.TemperatureMaxC, req.RequiresCooledRoute, batching, incArr,
	).Scan(&id)
	if err != nil {
