func (a *App) CreateLocation(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req createLocationReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if isBlank(req.Name) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_coordinate", "name required"))
