	}
	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_coordinate", "invalid coordinate"))
		return
	}
	coverage := 5.0
	if req.CoverageKm != nil {
		coverage = *req.CoverageKm
	}
	if coverage <= 0 || coverage > 5 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_node_coverage", "coverage must be >0 and <=5"))
