	var fns funcStates
	if req.Functions != nil {
		fns, err = parseFunctions(req.Functions)
		if err != nil {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_location_function", err.Error()))
			return
		}
	}
	ct, err := a.Pool.Exec(ctx,
		`UPDATE locations SET name=$2, latitude=$3, longitude=$4, coverage_km=$5, handling_minutes=$6,
		  fn_collection_point=COALESCE($7, fn_collection_point),
		  fn_transfer_point=COALESCE($8, fn_transfer_point),
		  fn_hub=COALESCE($9, fn_hub),
		  fn_laboratory=COALESCE($10, fn_laboratory),
		  updated_at=now() WHERE location_id=$1`,
		req.LocationID, req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, coverage, handling,
		optBool(fns.collectionPoint), optBool(fns.transferPoint), optBool(fns.hub), optBool(fns.laboratory),
	)
	if err != nil {
		writeErr(w, err)
		return
	}
	if ct.RowsAffected() == 0 {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "location not found"))
		return
	}
	loc, _ := a.loadLocation(ctx, req.LocationID)
	a.record(ctx, u.UserID, role, "update_location", "location", req.LocationID, true, nil)
	a.Svc.Load(ctx)
	web.Data(w, http.StatusCreated, loc)
}

type funcStates struct {
	collectionPoint, transferPoint, hub, laboratory bool
}

func parseFunctions(fns []string) (funcStates, error) {
	var f funcStates
	if len(fns) == 0 {
		return f, errors.New("at least one function required")
	}
	for _, fn := range fns {
		switch fn {
		case "collection_point":
			f.collectionPoint = true
		case "transfer_point":
			f.transferPoint = true
		case "hub":
			f.hub = true
		case "laboratory":
			f.laboratory = true
		default:
			return f, errors.New("invalid location function: " + fn)
		}
	}
	return f, nil
}

func optBool(b bool) interface{} {
	return b
}

func (a *App) loadLocation(ctx context.Context, locID string) (domain.Location, error) {
	var loc domain.Location
	var lat, lon, coverage float64
	var handling int
	var active bool
	var cp, tp, hub, lab bool
	err := a.Pool.QueryRow(ctx,
		`SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active,
		        fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory
		 FROM locations WHERE location_id=$1`, locID).
		Scan(&loc.LocationID, &loc.Name, &lat, &lon, &coverage, &handling, &active, &cp, &tp, &hub, &lab)
	if err != nil {
		return loc, err
	}
	loc.Coordinate = domain.Coordinate{Latitude: lat, Longitude: lon}
	loc.CoverageKm = coverage
	loc.HandlingMinutes = handling
	loc.Active = active
	loc.Functions = domain.LocationFunctionStates{CollectionPoint: cp, TransferPoint: tp, Hub: hub, Laboratory: lab}
	return loc, nil
}

