// ---------- Sample types ----------

type sampleTypeView struct {
	SampleTypeID              string   `json:"sampleTypeId"`
	Name                      string   `json:"name"`
	QualifiedCollectorRequired bool    `json:"qualifiedCollectorRequired"`
	RequiredQualification     string   `json:"requiredQualification"`
	ContainerType             string   `json:"containerType"`
	TemperatureMinC           float64  `json:"temperatureMinC"`
	TemperatureMaxC           float64  `json:"temperatureMaxC"`
	IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
	RequiresCooledRoute       bool     `json:"requiresCooledRoute"`
	BatchingAllowed           bool     `json:"batchingAllowed"`
}

type createSampleTypeReq struct {
	Name                      string   `json:"name"`
	QualifiedCollectorRequired bool     `json:"qualifiedCollectorRequired"`
	RequiredQualification     string   `json:"requiredQualification"`
	ContainerType             string   `json:"containerType"`
	TemperatureMinC           float64  `json:"temperatureMinC"`
	TemperatureMaxC           float64  `json:"temperatureMaxC"`
	IncompatibleSampleTypes   []string `json:"incompatibleSampleTypes"`
	RequiresCooledRoute       bool     `json:"requiresCooledRoute"`
	BatchingAllowed           *bool    `json:"batchingAllowed"`
}

func (a *App) CreateSampleType(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req createSampleTypeReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if isBlank(req.Name) || isBlank(req.ContainerType) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_handling_rule", "name and container required"))
		return
	}
	if req.TemperatureMinC > req.TemperatureMaxC {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_handling_rule", "temp min > max"))
		return
	}
	batching := true
	if req.BatchingAllowed != nil {
		batching = *req.BatchingAllowed
	}
	ctx := r.Context()
	var id string
	incArr := pgStringArray(req.IncompatibleSampleTypes)
	err = a.Pool.QueryRow(ctx,
		`INSERT INTO sample_types (name, qualified_collector_required, required_qualification, container_type,
		   temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed, incompatible_sample_types)
		 VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9::uuid[]) RETURNING sample_type_id`,
		req.Name, req.QualifiedCollectorRequired, nullStr(req.RequiredQualification), req.ContainerType,
		req.TemperatureMinC, req.TemperatureMaxC, req.RequiresCooledRoute, batching, incArr,
	).Scan(&id)
	if err != nil {
		writeErr(w, err)
		return
	}
	view, _ := a.loadSampleType(ctx, id)
	a.record(ctx, u.UserID, role, "create_sample_type", "sample_type", id, true, map[string]interface{}{"name": req.Name})
	web.Data(w, http.StatusCreated, view)
}

type updateSampleTypeReq struct {
	SampleTypeID              string   `json:"sampleTypeId"`
	QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
	RequiredQualification     *string   `json:"requiredQualification"`
	ContainerType             string   `json:"containerType"`
	TemperatureMinC           *float64  `json:"temperatureMinC"`
	TemperatureMaxC           *float64  `json:"temperatureMaxC"`
	IncompatibleSampleTypes   []string  `json:"incompatibleSampleTypes"`
	RequiresCooledRoute      *bool     `json:"requiresCooledRoute"`
	BatchingAllowed          *bool     `json:"batchingAllowed"`
}

func (a *App) UpdateSampleType(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req updateSampleTypeReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if isBlank(req.SampleTypeID) || isBlank(req.ContainerType) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_handling_rule", "sampleTypeId and container required"))
		return
	}
	ctx := r.Context()
	minC := req.TemperatureMinC
	maxC := req.TemperatureMaxC
	if minC != nil && maxC != nil && *minC > *maxC {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_handling_rule", "temp min > max"))
		return
	}
	ct, err := a.Pool.Exec(ctx,
		`UPDATE sample_types SET container_type=$2,
		   qualified_collector_required=COALESCE($3, qualified_collector_required),
		   required_qualification=COALESCE($4, required_qualification),
		   temperature_min_c=COALESCE($5, temperature_min_c),
		   temperature_max_c=COALESCE($6, temperature_max_c),
		   requires_cooled_route=COALESCE($7, requires_cooled_route),
		   batching_allowed=COALESCE($8, batching_allowed),
		   incompatible_sample_types=COALESCE($9::uuid[], incompatible_sample_types),
		   updated_at=now() WHERE sample_type_id=$1`,
		req.SampleTypeID, req.ContainerType, req.QualifiedCollectorRequired, req.RequiredQualification,
		minC, maxC, req.RequiresCooledRoute, req.BatchingAllowed, pgStringArray(req.IncompatibleSampleTypes),
	)
	if err != nil {
		writeErr(w, err)
		return
	}
	if ct.RowsAffected() == 0 {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "sample type not found"))
		return
	}
	view, _ := a.loadSampleType(ctx, req.SampleTypeID)
	a.record(ctx, u.UserID, role, "update_sample_type", "sample_type", req.SampleTypeID, true, nil)
	web.Data(w, http.StatusCreated, view)
}

func (a *App) loadSampleType(ctx context.Context, id string) (sampleTypeView, error) {
	var v sampleTypeView
	var reqQual *string
	var inc []string
	err := a.Pool.QueryRow(ctx,
		`SELECT sample_type_id, name, qualified_collector_required, required_qualification, container_type,
		   temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed, incompatible_sample_types
		 FROM sample_types WHERE sample_type_id=$1`, id).
		Scan(&v.SampleTypeID, &v.Name, &v.QualifiedCollectorRequired, &reqQual, &v.ContainerType,
			&v.TemperatureMinC, &v.TemperatureMaxC, &v.RequiresCooledRoute, &v.BatchingAllowed, &inc)
	if err != nil {
		return v, err
	}
	if reqQual != nil {
		v.RequiredQualification = *reqQual
	}
	v.IncompatibleSampleTypes = strArr(inc)
	return v, nil
}

// ---------- Capacity ----------

type configureCapacityReq struct {
	ResourceID           string `json:"resourceId"`
	CapacityUnits        *int   `json:"capacityUnits"`
	CooledCapacityUnits  *int   `json:"cooledCapacityUnits"`
}

func (a *App) ConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleAdministrator, auth.RoleNodeHandler, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req configureCapacityReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if isBlank(req.ResourceID) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_capacity", "resourceId required"))
		return
	}
	// Node handler / lab team can only configure their own node/lab capacity.
	ctx := r.Context()
	if role == auth.RoleNodeHandler || role == auth.RoleLaboratoryTeam {
		// ensure resource is the assigned location
		var assignedID *string
		_ = a.Pool.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE user_id=$1`, u.UserID).Scan(&assignedID)
		if assignedID == nil || *assignedID != req.ResourceID {
			writeErr(w, apiErr(http.StatusForbidden, "forbidden", "cannot configure this resource"))
			return
		}
	}
	cap := 0
	if req.CapacityUnits != nil {
		cap = *req.CapacityUnits
	}
	if cap < 0 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_capacity", "capacity must be >=0"))
		return
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	// ensure not below reserved.
	var resCap, resCooled int
	_ = a.Pool.QueryRow(ctx, `SELECT reserved_units, cooled_reserved_units FROM capacities WHERE resource_id=$1`, req.ResourceID).Scan(&resCap, &resCooled)
	if cap < resCap || cooled < resCooled {
		writeErr(w, apiErr(http.StatusConflict, "capacity_reserved", "cannot set below reserved"))
		return
	}
	// upsert capacity row with resource_kind detection
	kind := "location"
	var exists int
	_ = a.Pool.QueryRow(ctx, `SELECT count(*) FROM locations WHERE location_id=$1`, req.ResourceID).Scan(&exists)
	if exists == 0 {
		kind = "connection"
	}
	_, err = a.Pool.Exec(ctx,
		`INSERT INTO capacities (resource_id, resource_kind, capacity_units, cooled_capacity_units, updated_at)
		 VALUES ($1,$2,$3,$4,now())
		 ON CONFLICT (resource_id) DO UPDATE SET capacity_units=$3, cooled_capacity_units=$4, updated_at=now()`,
		req.ResourceID, kind, cap, cooled)
	if err != nil {
		writeErr(w, err)
		return
	}
	a.record(ctx, u.UserID, role, "configure_capacity", "capacity", req.ResourceID, true, map[string]interface{}{"capacityUnits": cap, "cooledCapacityUnits": cooled})
	a.Svc.Load(ctx)
	web.Data(w, http.StatusOK, map[string]interface{}{"resourceId": req.ResourceID, "capacityUnits": cap, "cooledCapacityUnits": cooled})
}

// ---------- Laboratory acceptance ----------

func (a *App) ConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleAdministrator, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      bool   `json:"accepts"`
	}
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if isBlank(req.LaboratoryID) || isBlank(req.SampleTypeID) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_acceptance", "labId and sampleTypeId required"))
		return
	}
	ctx := r.Context()
	if role == auth.RoleLaboratoryTeam {
		var assignedID *string
		_ = a.Pool.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE user_id=$1`, u.UserID).Scan(&assignedID)
		if assignedID == nil || *assignedID != req.LaboratoryID {
			writeErr(w, apiErr(http.StatusForbidden, "forbidden", "not your laboratory"))
			return
		}
	}
	var accID string
	err = a.Pool.QueryRow(ctx,
		`INSERT INTO laboratory_acceptance (laboratory_id, sample_type_id, accepts)
		 VALUES ($1,$2,$3)
		 ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=$3, updated_at=now()
		 RETURNING acceptance_id`,
		req.LaboratoryID, req.SampleTypeID, req.Accepts).Scan(&accID)
	if err != nil {
		writeErr(w, err)
		return
	}
	a.record(ctx, u.UserID, role, "configure_laboratory_acceptance", "laboratory", req.LaboratoryID, true, map[string]interface{}{"sampleTypeId": req.SampleTypeID, "accepts": req.Accepts})
	a.Svc.Load(ctx)
	web.Data(w, http.StatusOK, map[string]interface{}{"acceptanceId": accID, "accepts": req.Accepts})
}

// ---------- Worker availability ----------

func (a *App) SetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleAdministrator, auth.RoleDispatcher,
		auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits int    `json:"capacityUnits"`
	}
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if isBlank(req.WorkerID) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_capacity", "workerId required"))
		return
	}
	if req.CapacityUnits < 0 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_capacity", "capacity must be >=0"))
		return
	}
	// Workers may only set their own availability; admin/dispatcher may set any.
	if (role == auth.RoleCollectionProfessional || role == auth.RoleDeliveryPartner || role == auth.RoleNodeHandler || role == auth.RoleLaboratoryTeam) && req.WorkerID != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "forbidden", "can only set own availability"))
		return
	}
	ctx := r.Context()
	ct, err := a.Pool.Exec(ctx,
		`INSERT INTO worker_availability (user_id, available, capacity_units, updated_at)
		 VALUES ($1,$2,$3,now())
		 ON CONFLICT (user_id) DO UPDATE SET available=$2, capacity_units=$3, updated_at=now()`,
		req.WorkerID, req.Available, req.CapacityUnits)
	if err != nil {
		writeErr(w, err)
		return
	}
	_ = ct
	a.record(ctx, u.UserID, role, "set_worker_availability", "worker", req.WorkerID, true, map[string]interface{}{"available": req.Available, "capacityUnits": req.CapacityUnits})
	web.Data(w, http.StatusOK, map[string]interface{}{"workerId": req.WorkerID, "available": req.Available, "capacityUnits": req.CapacityUnits})
}

