action.file_text:
package api

import (
	"context"
	"sort"
	"time"

	"github.com/google/uuid"

	"lablogistics/internal/auth"
)

// offerAssignments offers each 'offered' assignment in a journey to the single
// most suitable eligible worker (one at a time). Eligibility mirrors the role:
//   collection -> collection_professional with matching qualification/cert
//   transport   -> delivery_partner
//   node        -> node_handler assigned to that node
//   laboratory  -> laboratory_team assigned to that lab
func (a *App) offerAssignments(ctx context.Context, journeyID string) {
	rows, err := a.Pool.Query(ctx,
		`SELECT assignment_id, kind, from_location_id, to_location_id, sample_id
		 FROM assignments WHERE journey_id=$1 AND status='offered' ORDER BY sequence ASC`, journeyID)
	if err != nil {
		return
	}
	defer rows.Close()
	type asg struct {
		ID, kind, from, to, sample string
	}
	var asgs []asg
	for rows.Next() {
		var x asg
		var from, to *string
		if rows.Scan(&x.ID, &x.kind, &from, &to, &x.sample) != nil {
			continue
		}
		if from != nil {
			x.from = *from
		}
		if to != nil {
			x.to = *to
		}
		asgs = append(asgs, x)
	}
	for _, x := range asgs {
		a.offerOne(ctx, x.ID, x.kind, x.from, x.to, x.sample)
	}
}

func (a *App) offerOne(ctx context.Context, asgID, kind, fromLoc, toLoc, sampleID string) {
	var sampleTypeID string
	_ = a.Pool.QueryRow(ctx, `SELECT sample_type_id FROM samples WHERE sample_id=$1`, sampleID).Scan(&sampleTypeID)
	st, _ := a.loadSampleType(ctx, sampleTypeID)

	// Determine target worker pool.
