		return
	}

	candidates := a.eligibleWorkers(ctx, role, kind, fromLoc, toLoc, st)
	if len(candidates) == 0 {
		// No qualified worker available. Flag as exception if a collection requires
		// qualification and none becomes available (best-effort: mark assignment
		// waiting; the sample gets flagged via exception path when deadline nears).
		return
	}
	// Sort by fairness: current workload (assignment count) asc, then recent offers.
	sort.Slice(candidates, func(i, j int) bool {
		if candidates[i].assignmentCount != candidates[j].assignmentCount {
			return candidates[i].assignmentCount < candidates[j].assignmentCount
		}
		return candidates[i].userID < candidates[j].userID
	})
	worker := candidates[0]
	// Set the assignment's offered_to_worker_id and create an offer row.
	exp := time.Now().Add(time.Duration(a.Cfg.OfferTimeoutSec) * time.Second)
	_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET offered_to_worker_id=$2, offer_expires_at=$3 WHERE assignment_id=$1`, asgID, worker.userID, exp)
	_, _ = a.Pool.Exec(ctx,
		`INSERT INTO assignment_offers (assignment_id, worker_id, status, offered_at, expires_at)
		 VALUES ($1,$2,'pending',now(),$3) ON CONFLICT DO NOTHING`, asgID, worker.userID, exp)
	a.record(ctx, worker.userID, role, "offer_assignment", "assignment", asgID, true, map[string]interface{}{"workerId": worker.userID})
	a.emit(ctx, "assignment.offered", "assignment", asgID, map[string]interface{}{"workerId": worker.userID, "kind": kind})
}

type workerCand struct {
	userID          string
	assignmentCount  int
}

func (a *App) eligibleWorkers(ctx context.Context, role, kind, fromLoc, toLoc string, st sampleTypeView) []workerCand {
	// Base: active users holding the role.
	rows, err := a.Pool.Query(ctx,
		`SELECT u.user_id FROM users u WHERE u.active=true AND $1 = ANY(u.roles)`, role)
	if err != nil {
		return nil
	}
	defer rows.Close()
	var ids []string
	for rows.Next() {
		var id string
		if rows.Scan(&id) == nil {
			ids = append(ids, id)
		}
	}
	var out []workerCand
	for _, id := range ids {
		// availability
		var avail bool
		var cap int
		err := a.Pool.QueryRow(ctx, `SELECT available, capacity_units FROM worker_availability WHERE user_id=$1`, id).Scan(&avail, &cap)
		if err != nil {
			avail = true
			cap = 4
		}
		if !avail {
			continue
		}
		// node/lab assignment restriction
		if role == auth.RoleNodeHandler {
			var assigned *string
			_ = a.Pool.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE user_id=$1`, id).Scan(&assigned)
			if assigned == nil || (*assigned != fromLoc && *assigned != toLoc) {
				continue
			}
		}
		if role == auth.RoleLaboratoryTeam {
			var assigned *string
			_ = a.Pool.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE user_id=$1`, id).Scan(&assigned)
			if assigned == nil || (*assigned != fromLoc && *assigned != toLoc) {
				continue
			}
		}
		// qualification/cert for collection of qualified sample type
		if role == auth.RoleCollectionProfessional && kind == "collection" && st.QualifiedCollectorRequired && st.RequiredQualification != "" {
			if !a.hasActiveCert(ctx, id, st.RequiredQualification) {
				continue
			}
		}
		// workload count
		var cnt int
		_ = a.Pool.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','active')`, id).Scan(&cnt)
		if cnt >= cap {
			continue
		}
		out = append(out, workerCand{userID: id, assignmentCount: cnt})
	}
	return out
}

func (a *App) hasActiveCert(ctx context.Context, userID, code string) bool {
	var c int
	_ = a.Pool.QueryRow(ctx, `SELECT count(*) FROM user_certifications WHERE user_id=$1 AND code=$2 AND active=true`, userID, code).Scan(&c)
	// also accept qualifications list match
	if c == 0 {
		var q []string
		_ = a.Pool.QueryRow(ctx, `SELECT qualifications FROM users WHERE user_id=$1`, userID).Scan(&q)
		for _, x := range q {
			if x == code {
				return true
			}
		}
		return false
	}
	return true
}

// reoffer moves an assignment to the next eligible worker (after decline/timeout).
func (a *App) reoffer(ctx context.Context, asgID string) {
	var kind, from, to, sample string
	err := a.Pool.QueryRow(ctx, `SELECT kind, COALESCE(from_location_id::text,''), COALESCE(to_location_id::text,''), sample_id FROM assignments WHERE assignment_id=$1`, asgID).
		Scan(&kind, &from, &to, &sample)
	if err != nil {
		return
	}
	// bump decline count
	_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET decline_count=decline_count+1, offered_to_worker_id=NULL, offer_expires_at=NULL WHERE assignment_id=$1`, asgID)
	a.offerOne(ctx, asgID, kind, from, to, sample)
}

// offerExpireCheck reoffers assignments whose offers expired without response.
func (a *App) offerExpireLoop(ctx context.Context) {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			rows, err := a.Pool.Query(ctx,
				`SELECT assignment_id FROM assignments WHERE status='offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < now()`)
			if err != nil {
				continue
			}
			var ids []string
			for rows.Next() {
				var id string
				rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				a.reoffer(ctx, id)
			}
		}
	}
}

var _ = uuid.NewString

