package api

import (
	"context"
	"errors"
	"net/http"
	"time"

	"github.com/google/uuid"

	"lablogistics/internal/auth"
	"lablogistics/internal/domain"
	"lablogistics/internal/web"
)

// ---------- Accept assignment ----------

type acceptReq struct {
	AssignmentID  string `json:"assignmentId"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (a *App) AcceptAssignment(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req acceptReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.AssignmentID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "assignmentId and idempotencyKey required"))
		return
	}
	ctx := r.Context()
	var kind, status, offeredTo string
	var journeyID, sampleID string
	err = a.Pool.QueryRow(ctx,
		`SELECT kind, status, COALESCE(offered_to_worker_id::text,''), journey_id, sample_id
		 FROM assignments WHERE assignment_id=$1`, req.AssignmentID).Scan(&kind, &status, &offeredTo, &journeyID, &sampleID)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "assignment not found"))
		return
	}
	if offeredTo != u.UserID {
		// assignment cannot be accepted by someone other than the offered worker
		writeErr(w, apiErr(http.StatusForbidden, "ineligible_worker", "assignment not offered to you"))
		return
	}
	if status != "offered" {
		if status == "accepted" || status == "active" || status == "completed" {
			writeErr(w, apiErr(http.StatusConflict, "assignment_taken", "assignment already taken"))
			return
		}
		writeErr(w, apiErr(http.StatusConflict, "assignment_inactive", "assignment not offered"))
		return
	}
	// eligibility recheck
	if !a.workerEligibleForAssignment(ctx, u.UserID, req.AssignmentID, kind) {
		writeErr(w, apiErr(http.StatusForbidden, "ineligible_worker", "not eligible"))
		return
	}
	// update assignment
	ct, err := a.Pool.Exec(ctx, `UPDATE assignments SET status='accepted', worker_id=$2, updated_at=now() WHERE assignment_id=$1 AND status='offered'`, req.AssignmentID, u.UserID)
	if err != nil {
		writeErr(w, err)
		return
	}
	if ct.RowsAffected() == 0 {
		writeErr(w, apiErr(http.StatusConflict, "offer_not_available", "offer no longer available"))
		return
	}
	_, _ = a.Pool.Exec(ctx, `UPDATE assignment_offers SET status='accepted', responded_at=now() WHERE assignment_id=$1 AND worker_id=$2`, req.AssignmentID, u.UserID)
	// for collection assignment, set current holder to collector on accept (sample holder becomes collector once they hold it; actual custody after sealing)
	a.record(ctx, u.UserID, role, "accept_assignment", "assignment", req.AssignmentID, true, map[string]interface{}{"kind": kind})
	a.emit(ctx, "assignment.accepted", "assignment", req.AssignmentID, map[string]interface{}{"workerId": u.UserID, "sampleId": sampleID})
	web.Data(w, http.StatusCreated, map[string]interface{}{"assignmentId": req.AssignmentID, "workerId": u.UserID, "status": "accepted"})
}

func (a *App) workerEligibleForAssignment(ctx context.Context, userID, asgID, kind string) bool {
	var from, to *string
	var sampleID string
	_ = a.Pool.QueryRow(ctx, `SELECT COALESCE(from_location_id::text,''), COALESCE(to_location_id::text,''), sample_id FROM assignments WHERE assignment_id=$1`, asgID).Scan(&from, &to, &sampleID)
	st, _ := a.loadSampleType(ctx, sampleIDFromAssignment(ctx, a, asgID))
	switch kind {
	case "collection":
		if st.QualifiedCollectorRequired && st.RequiredQualification != "" {
			return a.hasActiveCert(ctx, userID, st.RequiredQualification)
		}
		return true
	case "transport":
		return true
	case "node":
		var assigned *string
		_ = a.Pool.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE user_id=$1`, userID).Scan(&assigned)
		if assigned == nil {
			return false
		}
		if from != nil && *from == *assigned {
			return true
		}
		if to != nil && *to == *assigned {
			return true
		}
		return false
	case "laboratory":
		var assigned *string
		_ = a.Pool.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE user_id=$1`, userID).Scan(&assigned)
		if assigned == nil {
			return false
		}
		if to != nil && *to == *assigned {
			return true
		}
		if from != nil && *from == *assigned {
			return true
		}
		return false
	}
	return false
}

func sampleIDFromAssignment(ctx context.Context, a *App, asgID string) string {
	var s string
	_ = a.Pool.QueryRow(ctx, `SELECT sample_id FROM assignments WHERE assignment_id=$1`, asgID).Scan(&s)
	return s
}

// ---------- Decline assignment ----------

type declineReq struct {
	AssignmentID   string `json:"assignmentId"`
	Reason         string `json:"reason"`
	DeclinedAt     string `json:"declinedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (a *App) DeclineAssignment(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req declineReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.AssignmentID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	declinedAt := time.Now().UTC()
	if req.DeclinedAt != "" {
		t, perr := parseTime(req.DeclinedAt)
		if perr != nil {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid declinedAt"))
			return
		}
		declinedAt = t
	}
	ctx := r.Context()
	var status, offeredTo string
	err = a.Pool.QueryRow(ctx, `SELECT status, COALESCE(offered_to_worker_id::text,'') FROM assignments WHERE assignment_id=$1`, req.AssignmentID).Scan(&status, &offeredTo)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "assignment not found"))
		return
	}
	if offeredTo != u.UserID {
		writeErr(w, apiErr(http.StatusConflict, "offer_not_available", "not offered to you"))
		return
	}
	_, _ = a.Pool.Exec(ctx, `UPDATE assignment_offers SET status='declined', responded_at=now() WHERE assignment_id=$1 AND worker_id=$2`, req.AssignmentID, u.UserID)
	// record decline and reoffer to next
	a.record(ctx, u.UserID, role, "decline_assignment", "assignment", req.AssignmentID, true, map[string]interface{}{"reason": req.Reason})

	// find next eligible worker
	nextID := a.nextEligibleWorker(ctx, req.AssignmentID, u.UserID)
	var reofferedTo string
	if nextID != "" {
		exp := time.Now().Add(time.Duration(a.Cfg.OfferTimeoutSec) * time.Second)
		_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET offered_to_worker_id=$2, offer_expires_at=$3, decline_count=decline_count+1 WHERE assignment_id=$1`, req.AssignmentID, nextID, exp)
		_, _ = a.Pool.Exec(ctx, `INSERT INTO assignment_offers (assignment_id, worker_id, status, offered_at, expires_at) VALUES ($1,$2,'pending',now(),$3) ON CONFLICT DO NOTHING`, req.AssignmentID, nextID, exp)
		reofferedTo = nextID
		a.record(ctx, nextID, role, "offer_assignment", "assignment", req.AssignmentID, true, nil)
		a.emit(ctx, "assignment.offered", "assignment", req.AssignmentID, map[string]interface{}{"workerId": nextID})
	} else {
		_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET offered_to_worker_id=NULL, offer_expires_at=NULL, decline_count=decline_count+1 WHERE assignment_id=$1`, req.AssignmentID)
	}
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"assignmentId": req.AssignmentID, "status": "pending", "declinedBy": u.UserID,
		"declinedAt": fmtTimeT(declinedAt), "reofferedTo": reofferedTo,
	})
}

func (a *App) nextEligibleWorker(ctx context.Context, asgID, excludeID string) string {
	var kind, from, to, sample string
	_ = a.Pool.QueryRow(ctx, `SELECT kind, COALESCE(from_location_id::text,''), COALESCE(to_location_id::text,''), sample_id FROM assignments WHERE assignment_id=$1`, asgID).Scan(&kind, &from, &to, &sample)
	st, _ := a.loadSampleType(ctx, sampleIDFromAssignment(ctx, a, asgID))
	cands := a.eligibleWorkers(ctx, roleForKind(kind), kind, from, to, st)
	for _, c := range cands {
		if c.userID == excludeID {
			continue
		}
		return c.userID
	}
	return ""
}

func roleForKind(kind string) string {
	switch kind {
	case "collection":
		return auth.RoleCollectionProfessional
	case "transport":
		return auth.RoleDeliveryPartner
	case "node":
		return auth.RoleNodeHandler
	case "laboratory":
		return auth.RoleLaboratoryTeam
	}
	return ""
}

// ---------- Update assignment progress ----------

type progressReq struct {
	AssignmentID   string `json:"assignmentId"`
	Status         string `json:"status"`
	OccurredAt     string `json:"occurredAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (a *App) UpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req progressReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.AssignmentID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	occurredAt, err := parseTime(req.OccurredAt)
	if err != nil || occurredAt.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid occurredAt"))
		return
	}
	valid := map[string]bool{"at_pickup": true, "picked_up": true, "in_transit": true, "arrived": true, "delivered": true, "in_progress": true, "completed": true}
	if !valid[req.Status] {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_json", "invalid status"))
		return
	}
	ctx := r.Context()
	var kind, status, workerID, sampleID string
	err = a.Pool.QueryRow(ctx, `SELECT kind, status, COALESCE(worker_id::text,''), sample_id FROM assignments WHERE assignment_id=$1`, req.AssignmentID).Scan(&kind, &status, &workerID, &sampleID)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "assignment not found"))
		return
	}
	if workerID != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "ineligible_worker", "not your assignment"))
		return
	}
	if status == "completed" || status == "cancelled" || status == "expired" {
		writeErr(w, apiErr(http.StatusConflict, "assignment_inactive", "assignment inactive"))
		return
	}
	// transport legs require collection first (custody).
	if kind == "transport" {
		var sealed bool
		_ = a.Pool.QueryRow(ctx, `SELECT sealed FROM samples WHERE sample_id=$1`, sampleID).Scan(&sealed)
		if !sealed && (req.Status == "picked_up" || req.Status == "in_transit" || req.Status == "delivered" || req.Status == "completed") {
			writeErr(w, apiErr(http.StatusConflict, "collection_required", "sample must be collected and sealed first"))
			return
		}
	}
	// deadline check
	var deadline time.Time
	_ = a.Pool.QueryRow(ctx, `SELECT delivery_deadline FROM samples WHERE sample_id=$1`, sampleID).Scan(&deadline)
	if !deadline.IsZero() && occurredAt.After(deadline) && req.Status == "delivered" {
		writeErr(w, apiErr(http.StatusConflict, "delivery_deadline_exceeded", "past deadline"))
		return
	}
	newStatus := req.Status
	if req.Status == "completed" {
		newStatus = "completed"
		_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=$2 WHERE assignment_id=$1`, req.AssignmentID, occurredAt)
		// mark stop completed if applicable
		a.completeStopFor(ctx, req.AssignmentID, occurredAt)
	} else {
		mapped := "active"
		if req.Status == "in_transit" || req.Status == "picked_up" || req.Status == "arrived" || req.Status == "in_progress" || req.Status == "at_pickup" {
			mapped = "active"
		}
		_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET status=$2 WHERE assignment_id=$1`, req.AssignmentID, mapped)
	}
	a.record(ctx, u.UserID, role, "update_assignment_progress", "assignment", req.AssignmentID, true, map[string]interface{}{"status": newStatus})
	a.emit(ctx, "assignment.progress", "assignment", req.AssignmentID, map[string]interface{}{"status": newStatus, "sampleId": sampleID})
	web.Data(w, http.StatusCreated, map[string]interface{}{"assignmentId": req.AssignmentID, "sampleId": sampleID, "status": newStatus})
}

func (a *App) completeStopFor(ctx context.Context, asgID string, at time.Time) {
	var journeyID, toLoc *string
	_ = a.Pool.QueryRow(ctx, `SELECT journey_id, to_location_id::text FROM assignments WHERE assignment_id=$1`, asgID).Scan(&journeyID, &toLoc)
	if journeyID == nil || toLoc == nil {
		return
	}
	_, _ = a.Pool.Exec(ctx, `UPDATE journey_stops SET completed_at=$3 WHERE journey_id=$1 AND location_id=$2 AND completed_at IS NULL`, *journeyID, *toLoc, at)
}

// ---------- Collect and seal ----------

type collectSealReq struct {
	SampleID             string  `json:"sampleId"`
	AssignmentID         string  `json:"assignmentId"`
	CollectedAt          string  `json:"collectedAt"`
	ContainerType        string  `json:"containerType"`
	ObservedTemperatureC float64 `json:"observedTemperatureC"`
	IdempotencyKey       string  `json:"idempotencyKey"`
}

func (a *App) CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleCollectionProfessional)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req collectSealReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.SampleID == "" || req.AssignmentID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	collectedAt, err := parseTime(req.CollectedAt)
	if err != nil || collectedAt.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid collectedAt"))
		return
	}
	ctx := r.Context()
	var kind, status, workerID, sampleID string
	var journeyID *string
	err = a.Pool.QueryRow(ctx, `SELECT kind, status, COALESCE(worker_id::text,''), sample_id, journey_id::text FROM assignments WHERE assignment_id=$1`, req.AssignmentID).Scan(&kind, &status, &workerID, &sampleID, &journeyID)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "assignment not found"))
		return
	}
	if sampleID != req.SampleID {
		writeErr(w, apiErr(http.StatusConflict, "invalid_sample_state", "assignment/sample mismatch"))
		return
	}
	if kind != "collection" {
		writeErr(w, apiErr(http.StatusConflict, "collection_not_ready", "not a collection assignment"))
		return
	}
	if workerID != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "forbidden", "not your assignment"))
		return
	}
	if status != "accepted" && status != "active" {
		writeErr(w, apiErr(http.StatusConflict, "assignment_inactive", "assignment not active"))
		return
	}
	// collection window check
	var earliest, latest *time.Time
	_ = a.Pool.QueryRow(ctx, `SELECT earliest_collection_at, latest_collection_at FROM samples WHERE sample_id=$1`, req.SampleID).Scan(&earliest, &latest)
	if latest != nil && collectedAt.After(*latest) {
		writeErr(w, apiErr(http.StatusConflict, "outside_collection_window", "collected after latest collection window"))
		return
	}
	if earliest != nil && collectedAt.Before(*earliest) {
		writeErr(w, apiErr(http.StatusConflict, "invalid_collection_time", "collected before earliest collection window"))
		return
	}
	// certification active check
	var st sampleTypeView
	st, _ = a.loadSampleType(ctx, sampleIDFromAssignment(ctx, a, req.AssignmentID))
	if st.QualifiedCollectorRequired && st.RequiredQualification != "" {
		if !a.hasActiveCert(ctx, u.UserID, st.RequiredQualification) {
			writeErr(w, apiErr(http.StatusConflict, "certification_inactive", "certification inactive"))
			return
		}
	}
	// handling compliance
	compliant := true
	if req.ContainerType != "" && st.ContainerType != "" && req.ContainerType != st.ContainerType {
		// allow observed container to differ; but mark non-compliant if outside temp range
	}
	if req.ObservedTemperatureC < st.TemperatureMinC || req.ObservedTemperatureC > st.TemperatureMaxC {
		compliant = false
	}
	if !compliant {
		// per contract, handling_noncompliant is a 400. We still seal but flag.
		writeErr(w, apiErr(http.StatusBadRequest, "handling_noncompliant", "observed conditions outside required range"))
		return
	}
	_, _ = a.Pool.Exec(ctx, `UPDATE samples SET status='sealed', sealed=true, sealed_at=$2, sealed_by=$3, current_holder_id=$3, container_type=$4, updated_at=now() WHERE sample_id=$1`, req.SampleID, collectedAt, u.UserID, req.ContainerType)
	_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=$2 WHERE assignment_id=$1`, req.AssignmentID, collectedAt)
	// mark pickup stop completed
	if journeyID != nil {
		_, _ = a.Pool.Exec(ctx, `UPDATE journey_stops SET completed_at=$3 WHERE journey_id=$1 AND stop_type='pickup' AND completed_at IS NULL`, *journeyID, req.SampleID, collectedAt)
	}
	a.record(ctx, u.UserID, role, "collect_and_seal_sample", "sample", req.SampleID, true, map[string]interface{}{"handlingCompliant": compliant})
	a.emit(ctx, "sample.sealed", "sample", req.SampleID, map[string]interface{}{"holderId": u.UserID})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"sampleId": req.SampleID, "status": "sealed", "currentHolderId": u.UserID,
		"sealedAt": fmtTimeT(collectedAt), "handlingCompliant": compliant,
	})
}

// ---------- Record worker location ----------

type recordLocationReq struct {
	AssignmentID string            `json:"assignmentId"`
	Coordinate   domain.Coordinate `json:"coordinate"`
	Sequence     int               `json:"sequence"`
	RecordedAt   string            `json:"recordedAt"`
}

func (a *App) RecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req recordLocationReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.AssignmentID == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_json", "assignmentId required"))
		return
	}
	if req.Sequence < 1 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_sequence", "sequence must be >=1"))
		return
	}
	recordedAt, err := parseTime(req.RecordedAt)
	if err != nil || recordedAt.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid recordedAt"))
		return
	}
	ctx := r.Context()
	var workerID string
	err = a.Pool.QueryRow(ctx, `SELECT COALESCE(worker_id::text,'') FROM assignments WHERE assignment_id=$1`, req.AssignmentID).Scan(&workerID)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "assignment not found"))
		return
	}
	if workerID != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "forbidden", "not your assignment"))
		return
	}
	// insert or update by (user, sequence); reject stale (lower sequence than max)
	var maxSeq int
	_ = a.Pool.QueryRow(ctx, `SELECT COALESCE(MAX(sequence),0) FROM worker_locations WHERE user_id=$1`, u.UserID).Scan(&maxSeq)
	if req.Sequence <= maxSeq {
		writeErr(w, apiErr(http.StatusConflict, "stale_location", "stale location sequence"))
		return
	}
	_, err = a.Pool.Exec(ctx,
		`INSERT INTO worker_locations (user_id, assignment_id, latitude, longitude, sequence, recorded_at, recorded_at_epoch)
		 VALUES ($1,$2,$3,$4,$5,$6,$7)`,
		u.UserID, req.AssignmentID, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, recordedAt, recordedAt.UnixNano())
	if err != nil {
		writeErr(w, err)
		return
	}
	// update sample latest location (the assignment's sample)
	var sampleID string
	_ = a.Pool.QueryRow(ctx, `SELECT sample_id FROM assignments WHERE assignment_id=$1`, req.AssignmentID).Scan(&sampleID)
	if sampleID != "" {
		_, _ = a.Pool.Exec(ctx, `UPDATE samples SET latest_latitude=$2, latest_longitude=$3, location_recorded_at=$4 WHERE sample_id=$1`, sampleID, req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt)
	}
	a.record(ctx, u.UserID, role, "record_worker_location", "assignment", req.AssignmentID, true, nil)
	a.emit(ctx, "worker.location", "worker", u.UserID, map[string]interface{}{"assignmentId": req.AssignmentID, "coordinate": req.Coordinate})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"assignmentId": req.AssignmentID, "coordinate": req.Coordinate,
		"sequence": req.Sequence, "recordedAt": fmtTimeT(recordedAt),
	})
}

var _ = errors.New
var _ = uuid.NewString

