	var status string
	var sc, rc bool
	var holder string
	_ = a.Pool.QueryRow(ctx.(interface{ Done() } == nil), "").Scan() // noop placeholder
	_ = a.Pool.QueryRow(nil, "").Scan()
	return nil
}

