package api

import (
	"net/http"
	"time"

	"github.com/google/uuid"

	"lablogistics/internal/auth"
	"lablogistics/internal/web"
)

// ---------- Initiate handoff ----------

type initiateHandoffReq struct {
	SampleID        string `json:"sampleId"`
	FromAssignmentID string `json:"fromAssignmentId"`
	ToAssignmentID   string `json:"toAssignmentId"`
	ReceiverID       string `json:"receiverId"`
	InitiatedAt      string `json:"initiatedAt"`
	IdempotencyKey   string `json:"idempotencyKey"`
}

func (a *App) InitiateHandoff(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req initiateHandoffReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.SampleID == "" || req.FromAssignmentID == "" || req.ToAssignmentID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	initiatedAt, err := parseTime(req.InitiatedAt)
	if err != nil || initiatedAt.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid initiatedAt"))
		return
	}
	ctx := r.Context()
	// sender must be current holder and the from assignment belongs to them & sample.
	var currentHolder string
	var sealed bool
	err = a.Pool.QueryRow(ctx, `SELECT COALESCE(current_holder_id::text,''), sealed FROM samples WHERE sample_id=$1`, req.SampleID).Scan(&currentHolder, &sealed)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "sample not found"))
		return
	}
	if !sealed {
		writeErr(w, apiErr(http.StatusConflict, "transport_leg_incomplete", "sample not sealed"))
		return
	}
	if currentHolder != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "not_current_holder", "you are not the current holder"))
		return
	}
	// from assignment belongs to sender
	var fromWorker string
	_ = a.Pool.QueryRow(ctx, `SELECT COALESCE(worker_id::text,'') FROM assignments WHERE assignment_id=$1`, req.FromAssignmentID).Scan(&fromWorker)
	if fromWorker != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "sender_assignment_mismatch", "from assignment not yours"))
		return
	}
	// pending handoff exists?
	var pending string
	_ = a.Pool.QueryRow(ctx, `SELECT handoff_id::text FROM handoffs WHERE sample_id=$1 AND status='pending'`, req.SampleID).Scan(&pending)
	if pending != "" {
		writeErr(w, apiErr(http.StatusConflict, "pending_handoff_exists", "a pending handoff already exists"))
		return
	}
	// to assignment must exist and belong to receiver
	var toWorker string
	_ = a.Pool.QueryRow(ctx, `SELECT COALESCE(worker_id::text,'') FROM assignments WHERE assignment_id=$1`, req.ToAssignmentID).Scan(&toWorker)
	receiver := req.ReceiverID
	if toWorker != "" {
		receiver = toWorker
	}
	if receiver == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_receiver", "receiver required"))
		return
	}
	var journeyID string
	_ = a.Pool.QueryRow(ctx, `SELECT journey_id::text FROM assignments WHERE assignment_id=$1`, req.FromAssignmentID).Scan(&journeyID)
	handoffID := uuid.NewString()
	_, err = a.Pool.Exec(ctx,
		`INSERT INTO handoffs (handoff_id, sample_id, journey_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at)
		 VALUES ($1,$2,$3::uuid,$4,$5,$6,$7,'pending',$8)`,
		handoffID, req.SampleID, journeyID, req.FromAssignmentID, req.ToAssignmentID, u.UserID, receiver, initiatedAt)
	if err != nil {
		writeErr(w, err)
		return
	}
	a.record(ctx, u.UserID, role, "initiate_handoff", "handoff", handoffID, true, map[string]interface{}{"senderId": u.UserID, "receiverId": receiver})
	a.emit(ctx, "handoff.initiated", "handoff", handoffID, map[string]interface{}{"sampleId": req.SampleID})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"handoffId": handoffID, "senderId": u.UserID, "receiverId": receiver,
		"currentHolderId": currentHolder, "status": "pending",
	})
}

// ---------- Confirm handoff ----------

type confirmHandoffReq struct {
	HandoffID        string `json:"handoffId"`
	ConfirmationSide string `json:"confirmationSide"`
	ConfirmedAt      string `json:"confirmedAt"`
	IdempotencyKey   string `json:"idempotencyKey"`
}

func (a *App) ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req confirmHandoffReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.HandoffID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_confirmation_side", "side must be sender or receiver"))
		return
	}
	confirmedAt, err := parseTime(req.ConfirmedAt)
	if err != nil || confirmedAt.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid confirmedAt"))
		return
	}
	ctx := r.Context()
	var handoffID, sampleID, senderID, receiverID, status string
	var senderConfirmed, receiverConfirmed bool
	err = a.Pool.QueryRow(ctx,
		`SELECT handoff_id::text, sample_id::text, sender_id::text, receiver_id::text, status, sender_confirmed, receiver_confirmed
		 FROM handoffs WHERE handoff_id=$1`, req.HandoffID).Scan(&handoffID, &sampleID, &senderID, &receiverID, &status, &senderConfirmed, &receiverConfirmed)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "handoff not found"))
		return
	}
	if status == "confirmed" || status == "cancelled" {
		writeErr(w, apiErr(http.StatusConflict, "handoff_inactive", "handoff already resolved"))
		return
	}
	// confirm on behalf: sender confirms for senderId, receiver for receiverId
	if req.ConfirmationSide == "sender" {
		if u.UserID != senderID {
			writeErr(w, apiErr(http.StatusForbidden, "forbidden", "not the sender"))
			return
		}
		if senderConfirmed {
			// idempotent already
			web.Data(w, http.StatusCreated, handoffView(ctx, a, req.HandoffID))
			return
		}
		_, _ = a.Pool.Exec(ctx, `INSERT INTO handoff_confirmations (handoff_id, side, confirmed_by, confirmed_at) VALUES ($1,'sender',$2,$3) ON CONFLICT DO NOTHING`, req.HandoffID, u.UserID, confirmedAt)
		_, _ = a.Pool.Exec(ctx, `UPDATE handoffs SET sender_confirmed=true WHERE handoff_id=$1`, req.HandoffID)
		senderConfirmed = true
	} else {
		if u.UserID != receiverID {
			writeErr(w, apiErr(http.StatusForbidden, "forbidden", "not the receiver"))
			return
		}
		if receiverConfirmed {
			web.Data(w, http.StatusCreated, handoffView(ctx, a, req.HandoffID))
			return
		}
		_, _ = a.Pool.Exec(ctx, `INSERT INTO handoff_confirmations (handoff_id, side, confirmed_by, confirmed_at) VALUES ($1,'receiver',$2,$3) ON CONFLICT DO NOTHING`, req.HandoffID, u.UserID, confirmedAt)
		_, _ = a.Pool.Exec(ctx, `UPDATE handoffs SET receiver_confirmed=true WHERE handoff_id=$1`, req.HandoffID)
		receiverConfirmed = true
	}

	bothConfirmed := senderConfirmed && receiverConfirmed
	currentHolder := senderID
	hStatus := "pending"
	if bothConfirmed {
		hStatus = "confirmed"
		_, _ = a.Pool.Exec(ctx, `UPDATE handoffs SET status='confirmed', confirmed_at=$2 WHERE handoff_id=$1`, req.HandoffID, confirmedAt)
		// transfer custody to receiver
		_, _ = a.Pool.Exec(ctx, `UPDATE samples SET current_holder_id=$2, updated_at=now() WHERE sample_id=$1`, sampleID, receiverID)
		// mark from assignment completed, to assignment active
		var fromAsg, toAsg string
		_ = a.Pool.QueryRow(ctx, `SELECT from_assignment_id::text, to_assignment_id::text FROM handoffs WHERE handoff_id=$1`, req.HandoffID).Scan(&fromAsg, &toAsg)
		if fromAsg != "" {
			_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=$2 WHERE assignment_id=$1`, fromAsg, confirmedAt)
		}
		if toAsg != "" {
			_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET status='active' WHERE assignment_id=$1 AND status IN ('accepted','offered')`, toAsg)
		}
		currentHolder = receiverID
		a.record(ctx, u.UserID, role, "custody_transfer", "sample", sampleID, true, map[string]interface{}{"from": senderID, "to": receiverID})
		a.emit(ctx, "handoff.confirmed", "handoff", req.HandoffID, map[string]interface{}{"sampleId": sampleID, "holderId": receiverID})
	}
	a.record(ctx, u.UserID, role, "confirm_handoff", "handoff", req.HandoffID, true, map[string]interface{}{"side": req.ConfirmationSide})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"handoffId": req.HandoffID, "status": hStatus,
		"senderConfirmed": senderConfirmed, "receiverConfirmed": receiverConfirmed,
		"currentHolderId": currentHolder,
	})
}

func handoffView(ctx interface{}, a *App, handoffID string) map[string]interface{} {
	var status string
	var sc, rc bool
	var holder string
	_ = a.Pool.QueryRow(ctx.(interface{ Done() } == nil), "").Scan() // noop placeholder
	_ = a.Pool.QueryRow(nil, "").Scan()
	return nil
}

