package api

import (
	"context"
	"encoding/json"
	"net/http"
	"time"

	"github.com/google/uuid"

	"lablogistics/internal/auth"
	"lablogistics/internal/web"
)

// ---------- Confirm laboratory receipt ----------

type confirmReceiptReq struct {
	SampleID       string `json:"sampleId"`
	LaboratoryID   string `json:"laboratoryId"`
	ReceivedAt     string `json:"receivedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (a *App) ConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req confirmReceiptReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.SampleID == "" || req.LaboratoryID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	receivedAt, err := parseTime(req.ReceivedAt)
	if err != nil || receivedAt.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid receivedAt"))
		return
	}
	ctx := r.Context()
	// lab operator must be assigned to that laboratory
	var assigned *string
	_ = a.Pool.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE user_id=$1`, u.UserID).Scan(&assigned)
	if assigned == nil || *assigned != req.LaboratoryID {
		writeErr(w, apiErr(http.StatusForbidden, "wrong_laboratory_operator", "not assigned to this laboratory"))
		return
	}
	// sample must be sealed and current holder must be the lab operator (or pending handoff to lab)
	var sealed bool
	var holder string
	var deadline time.Time
	var status string
	err = a.Pool.QueryRow(ctx, `SELECT sealed, COALESCE(current_holder_id::text,''), delivery_deadline, status FROM samples WHERE sample_id=$1`, req.SampleID).
		Scan(&sealed, &holder, &deadline, &status)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "sample not found"))
		return
	}
	if !sealed {
		writeErr(w, apiErr(http.StatusConflict, "receipt_not_ready", "sample not sealed"))
		return
	}
	if holder != u.UserID {
		// allow receipt only if custody already at lab operator; otherwise need handoff
		writeErr(w, apiErr(http.StatusConflict, "pending_handoff_exists", "custody not yet transferred to lab operator"))
		return
	}
	if !deadline.IsZero() && receivedAt.After(deadline) {
		// past deadline: still record but mark exception
		_, _ = a.Pool.Exec(ctx, `UPDATE samples SET status='exception', exception=$2, received_laboratory_id=$3, updated_at=now() WHERE sample_id=$1`,
			req.SampleID, `{"reason":"delivery_deadline_exceeded"}`, req.LaboratoryID)
		writeErr(w, apiErr(http.StatusConflict, "delivery_deadline_exceeded", "received after deadline"))
		return
	}
	_, _ = a.Pool.Exec(ctx, `UPDATE samples SET status='received', received_laboratory_id=$2, updated_at=now() WHERE sample_id=$1`, req.SampleID, req.LaboratoryID)
	// complete laboratory assignment for this sample
	_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=$2 WHERE sample_id=$1 AND kind='laboratory'`, req.SampleID, receivedAt)
	// complete delivery stop
	_, _ = a.Pool.Exec(ctx, `UPDATE journey_stops SET completed_at=$2 WHERE journey_id=(SELECT active_journey_id FROM samples WHERE sample_id=$1) AND stop_type='delivery' AND completed_at IS NULL`, req.SampleID, receivedAt)
	// mark journey completed
	_, _ = a.Pool.Exec(ctx, `UPDATE journeys SET status='completed', updated_at=now() WHERE journey_id=(SELECT active_journey_id FROM samples WHERE sample_id=$1) AND status NOT IN ('completed','cancelled')`, req.SampleID)
	a.releaseCapacity(ctx, journeyIDOfSample(ctx, a, req.SampleID))
	a.record(ctx, u.UserID, role, "confirm_laboratory_receipt", "sample", req.SampleID, true, map[string]interface{}{"laboratoryId": req.LaboratoryID})
	a.emit(ctx, "sample.received", "sample", req.SampleID, map[string]interface{}{"laboratoryId": req.LaboratoryID})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"sampleId": req.SampleID, "laboratoryId": req.LaboratoryID,
		"status": "received", "receivedAt": fmtTimeT(receivedAt),
	})
}

func journeyIDOfSample(ctx context.Context, a *App, sampleID string) string {
	var j string
	_ = a.Pool.QueryRow(ctx, `SELECT COALESCE(active_journey_id::text,'') FROM samples WHERE sample_id=$1`, sampleID).Scan(&j)
	return j
}

