		return
	}
	if holder != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "forbidden", "not the current holder"))
		return
	}
	if status == "received" || status == "cancelled" || status == "expired" {
		writeErr(w, apiErr(http.StatusConflict, "terminal_sample", "sample in terminal state"))
		return
	}
	st, _ := a.loadSampleType(ctx, sampleIDFromAssignment(ctx, a, req.AssignmentID))
	compliant := true
	if req.ObservedTemperatureC < st.TemperatureMinC || req.ObservedTemperatureC > st.TemperatureMaxC {
		compliant = false
	}
	checkpointID := uuid.NewString()
	_, err = a.Pool.Exec(ctx,
		`INSERT INTO handling_checkpoints (checkpoint_id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_by, recorded_at)
		 VALUES ($1,$2,$3,$4::uuid,$5,$6,$7,$8,$9)`,
