		a.emit(ctx, "sample.exception", "sample", req.SampleID, map[string]interface{}{"reason": "handling_noncompliant"})
	}
	sampleStatus := status
	if !compliant {
		sampleStatus = "exception"
	}
	a.record(ctx, u.UserID, role, "record_handling_checkpoint", "sample", req.SampleID, true, map[string]interface{}{"compliant": compliant})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"checkpointId": checkpointID, "sampleId": req.SampleID,
		"compliant": compliant, "sampleStatus": sampleStatus,
	})
