package api

import (
	"context"
	"net/http"
	"time"

	"lablogistics/internal/auth"
	"lablogistics/internal/domain"
	"lablogistics/internal/web"
)

// ---------- Read sample state ----------

func (a *App) ReadSampleState(w http.ResponseWriter, r *http.Request) {
	_, _, err := a.requireRole(r.Context(), auth.RoleRequester, auth.RoleDispatcher, auth.RoleAdministrator,
		auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	sampleID := r.PathValue("sampleId")
	if sampleID == "" {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "missing sampleId"))
		return
	}
	ctx := r.Context()
	// For requesters, only own samples.
	u := auth.FromContext(ctx)
	role := auth.RoleFromContext(ctx)
	var requesterID string
	_ = a.Pool.QueryRow(ctx, `SELECT requester_id::text FROM samples WHERE sample_id=$1`, sampleID).Scan(&requesterID)
	if role == auth.RoleRequester && requesterID != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "forbidden", "not your sample"))
		return
	}
	state, err := a.loadSampleState(ctx, sampleID)
	if err != nil {
		writeErr(w, err)
		return
	}
	web.Data(w, http.StatusOK, state)
}

func (a *App) loadSampleState(ctx context.Context, sampleID string) (domain.SampleState, error) {
	var s domain.SampleState
	var sampleType, container string
	var inc []string
	var lat, lon float64
	var requesterID, requestID, originType string
	var requestedAt, deadline time.Time
	var active bool
	var journeyID, targetLab *string
	var locLat, locLon *float64
	var locAt *time.Time
	err := a.Pool.QueryRow(ctx,
		`SELECT sample_id, request_id, requester_id::text, origin_latitude, origin_longitude, origin_type,
		        requested_at, delivery_deadline, sample_type_id, container_type, temperature_min_c, temperature_max_c,
		        incompatible_sample_types, serviceable, active_journey_id::text, target_laboratory_id::text,
		        latest_latitude, latest_longitude, location_recorded_at
		 FROM samples WHERE sample_id=$1`, sampleID).
		Scan(&s.SampleID, &requestID, &requesterID, &lat, &lon, &originType,
			&requestedAt, &deadline, &sampleType, &container, &s.TemperatureMinC, &s.TemperatureMaxC,
			&inc, &active, &journeyID, &targetLab, &locLat, &locLon, &locAt)
	if err != nil {
		return s, err
	}
	s.RequestID = requestID
	s.RequesterID = requesterID
	s.Origin = domain.Coordinate{Latitude: lat, Longitude: lon}
	s.OriginType = originType
	s.RequestedAt = fmtTimeT(requestedAt)
	s.DeliveryDeadline = fmtTimeT(deadline)
	s.SampleTypeID = sampleType
	s.ContainerType = container
	s.IncompatibleSampleTypes = strArr(inc)
	s.Serviceability = serviceabilityStr(active)
	if journeyID != nil {
		s.ActiveJourneyID = *journeyID
	}
	if targetLab != nil {
		s.TargetLaboratoryID = *targetLab
	}
	if locLat != nil && locLon != nil {
		s.LatestLocation = &domain.Coordinate{Latitude: *locLat, Longitude: *locLon}
	}
	if locAt != nil {
		s.LocationRecordedAt = fmtTime(locAt)
	}
	s.LocationStale = stale(locAt, a.Cfg.StaleMinutes)

	// active assignments
	rows, _ := a.Pool.Query(ctx, `SELECT assignment_id::text FROM assignments WHERE sample_id=$1 AND status IN ('offered','accepted','active')`, sampleID)
	defer rows.Close()
	var asgIDs []string
	for rows.Next() {
		var id string
		rows.Scan(&id)
		asgIDs = append(asgIDs, id)
	}
	s.ActiveAssignmentIDs = strArr(asgIDs)

	// status
	var status string
	_ = a.Pool.QueryRow(ctx, `SELECT status FROM samples WHERE sample_id=$1`, sampleID).Scan(&status)
	s.State = domain.SampleStateInner{Status: status}

	// timeline
	tl, _ := a.Audit.Timeline(ctx, "sample", sampleID, 200)
	s.Timeline = tl
	if s.Timeline == nil {
		s.Timeline = []domain.TimelineEntry{}
	}
	return s, nil
}

// ---------- Read sample lifecycle ----------

func (a *App) ReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	_, _, err := a.requireRole(r.Context(), auth.RoleRequester, auth.RoleDispatcher, auth.RoleAdministrator,
		auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		SampleID string `json:"sampleId"`
	}
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.SampleID == "" {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "sampleId required"))
		return
	}
	ctx := r.Context()
	u := auth.FromContext(ctx)
	role := auth.RoleFromContext(ctx)
	var requesterID string
	_ = a.Pool.QueryRow(ctx, `SELECT requester_id::text FROM samples WHERE sample_id=$1`, req.SampleID).Scan(&requesterID)
	if role == auth.RoleRequester && requesterID != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "forbidden", "not your sample"))
		return
	}
	life, err := a.loadSampleLifecycle(ctx, req.SampleID)
	if err != nil {
		writeErr(w, err)
		return
	}
	web.Data(w, http.StatusOK, life)
}

func (a *App) loadSampleLifecycle(ctx context.Context, sampleID string) (domain.SampleLifecycle, error) {
	var l domain.SampleLifecycle
	var status string
	var sealed bool
	var journeyID, holder, lab *string
	var locLat, locLon *float64
	var locAt *time.Time
