		return l, err
	}
	l.Status = status
	l.Sealed = sealed
	if journeyID != nil {
		l.ActiveJourneyID = *journeyID
	}
	if holder != nil {
		l.CurrentHolderID = *holder
	}
	if lab != nil {
		l.ReceivedLaboratoryID = *lab
	}
	if len(exc) > 0 {
		_ = jsonUnmarshalMap(exc, &l.Exception)
	}
	if locLat != nil && locLon != nil {
		l.LatestLocation = &domain.Coordinate{Latitude: *locLat, Longitude: *locLon}
	}
	if locAt != nil {
		l.LocationRecordedAt = fmtTime(locAt)
	}
	l.LocationStale = stale(locAt, a.Cfg.StaleMinutes)

	// completed leg ids
	rows, _ := a.Pool.Query(ctx, `SELECT assignment_id::text FROM assignments WHERE sample_id=$1 AND status='completed'`, sampleID)
	defer rows.Close()
	var completed []string
	for rows.Next() {
		var id string
		rows.Scan(&id)
		completed = append(completed, id)
	}
	l.CompletedLegIDs = strArr(completed)

	// active replacement plan ids (replacements linked)
	l.ActiveReplacementPlanIDs = []string{}

	// pending handoff
	var phID string
	_ = a.Pool.QueryRow(ctx, `SELECT handoff_id::text FROM handoffs WHERE sample_id=$1 AND status='pending' LIMIT 1`, sampleID).Scan(&phID)
	if phID != "" {
		l.PendingHandoffID = phID
		l.PendingHandoff = map[string]interface{}{"handoffId": phID}
	}

	tl, _ := a.Audit.Timeline(ctx, "sample", sampleID, 200)
	l.Timeline = tl
	if l.Timeline == nil {
		l.Timeline = []domain.TimelineEntry{}
	}
	return l, nil
}

func jsonUnmarshalMap(b []byte, dst *map[string]interface{}) error {
	if len(b) == 0 {
		return nil
	}
	return web.Unmarshal(b, dst)
}

