}

func (a *App) loadAssignmentGroups(ctx context.Context, journeyID string) (coll, node, lab, workers []string) {
	rows, _ := a.Pool.Query(ctx,
		`SELECT assignment_id::text, kind, COALESCE(worker_id::text,'') FROM assignments WHERE journey_id=$1`, journeyID)
	defer rows.Close()
	for rows.Next() {
		var id, kind, w string
		if rows.Scan(&id, &kind, &w) != nil {
			continue
		}
		switch kind {
		case "collection":
			coll = append(coll, id)
		case "node":
			node = append(node, id)
		case "laboratory":
			lab = append(lab, id)
		}
		if w != "" {
