		}
	}
	if coll == nil {
		coll = []string{}
	}
	if node == nil {
		node = []string{}
	}
	if lab == nil {
		lab = []string{}
	}
	if workers == nil {
		workers = []string{}
	}
	return
}

func (a *App) workerJourneyPlan(ctx context.Context, jp domain.JourneyPlan, workerID string) domain.WorkerJourneyPlan {
