func (a *App) operationsState(ctx context.Context, sampleTypeFilter *string) (domain.OperationsState, error) {
	var ops domain.OperationsState
	// samples
	rows, err := a.Pool.Query(ctx,
		`SELECT sample_id, status, request_id, origin_latitude, origin_longitude, delivery_deadline,
		        current_holder_id::text, active_journey_id::text, latest_latitude, latest_longitude,
		        location_recorded_at, sample_type_id
		 FROM samples ORDER BY created_at DESC`)
	if err != nil {
		return ops, err
	}
	defer rows.Close()
	for rows.Next() {
		var sampleID, status, requestID, sampleType string
		var lat, lon float64
		var deadline time.Time
		var holder, journey *string
		var locLat, locLon *float64
		var locAt *time.Time
		if err := rows.Scan(&sampleID, &status, &requestID, &lat, &lon, &deadline, &holder, &journey, &locLat, &locLon, &locAt, &sampleType); err != nil {
			continue
		}
		if sampleTypeFilter != nil && *sampleTypeFilter != "" && sampleType != *sampleTypeFilter {
			continue
		}
		item := map[string]interface{}{
			"sampleId": sampleID, "status": status, "requestId": requestID,
			"origin":     domain.Coordinate{Latitude: lat, Longitude: lon},
			"deliveryDeadline": fmtTimeT(deadline),
			"locationStale": stale(locAt, a.Cfg.StaleMinutes),
		}
		if holder != nil {
			item["currentHolderId"] = *holder
		}
		if journey != nil {
			item["activeJourneyId"] = *journey
		}
		if locLat != nil && locLon != nil {
			item["latestLocation"] = domain.Coordinate{Latitude: *locLat, Longitude: *locLon}
		}
		if locAt != nil {
			item["locationRecordedAt"] = fmtTime(locAt)
		}
		ops.Samples = append(ops.Samples, item)
	}
	if ops.Samples == nil {
		ops.Samples = []map[string]interface{}{}
	}
	// workers
	ops.Workers = a.loadWorkersState(ctx)
	// locations
	ops.Locations = a.loadLocationsState(ctx)
	// connections
	ops.Connections = a.loadConnectionsState(ctx)
	ops.Routes = []map[string]interface{}{}
	ops.Handoffs = a.loadHandoffsState(ctx)
	ops.Delays = []map[string]interface{}{}
	ops.Exceptions = a.loadExceptionsState(ctx)
	ops.AssignmentCountSpread = a.assignmentSpread(ctx)
	ops.IneligibleAssignmentCount = a.ineligibleCount(ctx)
	return ops, nil
}

func (a *App) loadWorkersState(ctx context.Context) []map[string]interface{} {
	rows, _ := a.Pool.Query(ctx,
		`SELECT u.user_id, u.username, COALESCE(u.full_name,''), u.roles, COALESCE(wa.available,true), COALESCE(wa.capacity_units,4),
		        wl.latitude, wl.longitude, wl.recorded_at
		 FROM users u
		 LEFT JOIN worker_availability wa ON wa.user_id = u.user_id
		 LEFT JOIN LATERAL (SELECT latitude, longitude, recorded_at FROM worker_locations WHERE user_id=u.user_id ORDER BY sequence DESC LIMIT 1) wl ON true
		 WHERE u.active=true AND EXISTS (SELECT 1 FROM unnest(u.roles) r WHERE r IN ('collection_professional','delivery_partner','node_handler','laboratory_team','dispatcher'))`)
	defer rows.Close()
	var out []map[string]interface{}
	for rows.Next() {
		var userID, username, fullName string
		var roles []string
		var avail bool
		var cap int
		var lat, lon *float64
		var locAt *time.Time
		if rows.Scan(&userID, &username, &fullName, &roles, &avail, &cap, &lat, &lon, &locAt) != nil {
			continue
		}
		status := "available"
		if !avail {
			status = "unavailable"
		}
		var cnt int
		_ = a.Pool.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','active')`, userID).Scan(&cnt)
		item := map[string]interface{}{
			"workerId": userID, "fullName": fullName, "roles": strArr(roles),
			"available": avail, "status": status, "capacityUnits": cap, "assignmentCount": cnt,
			"locationStale": stale(locAt, a.Cfg.StaleMinutes),
		}
		if lat != nil && lon != nil {
			item["latestLocation"] = domain.Coordinate{Latitude: *lat, Longitude: *lon}
		}
		if locAt != nil {
			item["locationRecordedAt"] = fmtTime(locAt)
		}
		out = append(out, item)
	}
	if out == nil {
		out = []map[string]interface{}{}
	}
	return out
}

func (a *App) loadLocationsState(ctx context.Context) []domain.OperationsLocation {
	rows, _ := a.Pool.Query(ctx,
		`SELECT l.location_id, l.name, l.latitude, l.longitude, l.active, l.coverage_km, l.handling_minutes,
		        l.fn_collection_point, l.fn_transfer_point, l.fn_hub, l.fn_laboratory,
		        COALESCE(c.capacity_units,0), COALESCE(c.reserved_units,0), COALESCE(c.cooled_capacity_units,0), COALESCE(c.cooled_reserved_units,0)
		 FROM locations l LEFT JOIN capacities c ON c.resource_id=l.location_id`)
	defer rows.Close()
	var out []domain.OperationsLocation
	for rows.Next() {
		var o domain.OperationsLocation
		var lat, lon, cov float64
		var handling int
		var active, cp, tp, hub, lab bool
		var cap, res, ccap, cres int
		if rows.Scan(&o.LocationID, &o.Name, &lat, &lon, &active, &cov, &handling, &cp, &tp, &hub, &lab, &cap, &res, &ccap, &cres) != nil {
			continue
		}
		o.ID = o.LocationID
		o.Coordinate = domain.Coordinate{Latitude: lat, Longitude: lon}
		o.Active = active
		o.CoverageKm = cov
		o.HandlingMinutes = handling
		o.Functions = domain.LocationFunctionStates{CollectionPoint: cp, TransferPoint: tp, Hub: hub, Laboratory: lab}
		o.Capacity = &domain.Capacity{CapacityUnits: cap, ReservedUnits: res, AvailableUnits: cap - res,
			CooledCapacityUnits: ccap, CooledReservedUnits: cres, CooledAvailableUnits: ccap - cres}
		out = append(out, o)
	}
	if out == nil {
		out = []domain.OperationsLocation{}
	}
	return out
}

func (a *App) loadConnectionsState(ctx context.Context) []domain.OperationsConnection {
	rows, _ := a.Pool.Query(ctx,
		`SELECT c.connection_id, c.from_location_id, c.to_location_id, c.travel_minutes, c.cost_units, c.cooled, c.active,
		        COALESCE(cap.capacity_units,0), COALESCE(cap.reserved_units,0), COALESCE(cap.cooled_capacity_units,0), COALESCE(cap.cooled_reserved_units,0)
		 FROM connections c LEFT JOIN capacities cap ON cap.resource_id=c.connection_id`)
	defer rows.Close()
	var out []domain.OperationsConnection
	for rows.Next() {
		var o domain.OperationsConnection
		var cap, res, ccap, cres int
		if rows.Scan(&o.ConnectionID, &o.FromLocationID, &o.ToLocationID, &o.TravelMinutes, &o.CostUnits, &o.Cooled, &o.Active, &cap, &res, &ccap, &cres) != nil {
			continue
		}
		o.ID = o.ConnectionID
		o.Capacity = &domain.Capacity{CapacityUnits: cap, ReservedUnits: res, AvailableUnits: cap - res,
			CooledCapacityUnits: ccap, CooledReservedUnits: cres, CooledAvailableUnits: ccap - cres}
		out = append(out, o)
	}
	if out == nil {
		out = []domain.OperationsConnection{}
	}
	return out
}

func (a *App) loadHandoffsState(ctx context.Context) []map[string]interface{} {
	rows, _ := a.Pool.Query(ctx,
		`SELECT h.handoff_id, h.sample_id, h.sender_id, h.receiver_id, h.status, h.sender_confirmed, h.receiver_confirmed, h.initiated_at
		 FROM handoffs h ORDER BY h.initiated_at DESC LIMIT 200`)
	defer rows.Close()
	var out []map[string]interface{}
	for rows.Next() {
		var id, sample, sender, receiver, status string
		var sc, rc bool
		var init time.Time
		if rows.Scan(&id, &sample, &sender, &receiver, &status, &sc, &rc, &init) != nil {
			continue
		}
		out = append(out, map[string]interface{}{
			"handoffId": id, "sampleId": sample, "senderId": sender, "receiverId": receiver,
			"status": status, "senderConfirmed": sc, "receiverConfirmed": rc, "initiatedAt": fmtTimeT(init),
		})
	}
	if out == nil {
		out = []map[string]interface{}{}
	}
	return out
}

func (a *App) loadExceptionsState(ctx context.Context) []map[string]interface{} {
	rows, _ := a.Pool.Query(ctx,
		`SELECT sample_id, status, exception FROM samples WHERE status='exception' OR exception IS NOT NULL ORDER BY updated_at DESC LIMIT 200`)
	defer rows.Close()
	var out []map[string]interface{}
	for rows.Next() {
		var sample, status string
		var exc []byte
		if rows.Scan(&sample, &status, &exc) != nil {
			continue
		}
		item := map[string]interface{}{"sampleId": sample, "status": status}
		var m map[string]interface{}
		if len(exc) > 0 {
			_ = web.Unmarshal(exc, &m)
			item["exception"] = m
		}
		out = append(out, item)
	}
	if out == nil {
		out = []map[string]interface{}{}
	}
	return out
}

func (a *App) assignmentSpread(ctx context.Context) int {
	var spread int
	_ = a.Pool.QueryRow(ctx, `SELECT COALESCE(max(cnt)-min(cnt),0) FROM (SELECT count(*) cnt FROM assignments WHERE status IN ('accepted','active') GROUP BY worker_id) sub`).Scan(&spread)
	return spread
}

func (a *App) ineligibleCount(ctx context.Context) int {
	var c int
	_ = a.Pool.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE status='offered' AND offered_to_worker_id IS NULL`).Scan(&c)
	return c
}

