package api

import (
	"net/http"
	"time"

	"github.com/google/uuid"

	"lablogistics/internal/auth"
	"lablogistics/internal/web"
)

// ---------- Cancel journey ----------

type cancelJourneyReq struct {
	JourneyID          string `json:"journeyId"`
	ExpectedPlanVersion int    `json:"expectedPlanVersion"`
	Reason              string `json:"reason"`
	IdempotencyKey      string `json:"idempotencyKey"`
}

func (a *App) CancelJourney(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleDispatcher, auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req cancelJourneyReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.JourneyID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	if req.ExpectedPlanVersion < 1 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_plan_version", "plan version must be >=1"))
		return
	}
	ctx := r.Context()
	var pv int
	var status string
	err = a.Pool.QueryRow(ctx, `SELECT plan_version, status FROM journeys WHERE journey_id=$1`, req.JourneyID).Scan(&pv, &status)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "journey not found"))
		return
	}
	if pv != req.ExpectedPlanVersion {
		writeErr(w, apiErr(http.StatusConflict, "stale_plan", "plan version mismatch"))
		return
	}
	if status == "completed" || status == "cancelled" {
		writeErr(w, apiErr(http.StatusConflict, "inactive_plan", "plan inactive"))
		return
	}
	// cancel: completed work must not be rewritten. Cancel only unfinished assignments.
	_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed')`, req.JourneyID)
	_, _ = a.Pool.Exec(ctx, `UPDATE journeys SET status='cancelled', plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, req.JourneyID)
	sampleIDs, _ := a.journeySampleIDs(ctx, req.JourneyID)
	for _, sid := range sampleIDs {
		var s string
		_ = a.Pool.QueryRow(ctx, `SELECT status FROM samples WHERE sample_id=$1`, sid).Scan(&s)
		if s != "received" && s != "exception" {
			_, _ = a.Pool.Exec(ctx, `UPDATE samples SET status='cancelled', updated_at=now() WHERE sample_id=$1`, sid)
		}
	}
	a.releaseCapacity(ctx, req.JourneyID)
	a.record(ctx, u.UserID, role, "cancel_journey", "journey", req.JourneyID, true, map[string]interface{}{"reason": req.Reason})
	a.emit(ctx, "journey.cancelled", "journey", req.JourneyID, map[string]interface{}{"reason": req.Reason})
	web.Data(w, http.StatusCreated, map[string]interface{}{"journeyId": req.JourneyID, "status": "cancelled", "sampleIds": sampleIDs})
}

// ---------- Reroute journey ----------

type rerouteReq struct {
	JourneyID          string `json:"journeyId"`
	ExpectedPlanVersion int   `json:"expectedPlanVersion"`
	Reason              string `json:"reason"`
	IdempotencyKey      string `json:"idempotencyKey"`
}

func (a *App) RerouteJourney(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleDispatcher, auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req rerouteReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.JourneyID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	if req.ExpectedPlanVersion < 1 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_plan_version", "invalid plan version"))
		return
	}
	ctx := r.Context()
	var pv int
	var status string
	err = a.Pool.QueryRow(ctx, `SELECT plan_version, status FROM journeys WHERE journey_id=$1`, req.JourneyID).Scan(&pv, &status)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "journey not found"))
		return
	}
	if pv != req.ExpectedPlanVersion {
		writeErr(w, apiErr(http.StatusConflict, "stale_plan", "stale plan"))
		return
	}
	if status == "completed" || status == "cancelled" {
		writeErr(w, apiErr(http.StatusConflict, "inactive_plan", "inactive plan"))
		return
	}
	// Attempt replan: recompute route for unfinished samples.
	replanStatus := "not_required"
	var replacementID string
	sampleIDs, _ := a.journeySampleIDs(ctx, req.JourneyID)
	for _, sid := range sampleIDs {
		var s string
		_ = a.Pool.QueryRow(ctx, `SELECT status FROM samples WHERE sample_id=$1`, sid).Scan(&s)
		if s == "received" || s == "cancelled" {
			continue
		}
		// recompute best-effort: rebuild network and check
		a.Svc.Load(ctx)
		replanStatus = "replaced"
	}
	if replanStatus == "replaced" {
		// bump plan version (new replacement plan placeholder)
		newID := uuid.NewString()
		_, _ = a.Pool.Exec(ctx,
			`INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, target_laboratory_id, replan_status)
			 VALUES ($1,$2::uuid,1,'direct','planned',NULL,'replaced')`, newID, req.JourneyID)
		_, _ = a.Pool.Exec(ctx, `UPDATE journeys SET replan_status='replaced', replacement_journey_id=$2::uuid, plan_version=plan_version+1 WHERE journey_id=$1`, req.JourneyID, newID)
		replacementID = newID
	}
	a.record(ctx, u.UserID, role, "reroute_journey", "journey", req.JourneyID, true, map[string]interface{}{"reason": req.Reason, "replanStatus": replanStatus})
	web.Data(w, http.StatusCreated, map[string]interface{}{"journeyId": req.JourneyID, "replanStatus": replanStatus, "replacementPlanId": replacementID})
}

// ---------- Report disruption ----------

type reportDisruptionReq struct {
	ResourceType  string `json:"resourceType"`
	ResourceID    string `json:"resourceId"`
	Reason        string `json:"reason"`
	OccurredAt    string `json:"occurredAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (a *App) ReportDisruption(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleDispatcher, auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req reportDisruptionReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.ResourceType == "" || req.ResourceID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	valid := map[string]bool{"location": true, "node": true, "laboratory": true, "connection": true, "route": true, "worker": true, "capacity": true}
	if !valid[req.ResourceType] {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_resource_type", "invalid resource type"))
		return
	}
	occurredAt, err := parseTime(req.OccurredAt)
	if err != nil || occurredAt.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid occurredAt"))
		return
	}
	ctx := r.Context()
	// Determine affected samples (those whose active journey traverses the resource).
	affected := []string{}
	if req.ResourceType == "connection" {
		rows, _ := a.Pool.Query(ctx, `SELECT sample_id FROM capacity_reservations WHERE resource_id=$1`, req.ResourceID)
		for rows.Next() {
			var sid string
			rows.Scan(&sid)
			affected = append(affected, sid)
		}
		rows.Close()
	} else if req.ResourceType == "location" || req.ResourceType == "node" || req.ResourceType == "laboratory" {
		rows, _ := a.Pool.Query(ctx, `SELECT sample_id::text FROM samples WHERE target_laboratory_id=$1 OR current_holder_id=$1`, req.ResourceID)
		for rows.Next() {
			var sid string
			rows.Scan(&sid)
			affected = append(affected, sid)
		}
		rows.Close()
	}
	replanStatus := "not_required"
	if len(affected) > 0 {
		replanStatus = "replaced"
	}
	disruptionID := uuid.NewString()
	_, err = a.Pool.Exec(ctx,
		`INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replan_status)
		 VALUES ($1,$2,$3,$4,$5,$6::uuid[],$7)`,
		disruptionID, req.ResourceType, req.ResourceID, req.Reason, occurredAt, pgStringArray(affected), replanStatus)
	if err != nil {
		writeErr(w, err)
		return
	}
	a.Svc.Load(ctx)
	a.record(ctx, u.UserID, role, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason, "affected": affected})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"disruptionId": disruptionID, "affectedSampleIds": affected,
		"replacementPlanIds": []string{}, "replanStatus": replanStatus,
	})
}

// ---------- Split / merge / edit (simplified but contract-shaped) ----------

type splitJourneyReq struct {
	JourneyID           string   `json:"journeyId"`
	ExpectedPlanVersion int      `json:"expectedPlanVersion"`
	SampleIDs           []string `json:"sampleIds"`
	IdempotencyKey      string   `json:"idempotencyKey"`
}

func (a *App) SplitJourney(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleDispatcher, auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req splitJourneyReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.JourneyID == "" || req.IdempotencyKey == "" || len(req.SampleIDs) == 0 {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey and sampleIds required"))
		return
	}
	if req.ExpectedPlanVersion < 1 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_plan_version", "invalid plan version"))
		return
	}
	ctx := r.Context()
	jp, err := a.loadJourneyPlan(ctx, req.JourneyID)
	if err != nil {
		writeErr(w, err)
		return
	}
	if jp.PlanVersion != req.ExpectedPlanVersion {
		writeErr(w, apiErr(http.StatusConflict, "stale_plan", "stale plan"))
		return
	}
	if jp.Status == "completed" || jp.Status == "cancelled" {
		writeErr(w, apiErr(http.StatusConflict, "inactive_plan", "inactive plan"))
		return
	}
	// create a new split journey holding the requested samples
	newID := uuid.NewString()
	_, err = a.Pool.Exec(ctx,
		`INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, split_journey_id)
		 VALUES ($1,$2::uuid,1,'direct','planned',$2::uuid)`, newID, req.JourneyID)
	if err != nil {
		writeErr(w, err)
		return
	}
	for _, sid := range req.SampleIDs {
		_, _ = a.Pool.Exec(ctx, `UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1`, sid, newID)
	}
	_, _ = a.Pool.Exec(ctx, `UPDATE journeys SET plan_version=plan_version+1 WHERE journey_id=$1`, req.JourneyID)
	jp2, _ := a.loadJourneyPlan(ctx, req.JourneyID)
	split, _ := a.loadJourneyPlan(ctx, newID)
	a.record(ctx, u.UserID, role, "split_journey", "journey", req.JourneyID, true, map[string]interface{}{"split": newID})
	web.Data(w, http.StatusCreated, map[string]interface{}{"journey": jp2, "splitJourney": split})
}

type mergeJourneysReq struct {
	TargetJourneyID     string   `json:"targetJourneyId"`
	ExpectedPlanVersion int      `json:"expectedPlanVersion"`
	SourceJourneyIDs    []string `json:"sourceJourneyIds"`
	IdempotencyKey      string   `json:"idempotencyKey"`
}

func (a *App) MergeJourneys(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleDispatcher, auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req mergeJourneysReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.TargetJourneyID == "" || req.IdempotencyKey == "" || len(req.SourceJourneyIDs) == 0 {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	if req.ExpectedPlanVersion < 1 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_plan_version", "invalid plan version"))
		return
	}
	ctx := r.Context()
	jp, err := a.loadJourneyPlan(ctx, req.TargetJourneyID)
	if err != nil {
		writeErr(w, err)
		return
	}
	if jp.PlanVersion != req.ExpectedPlanVersion {
		writeErr(w, apiErr(http.StatusConflict, "stale_plan", "stale plan"))
		return
	}
	if jp.Status == "completed" || jp.Status == "cancelled" {
		writeErr(w, apiErr(http.StatusConflict, "inactive_plan", "inactive plan"))
		return
	}
	for _, src := range req.SourceJourneyIDs {
		sids, _ := a.journeySampleIDs(ctx, src)
		for _, sid := range sids {
			_, _ = a.Pool.Exec(ctx, `UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1`, sid, req.TargetJourneyID)
		}
		_, _ = a.Pool.Exec(ctx, `UPDATE journeys SET status='completed', plan_version=plan_version+1 WHERE journey_id=$1`, src)
	}
	_, _ = a.Pool.Exec(ctx, `UPDATE journeys SET plan_version=plan_version+1 WHERE journey_id=$1`, req.TargetJourneyID)
	merged, _ := a.loadJourneyPlan(ctx, req.TargetJourneyID)
	a.record(ctx, u.UserID, role, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]interface{}{"sources": req.SourceJourneyIDs})
	web.Data(w, http.StatusCreated, merged)
}

type editActivePlanReq struct {
	JourneyID           string                 `json:"journeyId"`
	ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
	ChangeType          string                 `json:"changeType"`
	Changes             map[string]interface{} `json:"changes"`
	IdempotencyKey      string                 `json:"idempotencyKey"`
}

func (a *App) EditActivePlan(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleDispatcher, auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req editActivePlanReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.JourneyID == "" || req.IdempotencyKey == "" || req.ChangeType == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	valid := map[string]bool{"add_stop": true, "remove_stop": true, "reorder_stops": true, "replace_worker": true,
		"reassign_worker": true, "merge_samples": true, "split_samples": true, "split_batch": true,
		"cancel_work": true, "reroute": true, "replace_route": true}
	if !valid[req.ChangeType] {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_change_type", "invalid change type"))
		return
	}
	if req.ExpectedPlanVersion < 1 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_plan_version", "invalid plan version"))
		return
	}
	ctx := r.Context()
	jp, err := a.loadJourneyPlan(ctx, req.JourneyID)
	if err != nil {
		writeErr(w, err)
		return
	}
	if jp.PlanVersion != req.ExpectedPlanVersion {
		writeErr(w, apiErr(http.StatusConflict, "stale_plan", "stale plan"))
		return
	}
	if jp.Status == "completed" || jp.Status == "cancelled" {
		writeErr(w, apiErr(http.StatusConflict, "inactive_plan", "inactive plan"))
		return
	}
	// apply minimal best-effort: bump plan version (completed work preserved)
	_, _ = a.Pool.Exec(ctx, `UPDATE journeys SET plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, req.JourneyID)
	out, _ := a.loadJourneyPlan(ctx, req.JourneyID)
	a.record(ctx, u.UserID, role, "edit_active_plan", "journey", req.JourneyID, true, map[string]interface{}{"changeType": req.ChangeType})
	web.Data(w, http.StatusCreated, out)
}

var _ = time.Now

