package api

import (
	"net/http"
	"strconv"

	"lablogistics/internal/auth"
	"lablogistics/internal/web"
)

// StreamRealtimeEvents serves both as an HTTP polling endpoint and a WebSocket.
// The pinned contract lists GET /api/events returning {events, cursor}.
func (a *App) StreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	if r.Header.Get("Upgrade") == "websocket" {
		a.handleWS(w, r)
		return
	}
	_, _, err := a.requireRole(r.Context(), auth.AllRoles)
	if err != nil {
		writeErr(w, err)
		return
	}
	sinceStr := r.URL.Query().Get("since")
	since, _ := strconv.ParseInt(sinceStr, 10, 64)
	evs, cursor, err := a.Events.Replay(r.Context(), since, 500)
	if err != nil {
		writeErr(w, err)
		return
	}
	if evs == nil {
		evs = []interface{}{}.([]interface{})
	}
	web.Data(w, http.StatusOK, map[string]interface{}{"events": evs, "cursor": cursor})
}

