action.file_text:
package api

import (
	"encoding/base64"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/gorilla/websocket"

	"lablogistics/internal/domain"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

// handleWS upgrades to a WebSocket using the lab-logistics-v1 subprotocol, which
// carries the bearer [REDACTED] as base64url-encoded "bearer.<token>".
func (a *App) handleWS(w http.ResponseWriter, r *http.Request) {
	proto := r.Header.Get("Sec-WebSocket-Protocol")
	token := extractWSToken(proto)
	if token == "" {
		token = auth.ExtractBearer(r)
	}
	if !a.validSession(r, token) {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}
	sinceStr := r.URL.Query().Get("since")
	since, _ := strconv.ParseInt(sinceStr, 10, 64)

	protocols := []string{"lab-logistics-v1"}
	hdr := http.Header{}
	hdr.Set("Sec-WebSocket-Protocol", strings.Join(protocols, ", "))
	conn, err := upgrader.Upgrade(w, r, hdr)
	if err != nil {
		return
	}
	defer conn.Close()

	ch, unsub := a.Events.Subscribe()
	defer unsub()

	// replay missed events first
	evs, cursor, _ := a.Events.Replay(r.Context(), since, 500)
	for _, ev := range evs {
		_ = conn.WriteJSON(ev)
	}
	_ = cursor

	// stream new events
	writeTimeout := time.NewTimer(0)
	defer writeTimeout.Stop()
	for {
		select {
		case ev, ok := <-ch:
			if !ok {
				return
			}
			_ = conn.WriteJSON(ev)
		case <-time.After(30 * time.Second):
			// keepalive ping
			_ = conn.WriteMessage(websocket.PingMessage, nil)
		}
	}
}

func extractWSToken(proto string) string {
	parts := strings.Split(proto, ",")
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if strings.HasPrefix(p, "bearer.") {
			raw := strings.TrimPrefix(p, "bearer.")
			b, err := base64.RawURLEncoding.DecodeString(raw)
			if err == nil {
				return string(b)
			}
			return raw
		}
	}
	return ""
}

func (a *App) validSession(r *http.Request, token string) bool {
	if token == "" {
		return false
	}
	var userID string
	err := a.Pool.QueryRow(r.Context(), `SELECT user_id::text FROM sessions WHERE session_token=$1 AND expires_at > now()`, token).Scan(&userID)
	if err != nil {
		return false
	}
	return userID != ""
}

var _ = domain.RealtimeEvent{}

