package seed

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/jackc/pgx/v5/pgxpool"
)

// SeedDefaultSampleTypes ensures the four default named sample types exist.
// Amber - standard handling.
// Indigo - must not share a container with Amber (modeled via incompatibility).
// Frost - requires cooled storage/transport throughout.
// Pulse - time-critical; no batching/waiting.
func SeedDefaultSampleTypes(ctx context.Context, pool *pgxpool.Pool) error {
	type def struct {
		name                      string
		qualified                 bool
		qual                      string
		container                 string
		minC, maxC                float64
		cooled                    bool
		batching                  bool
		incompatNames             []string
	}
	defs := []def{
		{name: "Amber", qualified: true, qual: "AMBER", container: "standard", minC: 2, maxC: 25, cooled: false, batching: true},
		{name: "Indigo", qualified: true, qual: "INDIGO", container: "standard", minC: 2, maxC: 25, cooled: false, batching: true, incompatNames: []string{"Amber"}},
		{name: "Frost", qualified: true, qual: "FROST", container: "cooled", minC: 2, maxC: 8, cooled: true, batching: true},
		{name: "Pulse", qualified: true, qual: "PULSE", container: "standard", minC: 2, maxC: 25, cooled: false, batching: false},
	}
	// resolve names to ids
	nameToID := map[string]string{}
	rows, err := pool.Query(ctx, `SELECT sample_type_id::text, name FROM sample_types`)
	if err != nil {
		return err
	}
	for rows.Next() {
		var id, name string
		rows.Scan(&id, &name)
		nameToID[name] = id
	}
	rows.Close()

	for _, d := range defs {
		var id string
		if existing, ok := nameToID[d.name]; ok {
			// update defaults
			_, err := pool.Exec(ctx, `UPDATE sample_types SET qualified_collector_required=$2, required_qualification=$3, container_type=$4, temperature_min_c=$5, temperature_max_c=$6, requires_cooled_route=$7, batching_allowed=$8 WHERE sample_type_id=$1`,
				existing, d.qualified, d.qual, d.container, d.minC, d.maxC, d.cooled, d.batching)
			if err != nil {
				return err
			}
			id = existing
			continue
		}
		incIDs := []string{}
		for _, n := range d.incompatNames {
			if iid, ok := nameToID[n]; ok {
				incIDs = append(incIDs, iid)
			}
		}
		incArr, _ := json.Marshal(incIDs)
		err := pool.QueryRow(ctx,
			`INSERT INTO sample_types (name, qualified_collector_required, required_qualification, container_type,
			   temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed, incompatible_sample_types)
			 VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9::uuid[]) RETURNING sample_type_id`,
			d.name, d.qualified, d.qual, d.container, d.minC, d.maxC, d.cooled, d.batching, string(incArr),
		).Scan(&id)
		if err != nil {
			return fmt.Errorf("seed %s: %w", d.name, err)
		}
		nameToID[d.name] = id
	}
	// set Indigo <-> Amber incompatibility both ways
	if amber, ok := nameToID["Amber"]; ok {
		if indigo, ok2 := nameToID["Indigo"]; ok2 {
			_, _ = pool.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types=$2::uuid[] WHERE sample_type_id=$1`, amber, fmt.Sprintf("{%s}", indigo))
			_, _ = pool.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types=$2::uuid[] WHERE sample_type_id=$1`, indigo, fmt.Sprintf("{%s}", amber))
		}
	}
	return nil
}

