		).Scan(&id)
		if err != nil {
			return fmt.Errorf("seed %s: %w", d.name, err)
		}
		nameToID[d.name] = id
	}
	// set Indigo <-> Amber incompatibility both ways
	if amber, ok := nameToID["Amber"]; ok {
		if indigo, ok2 := nameToID["Indigo"]; ok2 {
			_, _ = pool.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types=$2::uuid[] WHERE sample_type_id=$1`, amber, fmt.Sprintf("{%s}", indigo))
			_, _ = pool.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types=$2::uuid[] WHERE sample_type_id=$1`, indigo, fmt.Sprintf("{%s}", amber))
		}
	}
	return nil
}

