package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"

	"lablogistics/internal/api"
	"lablogistics/internal/config"
	"lablogistics/internal/seed"
	"lablogistics/internal/serviceability"
	smongo "lablogistics/internal/storemongo"
	"lablogistics/internal/storepg"
	"lablogistics/internal/web"
)

func main() {
	if len(os.Args) > 1 && os.Args[1] == "reset" {
		if err := runReset(); err != nil {
			fmt.Fprintf(os.Stderr, "reset failed: %v\n", err)
			os.Exit(1)
		}
		fmt.Println("reset complete")
		return
	}
	if err := runServer(); err != nil {
		fmt.Fprintf(os.Stderr, "server error: %v\n", err)
		os.Exit(1)
	}
}

func runReset() error {
	cfg, err := config.Load()
	if err != nil {
		return err
	}
	ctx := context.Background()
	db, err := storepg.New(ctx, cfg.DatabaseURL)
	if err != nil {
		return fmt.Errorf("pg: %w", err)
	}
	defer db.Pool.Close()
	if err := db.Reset(ctx); err != nil {
		return fmt.Errorf("pg migrate: %w", err)
	}
	mongo, err := smongo.New(ctx, cfg.MongoURI)
	if err != nil {
		return fmt.Errorf("mongo: %w", err)
	}
	defer mongo.Client.Disconnect(ctx)
	if err := mongo.DropAll(ctx); err != nil {
		return err
	}
	if err := mongo.EnsureCollections(ctx); err != nil {
		return fmt.Errorf("mongo collections: %w", err)
	}
	if err := seed.SeedDefaultSampleTypes(ctx, db.Pool); err != nil {
		return fmt.Errorf("seed: %w", err)
	}
	return nil
}

func runServer() error {
	cfg, err := config.Load()
	if err != nil {
		return err
	}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	db, err := storepg.New(ctx, cfg.DatabaseURL)
	if err != nil {
		return fmt.Errorf("pg connect: %w", err)
	}
	defer db.Pool.Close()

	// Ensure schema exists (idempotent) on start.
	if err := db.Migrate(ctx); err != nil {
		return fmt.Errorf("pg migrate: %w", err)
	}

	mongo, err := smongo.New(ctx, cfg.MongoURI)
	if err != nil {
		log.Printf("warning: mongo unavailable: %v (continuing without audit/search mirror)", err)
		mongo = nil
	} else {
		if err := mongo.EnsureCollections(ctx); err != nil {
			log.Printf("warning: mongo ensure collections: %v", err)
		}
	}
	if mongo != nil {
		defer mongo.Client.Disconnect(ctx)
	}

	// Seed default sample types.
	if err := seed.SeedDefaultSampleTypes(ctx, db.Pool); err != nil {
		log.Printf("warning: seed sample types: %v", err)
	}

	svc := serviceability.New(db.Pool)
	if _, err := svc.Load(ctx); err != nil {
		log.Printf("warning: initial serviceability load: %v", err)
	}

	app := api.NewApp(cfg, db.Pool, mongo, svc)

	if err := app.EnsureAdmin(ctx); err != nil {
		log.Printf("warning: ensure admin: %v", err)
	}

	// background offer-expire loop
	go app.OfferExpireLoop(ctx)

	mux := http.NewServeMux()
	app.Routes(mux)

	// Static assets: map assets + frontend.
	registerStatic(mux, cfg)

	authMW := web.NewAuthMiddleware(db.Pool)
	handler := web.DefaultMiddleware(authMW.Wrap(mux))

	srv := &http.Server{
		Addr:              cfg.HTTPAddr,
		Handler:           handler,
		ReadHeaderTimeout: 15 * time.Second,
	}

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		<-stop
		log.Println("shutting down...")
		cancel()
		shutCtx, shutCancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer shutCancel()
		_ = srv.Shutdown(shutCtx)
	}()

	log.Printf("lab-logistics server listening on http://%s", cfg.HTTPAddr)
	if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}

// registerStatic serves the frontend SPA and the local PMTiles map assets.
func registerStatic(mux *http.ServeMux, cfg *config.Config) {
	// Map assets at /map-assets/ from the supplied directory.
	mapDir := cfg.MapAssetsDir
	if _, err := os.Stat(mapDir); err == nil {
		fs := http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapDir)))
		mux.Handle("GET /map-assets/", fs)
	}

	// Frontend SPA from the built dist directory.
	frontDir := cfg.FrontendDir
	if info, err := os.Stat(frontDir); err == nil && info.IsDir() {
		fileServer := http.FileServer(http.Dir(frontDir))
		mux.Handle("GET /", withSPA(frontDir, fileServer))
	}
}

// withSPA serves index.html for client-side routes that don't match a static file.
func withSPA(frontDir string, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := strings.TrimPrefix(r.URL.Path, "/")
		if p == "" {
			next.ServeHTTP(w, r)
			return
		}
		full := filepath.Join(frontDir, p)
		if _, err := os.Stat(full); err == nil {
			next.ServeHTTP(w, r)
			return
		}
		// fallback to index.html
		http.ServeFile(w, r, filepath.Join(frontDir, "index.html"))
	})
}

