package routing

import (
	"math"
	"sort"
	"time"
)

// Network is an in-memory view of the transport network used for routing and
// serviceability calculations. It is rebuilt whenever the network changes.
type Network struct {
	Locations map[string]*Node
	Edges     map[string][]*Edge // fromLocationID -> edges
}

type Node struct {
	LocationID      string
	Latitude        float64
	Longitude       float64
	CoverageKm      float64
	HandlingMinutes int
	Active          bool
	CollectionPoint bool
	TransferPoint   bool
	Hub             bool
	Laboratory      bool
}

type Edge struct {
	ConnectionID  string
	From          string
	To            string
	TravelMinutes int
	CostUnits     float64
	Cooled        bool
	Active        bool
}

func NewNetwork() *Network {
	return &Network{
		Locations: map[string]*Node{},
		Edges:     map[string][]*Edge{},
	}
}

func (n *Network) AddNode(loc *Node) {
	n.Locations[loc.LocationID] = loc
}

func (n *Network) AddEdge(e *Edge) {
	n.Edges[e.From] = append(n.Edges[e.From], e)
}

// Haversine distance in km.
func HaversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180
	dLon := (lon2 - lon1) * math.Pi / 180
	la1 := lat1 * math.Pi / 180
	la2 := lat2 * math.Pi / 180
	a := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(la1)*math.Cos(la2)*math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

// CollectionPoints returns active collection points covering the origin within coverageKm.
func (n *Network) CollectionPoints(lat, lon float64, maxKm float64) []*Node {
	if maxKm <= 0 {
		maxKm = 5
	}
	var out []*Node
	for _, loc := range n.Locations {
		if !loc.Active || !loc.CollectionPoint {
			continue
		}
		d := HaversineKm(lat, lon, loc.Latitude, loc.Longitude)
		if d <= loc.CoverageKm && d <= maxKm {
			out = append(out, loc)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		return HaversineKm(lat, lon, out[i].Latitude, out[i].Longitude) <
			HaversineKm(lat, lon, out[j].Latitude, out[j].Longitude)
	})
	return out
}

// AcceptingLaboratories returns active laboratory nodes that accept the given sample type.
func (n *Network) AcceptingLaboratories(accepted map[string]bool) []*Node {
	var out []*Node
	for _, loc := range n.Locations {
		if loc.Active && loc.Laboratory {
			out = append(out, loc)
		}
	}
	return out
}

// Path describes a computed route.
type Path struct {
	Nodes           []*Node
	Edges           []*Edge
	TotalMinutes    int
	TotalCost       float64
	AllCooled       bool
}

// FindPath finds the cheapest (by cost) path from start to any of the goal locations,
// respecting cooled requirements (requiresCooled: only use cooled edges), and active edges.
// Returns the best path to each goal; caller picks the best.
func (n *Network) FindPath(startID string, goalIDs map[string]bool, requiresCooled bool, requireCooledEdges bool) *Path {
	if _, ok := n.Locations[startID]; !ok {
		return nil
	}
	type state struct {
		loc      string
		minutes  int
		cost     float64
		path     []*Edge
		nodes    []*Node
	}
	bestByGoal := map[string]*Path{}
	visited := map[string]int{} // loc -> best minutes
	queue := []state{{loc: startID, minutes: 0, cost: 0, nodes: []*Node{n.Locations[startID]}}}
	for len(queue) > 0 {
		// pop smallest minutes (Dijkstra-ish by time)
		sort.Slice(queue, func(i, j int) bool { return queue[i].minutes < queue[j].minutes })
		cur := queue[0]
		queue = queue[1:]
		if prev, ok := visited[cur.loc]; ok && prev <= cur.minutes {
			continue
		}
		visited[cur.loc] = cur.minutes
		if goalIDs[cur.loc] {
			p := &Path{Nodes: cur.nodes, Edges: cur.path, TotalMinutes: cur.minutes, TotalCost: cur.cost, AllCooled: true}
			for _, e := range cur.path {
				if !e.Cooled {
					p.AllCooled = false
				}
			}
			bestByGoal[cur.loc] = p
			continue
		}
		for _, e := range n.Edges[cur.loc] {
			if !e.Active {
				continue
			}
			if requireCooledEdges && !e.Cooled {
				continue
			}
			nextLoc := e.To
			if _, ok := n.Locations[nextLoc]; !ok {
				continue
			}
			// only traverse via active locations (except allow reaching inactive? no).
			if !n.Locations[nextLoc].Active {
				continue
			}
			handling := n.Locations[nextLoc].HandlingMinutes
			nm := cur.minutes + e.TravelMinutes + handling
			nc := cur.cost + e.CostUnits
			np := append(append([]*Edge{}, cur.path...), e)
			nn := append(append([]*Node{}, cur.nodes...), n.Locations[nextLoc])
			queue = append(queue, state{loc: nextLoc, minutes: nm, cost: nc, path: np, nodes: nn})
		}
	}
	// pick best path among goals by total cost (then minutes)
	var best *Path
	for _, p := range bestByGoal {
		if best == nil || p.TotalCost < best.TotalCost || (p.TotalCost == best.TotalCost && p.TotalMinutes < best.TotalMinutes) {
			best = p
		}
	}
	return best
}

// EarliestArrival computes the earliest arrival time given earliest start and path.
func (p *Path) EarliestArrival(earliestStart time.Time, handlingPerNode int) time.Time {
	t := earliestStart
	for _, e := range p.Edges {
		t = t.Add(time.Duration(e.TravelMinutes) * time.Minute)
		t = t.Add(time.Duration(handlingPerNode) * time.Minute)
	}
	return t
}

