			return
		}
		_, _ = a.Pool.Exec(ctx, `INSERT INTO handoff_confirmations (handoff_id, side, confirmed_by, confirmed_at) VALUES ($1,'sender',$2,$3) ON CONFLICT DO NOTHING`, req.HandoffID, u.UserID, confirmedAt)
		_, _ = a.Pool.Exec(ctx, `UPDATE handoffs SET sender_confirmed=true WHERE handoff_id=$1`, req.HandoffID)
		senderConfirmed = true
	} else {
