func (a *App) CheckServiceability(w http.ResponseWriter, r *http.Request) {
	_, role, err := a.requireRole(r.Context(), auth.RoleRequester, auth.RoleDispatcher, auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req checkServiceabilityReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	originType := req.OriginType
	if originType == "" {
		originType = "home"
	}
	if originType != "home" && originType != "clinic" && originType != "node" {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_origin_type", "invalid originType"))
		return
	}
	if originType == "node" && isBlank(req.OriginNodeID) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_origin", "originNodeId required for node origin"))
		return
	}
	if isBlank(req.SampleTypeID) {
		writeErr(w, apiErr(http.StatusBadRequest, "not_found", "sampleTypeId required"))
		return
	}
	deadline, err := parseTime(req.DeliveryDeadline)
	if err != nil || deadline.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_deadline", "invalid deliveryDeadline"))
		return
	}
	requestedAt, err := parseTime(req.RequestedAt)
	if err != nil {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid requestedAt"))
		return
	}
	if requestedAt.IsZero() {
		requestedAt = time.Now().UTC()
	}
	var earliest, latest time.Time
	if req.EarliestCollectionAt != "" {
		earliest, err = parseTime(req.EarliestCollectionAt)
		if err != nil {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_collection_window", "invalid earliestCollectionAt"))
			return
		}
	}
	if req.LatestCollectionAt != "" {
		latest, err = parseTime(req.LatestCollectionAt)
		if err != nil {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_collection_window", "invalid latestCollectionAt"))
			return
		}
	}
	if !earliest.IsZero() && !latest.IsZero() && earliest.After(latest) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_collection_window", "earliest after latest"))
		return
	}
	// validate sample type exists + handling rules
	st, err := a.loadSampleType(r.Context(), req.SampleTypeID)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "sample type not found"))
		return
	}
	ctx := r.Context()
	res := a.Svc.Check(req.Origin, originType, req.OriginNodeID, req.SampleTypeID, st.RequiresCooledRoute, deadline, earliest)
	out := map[string]interface{}{
		"serviceable":           res.Serviceable,
		"reason":                res.Reason,
		"serviceabilityVersion": res.Version,
	}
	if res.TargetLaboratoryID != "" {
		out["targetLaboratoryId"] = res.TargetLaboratoryID
	}
	if !res.EstimatedArrivalAt.IsZero() {
		out["estimatedArrivalAt"] = fmtTimeT(res.EstimatedArrivalAt)
	}
	a.record(ctx, "", role, "check_serviceability", "sample_type", req.SampleTypeID, true, map[string]interface{}{"serviceable": res.Serviceable, "reason": res.Reason})
	// Dry run: nothing is created.
	web.Data(w, http.StatusOK, out)
}

// -------- Create collection request --------

