		_, _ = a.Pool.Exec(ctx, `INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`,
			userID, c.Code, c.Active, exp)
	}
	if _, err := a.Pool.Exec(ctx, `INSERT INTO worker_availability (user_id, available, capacity_units) VALUES ($1,true,4) ON CONFLICT (user_id) DO NOTHING`, userID); err != nil && !isMissingTable(err) {
		// best-effort
	}
	view, _ := a.loadUser(ctx, userID)
	a.record(ctx, u.UserID, role, "create_user", "user", userID, true, map[string]interface{}{"username": req.Username, "roles": req.Roles})
	web.Data(w, http.StatusCreated, view)
}

type updateUserReq struct {
	UserID             string                 `json:"userId"`
	Roles              []string               `json:"roles"`
	Qualifications     []string               `json:"qualifications"`
	Certifications     []domain.Certification `json:"certifications"`
	Active             bool                   `json:"active"`
	AssignedLocationID string                 `json:"assignedLocationId"`
}

func (a *App) UpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req updateUserReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if isBlank(req.UserID) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_user", "userId required"))
		return
	}
	for _, ro := range req.Roles {
		if !auth.IsValidRole(ro) {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_role", "invalid role: "+ro))
			return
		}
	}
	for _, c := range req.Certifications {
		if isBlank(c.Code) {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_certification", "cert code required"))
			return
		}
	}
	ctx := r.Context()
	rolesArr := pgStringArray(req.Roles)
	qualsArr := pgStringArray(req.Qualifications)
	ct, err := a.Pool.Exec(ctx,
		`UPDATE users SET roles=$2, qualifications=$3, active=$4, assigned_location_id=$5::uuid, updated_at=now() WHERE user_id=$1`,
		req.UserID, rolesArr, qualsArr, req.Active, nullStr(req.AssignedLocationID))
	if err != nil {
		writeErr(w, err)
		return
	}
	if ct.RowsAffected() == 0 {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "user not found"))
		return
	}
	_, _ = a.Pool.Exec(ctx, `DELETE FROM user_certifications WHERE user_id=$1`, req.UserID)
	for _, c := range req.Certifications {
		var exp *time.Time
		if c.ExpiresAt != nil && *c.ExpiresAt != "" {
			t, perr := parseTime(*c.ExpiresAt)
			if perr == nil {
				exp = &t
			}
		}
		_, _ = a.Pool.Exec(ctx, `INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`,
			req.UserID, c.Code, c.Active, exp)
	}
	view, _ := a.loadUser(ctx, req.UserID)
	a.record(ctx, u.UserID, role, "update_user_access", "user", req.UserID, true, map[string]interface{}{"roles": req.Roles})
	web.Data(w, http.StatusCreated, view)
}

func (a *App) ReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	u := auth.FromContext(r.Context())
	if u == nil {
		web.Error(w, http.StatusUnauthorized, "unauthorized", "unauthorized")
		return
	}
	ctx := r.Context()
	role := auth.RoleFromContext(ctx)
	view, _ := a.loadUser(ctx, u.UserID)
	out := map[string]interface{}{
		"user": map[string]interface{}{
			"userId":                 view.UserID,
			"username":               view.Username,
			"fullName":               view.FullName,
			"roles":                  strArr(u.Roles),
			"activeRole":             role,
			"roleSelectionRequired": role == "",
		},
		"serverTime": time.Now().UTC().Format(time.RFC3339Nano),
	}
	// requester samples
	if role == auth.RoleRequester {
		samples, _ := a.requesterSamples(ctx, u.UserID)
		out["requesterSamples"] = samples
	}
	// operations state for dispatcher/admin
	if role == auth.RoleDispatcher || role == auth.RoleAdministrator {
		ops, _ := a.operationsState(ctx, nil)
		out["operations"] = ops
	}
	web.Data(w, http.StatusOK, out)
}

func (a *App) requesterSamples(ctx context.Context, requesterID string) ([]map[string]interface{}, error) {
	rows, err := a.Pool.Query(ctx,
		`SELECT s.sample_id, s.request_id, s.status, s.serviceable, s.origin_type,
		        s.requested_at, s.delivery_deadline, s.active_journey_id, s.target_laboratory_id,
		        s.latest_latitude, s.latest_longitude, s.location_recorded_at
		 FROM samples s WHERE s.requester_id=$1 ORDER BY s.created_at DESC`, requesterID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []map[string]interface{}
	for rows.Next() {
		var sampleID, requestID, status, originType string
		var serviceable bool
		var requestedAt, deadline time.Time
		var journeyID, labID *string
		var lat, lon *float64
		var locAt *time.Time
		if err := rows.Scan(&sampleID, &requestID, &status, &serviceable, &originType, &requestedAt, &deadline, &journeyID, &labID, &lat, &lon, &locAt); err != nil {
			return nil, err
		}
		item := map[string]interface{}{
			"sampleId": sampleID, "requestId": requestID, "status": status,
			"serviceability": serviceabilityStr(serviceable), "originType": originType,
			"requestedAt": fmtTimeT(requestedAt), "deliveryDeadline": fmtTimeT(deadline),
			"locationStale": stale(locAt, a.Cfg.StaleMinutes),
		}
		if journeyID != nil {
			item["activeJourneyId"] = *journeyID
		}
		if labID != nil {
			item["targetLaboratoryId"] = *labID
		}
		if lat != nil && lon != nil {
			item["latestLocation"] = domain.Coordinate{Latitude: *lat, Longitude: *lon}
		}
		if locAt != nil {
			item["locationRecordedAt"] = fmtTime(locAt)
		}
		out = append(out, item)
	}
	if out == nil {
		out = []map[string]interface{}{}
	}
	return out, nil
}

func serviceabilityStr(b bool) string {
	if b {
		return "serviceable"
	}
	return "unserviceable"
}

// helpers
func pgStringArray(a []string) string {
	if a == nil {
		return "{}"
	}
	b, _ := json.Marshal(a)
	return string(b)
}

// pgUUIDArray formats a string slice as a Postgres uuid[] literal "{}" for ::uuid[] casts.
func pgUUIDArray(a []string) string {
	if len(a) == 0 {
		return "{}"
	}
	return "{" + strings.Join(a, ",") + "}"
}

func nullStr(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

func isDupUser(err error) bool {
	if err == nil {
		return false
	}
	return contains(err.Error(), "duplicate key") || contains(err.Error(), "username")
}

func isMissingTable(err error) bool {
	if err == nil {
		return false
	}
	return contains(err.Error(), "does not exist") || contains(err.Error(), "relation")
}

func contains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

