package api

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
"strings"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"lablogistics/internal/auth"
	"lablogistics/internal/domain"
	"lablogistics/internal/web"
)

type authenticateReq struct {
	Username string `json:"username"`
	Password string `json:"password"`
}

type authenticateResp struct {
	SessionToken string   `json:"sessionToken"`
	UserID       string   `json:"userId"`
	Roles        []string `json:"roles"`
	ActiveRole   string   `json:"activeRole"`
}

func (a *App) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req authenticateReq
	if err := web.DecodeJSON(r, &req); err != nil {
		web.Error(w, http.StatusBadRequest, "invalid_json", "invalid json")
		return
	}
	if req.Username == "" || req.Password == "" {
		web.Error(w, http.StatusUnauthorized, "invalid_credentials", "invalid credentials")
		return
	}
	ctx := r.Context()
	var userID, hash, fullName string
	var roles []string
	var active bool
	err := a.Pool.QueryRow(ctx,
		`SELECT user_id, password_hash, COALESCE(full_name,''), roles, active FROM users WHERE username=$1`,
		req.Username).Scan(&userID, &hash, &fullName, &roles, &active)
	if err != nil || !active || !auth.VerifyPassword(req.Password, hash) {
		web.Error(w, http.StatusUnauthorized, "invalid_credentials", "invalid credentials")
		a.record(ctx, "", "", "sign_in", "user", "", false, map[string]interface{}{"username": req.Username})
		return
	}
	token := auth.NewSessionToken()
	activeRole := ""
	if len(roles) > 0 {
		activeRole = roles[0]
	}
	_, _ = a.Pool.Exec(ctx,
		`INSERT INTO sessions (session_token, user_id, active_role, expires_at) VALUES ($1,$2,$3,$4)`,
		token, userID, activeRole, time.Now().Add(24*time.Hour))
	a.record(ctx, userID, activeRole, "sign_in", "user", userID, true, map[string]interface{}{"username": req.Username})
	a.record(ctx, userID, activeRole, "permission_check", "session", token, true, map[string]interface{}{"roles": roles})
	web.Data(w, http.StatusOK, authenticateResp{SessionToken: token, UserID: userID, Roles: strArr(roles), ActiveRole: activeRole})
}

type selectRoleReq struct {
	Role string `json:"role"`
}

func (a *App) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	u := auth.FromContext(r.Context())
	if u == nil {
		web.Error(w, http.StatusUnauthorized, "unauthorized", "unauthorized")
		return
	}
	var req selectRoleReq
	if err := web.DecodeJSON(r, &req); err != nil {
		web.Error(w, http.StatusBadRequest, "invalid_json", "invalid json")
		return
	}
	if !auth.IsValidRole(req.Role) {
		web.Error(w, http.StatusBadRequest, "invalid_role", "invalid role")
		return
	}
	held := false
	for _, ro := range u.Roles {
		if ro == req.Role {
			held = true
			break
		}
	}
	if !held {
		web.Error(w, http.StatusForbidden, "role_not_held", "role not held")
		return
	}
	ctx := r.Context()
	// Persist selection by session token (from context header)
	tok := auth.ExtractBearer(r)
	if tok != "" {
		_, _ = a.Pool.Exec(ctx, `UPDATE sessions SET active_role=$2 WHERE session_token=$1`, tok, req.Role)
	}
	a.record(ctx, u.UserID, req.Role, "select_role", "user", u.UserID, true, map[string]interface{}{"role": req.Role})
	web.Data(w, http.StatusOK, map[string]interface{}{"activeRole": req.Role, "roles": strArr(u.Roles)})
}

func (a *App) ReadUser(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	userID := r.PathValue("userId")
	if userID == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "not_found", "missing userId"))
		return
	}
	ctx := r.Context()
	d, err := a.loadUser(ctx, userID)
	if err != nil {
		writeErr(w, err)
		return
	}
	a.record(ctx, u.UserID, role, "read_user", "user", userID, true, nil)
	web.Data(w, http.StatusOK, d)
}

type createUserReq struct {
	Username          string                  `json:"username"`
	InitialPassword   string                  `json:"initialPassword"`
	Email             string                  `json:"email"`
	FullName          string                  `json:"fullName"`
	Phone             string                  `json:"phone"`
	Roles             []string                `json:"roles"`
	Qualifications    []string                `json:"qualifications"`
	Certifications    []domain.Certification  `json:"certifications"`
	Active            bool                    `json:"active"`
	AssignedLocationID string                 `json:"assignedLocationId"`
}

type userView struct {
	UserID         string                 `json:"userId"`
	Username       string                 `json:"username"`
	Email          string                 `json:"email"`
	FullName       string                 `json:"fullName"`
	Phone          string                 `json:"phone"`
	Roles          []string               `json:"roles"`
	Qualifications []string               `json:"qualifications"`
	Certifications []domain.Certification `json:"certifications"`
	Active         bool                   `json:"active"`
}

func (a *App) loadUser(ctx context.Context, userID string) (userView, error) {
	var v userView
	var roles, quals []string
	var email, fullName, phone *string
	err := a.Pool.QueryRow(ctx,
		`SELECT user_id, username, email, full_name, phone, roles, qualifications, active
		 FROM users WHERE user_id=$1`, userID).
		Scan(&v.UserID, &v.Username, &email, &fullName, &phone, &roles, &quals, &v.Active)
	if err != nil {
		return v, err
	}
	if email != nil {
		v.Email = *email
	}
	if fullName != nil {
		v.FullName = *fullName
	}
	if phone != nil {
		v.Phone = *phone
	}
	v.Roles = strArr(roles)
	v.Qualifications = strArr(quals)
	certs, _ := a.loadCerts(ctx, userID)
	v.Certifications = certs
	return v, nil
}

func (a *App) loadCerts(ctx context.Context, userID string) ([]domain.Certification, error) {
	rows, err := a.Pool.Query(ctx, `SELECT code, active, expires_at FROM user_certifications WHERE user_id=$1`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []domain.Certification
	for rows.Next() {
		var c domain.Certification
		var exp *time.Time
		if err := rows.Scan(&c.Code, &c.Active, &exp); err != nil {
			return nil, err
		}
		if exp != nil {
			s := exp.UTC().Format(time.RFC3339Nano)
			c.ExpiresAt = &s
		}
		out = append(out, c)
	}
	if out == nil {
		out = []domain.Certification{}
	}
	return out, nil
}

func (a *App) CreateUser(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req createUserReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if isBlank(req.Username) || isBlank(req.InitialPassword) || len(req.Roles) == 0 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_user", "missing required fields"))
		return
	}
	for _, ro := range req.Roles {
		if !auth.IsValidRole(ro) {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_user", "invalid role: "+ro))
			return
		}
	}
	for _, c := range req.Certifications {
		if isBlank(c.Code) {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_certification", "cert code required"))
			return
		}
	}
	hash, err := auth.HashPassword(req.InitialPassword)
	if err != nil {
		writeErr(w, err)
		return
	}
	ctx := r.Context()
	var userID string
	rolesArr := pgStringArray(req.Roles)
	qualsArr := pgStringArray(req.Qualifications)
	err = a.Pool.QueryRow(ctx,
		`INSERT INTO users (username, password_hash, email, full_name, phone, roles, qualifications, active, assigned_location_id)
		 VALUES ($1,$2,$3,$4,$5,$6,$7,$8, $9::uuid) RETURNING user_id`,
		req.Username, hash, nullStr(req.Email), nullStr(req.FullName), nullStr(req.Phone), rolesArr, qualsArr, req.Active, nullStr(req.AssignedLocationID),
	).Scan(&userID)
	if err != nil {
		if isDupUser(err) {
			writeErr(w, apiErr(http.StatusConflict, "username_exists", "username exists"))
			return
		}
		writeErr(w, err)
		return
	}
	for _, c := range req.Certifications {
		var exp *time.Time
		if c.ExpiresAt != nil && *c.ExpiresAt != "" {
			t, perr := parseTime(*c.ExpiresAt)
			if perr == nil {
				exp = &t
			}
		}
		_, _ = a.Pool.Exec(ctx, `INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`,
			userID, c.Code, c.Active, exp)
	}
	if _, err := a.Pool.Exec(ctx, `INSERT INTO worker_availability (user_id, available, capacity_units) VALUES ($1,true,4) ON CONFLICT (user_id) DO NOTHING`, userID); err != nil && !isMissingTable(err) {
		// best-effort
	}
	view, _ := a.loadUser(ctx, userID)
	a.record(ctx, u.UserID, role, "create_user", "user", userID, true, map[string]interface{}{"username": req.Username, "roles": req.Roles})
	web.Data(w, http.StatusCreated, view)
}

type updateUserReq struct {
	UserID             string                 `json:"userId"`
	Roles              []string               `json:"roles"`
	Qualifications     []string               `json:"qualifications"`
	Certifications     []domain.Certification `json:"certifications"`
	Active             bool                   `json:"active"`
	AssignedLocationID string                 `json:"assignedLocationId"`
}

func (a *App) UpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req updateUserReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if isBlank(req.UserID) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_user", "userId required"))
		return
	}
	for _, ro := range req.Roles {
		if !auth.IsValidRole(ro) {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_role", "invalid role: "+ro))
			return
		}
	}
	for _, c := range req.Certifications {
		if isBlank(c.Code) {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_certification", "cert code required"))
			return
		}
	}
	ctx := r.Context()
	rolesArr := pgStringArray(req.Roles)
	qualsArr := pgStringArray(req.Qualifications)
	ct, err := a.Pool.Exec(ctx,
		`UPDATE users SET roles=$2, qualifications=$3, active=$4, assigned_location_id=$5::uuid, updated_at=now() WHERE user_id=$1`,
		req.UserID, rolesArr, qualsArr, req.Active, nullStr(req.AssignedLocationID))
	if err != nil {
		writeErr(w, err)
		return
	}
	if ct.RowsAffected() == 0 {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "user not found"))
		return
	}
	_, _ = a.Pool.Exec(ctx, `DELETE FROM user_certifications WHERE user_id=$1`, req.UserID)
	for _, c := range req.Certifications {
		var exp *time.Time
		if c.ExpiresAt != nil && *c.ExpiresAt != "" {
			t, perr := parseTime(*c.ExpiresAt)
			if perr == nil {
				exp = &t
			}
		}
		_, _ = a.Pool.Exec(ctx, `INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`,
			req.UserID, c.Code, c.Active, exp)
	}
	view, _ := a.loadUser(ctx, req.UserID)
	a.record(ctx, u.UserID, role, "update_user_access", "user", req.UserID, true, map[string]interface{}{"roles": req.Roles})
	web.Data(w, http.StatusCreated, view)
}

func (a *App) ReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	u := auth.FromContext(r.Context())
	if u == nil {
		web.Error(w, http.StatusUnauthorized, "unauthorized", "unauthorized")
		return
	}
	ctx := r.Context()
	role := auth.RoleFromContext(ctx)
	view, _ := a.loadUser(ctx, u.UserID)
	out := map[string]interface{}{
		"user": map[string]interface{}{
			"userId":                 view.UserID,
			"username":               view.Username,
			"fullName":               view.FullName,
			"roles":                  strArr(u.Roles),
			"activeRole":             role,
			"roleSelectionRequired": role == "",
		},
		"serverTime": time.Now().UTC().Format(time.RFC3339Nano),
	}
	// requester samples
	if role == auth.RoleRequester {
		samples, _ := a.requesterSamples(ctx, u.UserID)
		out["requesterSamples"] = samples
	}
	// operations state for dispatcher/admin
	if role == auth.RoleDispatcher || role == auth.RoleAdministrator {
		ops, _ := a.operationsState(ctx, nil)
		out["operations"] = ops
	}
	web.Data(w, http.StatusOK, out)
}

func (a *App) requesterSamples(ctx context.Context, requesterID string) ([]map[string]interface{}, error) {
	rows, err := a.Pool.Query(ctx,
		`SELECT s.sample_id, s.request_id, s.status, s.serviceable, s.origin_type,
		        s.requested_at, s.delivery_deadline, s.active_journey_id, s.target_laboratory_id,
		        s.latest_latitude, s.latest_longitude, s.location_recorded_at
		 FROM samples s WHERE s.requester_id=$1 ORDER BY s.created_at DESC`, requesterID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []map[string]interface{}
	for rows.Next() {
		var sampleID, requestID, status, originType string
		var serviceable bool
		var requestedAt, deadline time.Time
		var journeyID, labID *string
		var lat, lon *float64
		var locAt *time.Time
		if err := rows.Scan(&sampleID, &requestID, &status, &serviceable, &originType, &requestedAt, &deadline, &journeyID, &labID, &lat, &lon, &locAt); err != nil {
			return nil, err
		}
		item := map[string]interface{}{
			"sampleId": sampleID, "requestId": requestID, "status": status,
			"serviceability": serviceabilityStr(serviceable), "originType": originType,
			"requestedAt": fmtTimeT(requestedAt), "deliveryDeadline": fmtTimeT(deadline),
			"locationStale": stale(locAt, a.Cfg.StaleMinutes),
		}
		if journeyID != nil {
			item["activeJourneyId"] = *journeyID
		}
		if labID != nil {
			item["targetLaboratoryId"] = *labID
		}
		if lat != nil && lon != nil {
			item["latestLocation"] = domain.Coordinate{Latitude: *lat, Longitude: *lon}
		}
		if locAt != nil {
			item["locationRecordedAt"] = fmtTime(locAt)
		}
		out = append(out, item)
	}
	if out == nil {
		out = []map[string]interface{}{}
	}
	return out, nil
}

func serviceabilityStr(b bool) string {
	if b {
		return "serviceable"
	}
	return "unserviceable"
}

// helpers
// pgStringArray formats a string slice as a Postgres array literal "{}",
// usable for both text[] columns and ::uuid[] casts.
func pgStringArray(a []string) string {
	if len(a) == 0 {
		return "{}"
	}
	return "{" + strings.Join(a, ",") + "}"
}

// pgUUIDArray is an alias kept for clarity (same format).
func pgUUIDArray(a []string) string {
	return pgStringArray(a)
}

func nullStr(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

func isDupUser(err error) bool {
	if err == nil {
		return false
	}
	return contains(err.Error(), "duplicate key") || contains(err.Error(), "username")
}

func isMissingTable(err error) bool {
	if err == nil {
		return false
	}
	return contains(err.Error(), "does not exist") || contains(err.Error(), "relation")
}

func contains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

var _ = errors.New
