	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"lablogistics/internal/audit"
	"lablogistics/internal/auth"
	"lablogistics/internal/config"
	"lablogistics/internal/domain"
	"lablogistics/internal/events"
	"lablogistics/internal/serviceability"
	smongo "lablogistics/internal/storemongo"
	"lablogistics/internal/web"
)

type App struct {
	Cfg    *config.Config
	Pool   *pgxpool.Pool
	Mongo  *smongo.Store
	Audit  *audit.Service
	Events *events.Service
	Svc    *serviceability.Service
}

func NewApp(cfg *config.Config, pool *pgxpool.Pool, mongo *smongo.Store, asvc *serviceability.Service) *App {
	return &App{
		Cfg:    cfg,
		Pool:   pool,
		Mongo:  mongo,
		Audit:  audit.New(pool, mongo),
		Events: events.New(pool, mongo),
		Svc:    asvc,
	}
}

// EnsureAdmin creates the first administrator account if no users exist.
func (a *App) EnsureAdmin(ctx context.Context) error {
	var count int
	err := a.Pool.QueryRow(ctx, `SELECT count(*) FROM users`).Scan(&count)
	if err != nil {
		return err
	}
	if count > 0 {
		return nil
	}
	hash, err := auth.HashPassword(a.Cfg.AdminPassword)
	if err != nil {
		return err
	}
	_, err = a.Pool.Exec(ctx,
		`INSERT INTO users (username, password_hash, full_name, roles, active) VALUES ($1,$2,$3,$4,true)`,
		a.Cfg.AdminUsername, hash, "System Administrator", fmt.Sprintf("{%s}", auth.RoleAdministrator))
	return err
}

func (a *App) record(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
	if a.Audit != nil {
		_, _ = a.Audit.Record(ctx, actorID, role, action, entityType, entityID, success, details)
	}
}

func (a *App) emit(ctx context.Context, eventType, entityType, entityID string, payload map[string]interface{}) {
	if a.Events != nil {
		_, _ = a.Events.Publish(ctx, eventType, entityType, entityID, payload)
	}
}

func stale(locRecordedAt *time.Time, staleMin int) bool {
	if locRecordedAt == nil {
		return true
	}
	return time.Since(*locRecordedAt) > time.Duration(staleMin)*time.Minute
}

func fmtTime(t *time.Time) string {
	if t == nil {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func fmtTimeT(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func parseTime(s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, nil
	}
	t, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		// try common layouts
		t, err = time.Parse(time.RFC3339, s)
		if err != nil {
			return time.Time{}, err
		}
	}
	return t, nil
}

func strArr(a []string) []string {
	if a == nil {
		return []string{}
	}
	return a
}

type apiError struct {
	status int
	code   string
	msg    string
}

func apiErr(status int, code, msg string) *apiError { return &apiError{status, code, msg} }

func (e *apiError) Error() string { return e.msg }

func writeErr(w http.ResponseWriter, err error) {
	if err == nil {
		return
	}
	var ae *apiError
	if errors.As(err, &ae) {
		web.Error(w, ae.status, ae.code, ae.msg)
		return
	}
	if errors.Is(err, pgx.ErrNoRows) || errors.Is(err, sql.ErrNoRows) {
		web.Error(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	var te *json.SyntaxError
	var ut *json.UnmarshalTypeError
	if errors.As(err, &te) || errors.As(err, &ut) {
		web.Error(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	web.ErrInternal(w)
}

func (a *App) requireRole(ctx context.Context, allowed ...string) (*auth.SessionUser, string, error) {
	u := auth.FromContext(ctx)
	if u == nil {
		return nil, "", apiErr(http.StatusUnauthorized, "unauthorized", "unauthorized")
	}
	role := auth.RoleFromContext(ctx)
	if role == "" {
		return u, "", apiErr(http.StatusConflict, "role_not_selected", "active role not selected")
	}
	ok := false
	for _, r := range allowed {
		if r == role {
			ok = true
			break
		}
	}
	if !ok {
		return u, role, apiErr(http.StatusForbidden, "forbidden", "role not permitted")
	}
	held := false
	for _, r := range u.Roles {
		if r == role {
			held = true
			break
		}
	}
	if !held {
		return u, role, apiErr(http.StatusForbidden, "role_not_held", "role not held")
	}
	return u, role, nil
}

func isBlank(s string) bool { return strings.TrimSpace(s) == "" }

// requireAnyRole accepts a slice of allowed roles (alias for requireRole spread).
func (a *App) requireAnyRole(ctx context.Context, allowed []string) (*auth.SessionUser, string, error) {
	return a.requireRole(ctx, allowed...)
}

