package api

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"time"

	"github.com/google/uuid"

	"lablogistics/internal/auth"
	"lablogistics/internal/domain"
	"lablogistics/internal/routing"
	"lablogistics/internal/web"
)

// -------- Serviceability check (dry run) --------

type checkServiceabilityReq struct {
	Origin               domain.Coordinate `json:"origin"`
	OriginType           string            `json:"originType"`
	OriginNodeID         string            `json:"originNodeId"`
	SampleTypeID         string            `json:"sampleTypeId"`
	RequestedAt          string            `json:"requestedAt"`
	DeliveryDeadline     string            `json:"deliveryDeadline"`
	EarliestCollectionAt string            `json:"earliestCollectionAt"`
	LatestCollectionAt   string            `json:"latestCollectionAt"`
}

func (a *App) CheckServiceability(w http.ResponseWriter, r *http.Request) {
	_, role, err := a.requireRole(r.Context(), auth.RoleRequester, auth.RoleDispatcher, auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req checkServiceabilityReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	originType := req.OriginType
	if originType == "" {
		originType = "home"
	}
	if originType != "home" && originType != "clinic" && originType != "node" {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_origin_type", "invalid originType"))
		return
	}
	if originType == "node" && isBlank(req.OriginNodeID) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_origin", "originNodeId required for node origin"))
		return
	}
	if isBlank(req.SampleTypeID) {
		writeErr(w, apiErr(http.StatusBadRequest, "not_found", "sampleTypeId required"))
		return
	}
	deadline, err := parseTime(req.DeliveryDeadline)
	if err != nil || deadline.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_deadline", "invalid deliveryDeadline"))
		return
	}
	requestedAt, err := parseTime(req.RequestedAt)
	if err != nil {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid requestedAt"))
		return
	}
	if requestedAt.IsZero() {
		requestedAt = time.Now().UTC()
	}
	var earliest, latest time.Time
	if req.EarliestCollectionAt != "" {
		earliest, err = parseTime(req.EarliestCollectionAt)
		if err != nil {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_collection_window", "invalid earliestCollectionAt"))
			return
		}
	}
	if req.LatestCollectionAt != "" {
		latest, err = parseTime(req.LatestCollectionAt)
		if err != nil {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_collection_window", "invalid latestCollectionAt"))
			return
		}
	}
	if !earliest.IsZero() && !latest.IsZero() && earliest.After(latest) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_collection_window", "earliest after latest"))
		return
	}
	// validate sample type exists + handling rules
	st, err := a.loadSampleType(r.Context(), req.SampleTypeID)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "sample type not found"))
		return
	}
	ctx := r.Context()
	res := a.Svc.Check(req.Origin, originType, req.OriginNodeID, req.SampleTypeID, st.RequiresCooledRoute, deadline, earliest)
	out := map[string]interface{}{
		"serviceable":           res.Serviceable,
		"reason":                res.Reason,
		"serviceabilityVersion": res.Version,
	}
	if res.TargetLaboratoryID != "" {
		out["targetLaboratoryId"] = res.TargetLaboratoryID
	}
	if !res.EstimatedArrivalAt.IsZero() {
		out["estimatedArrivalAt"] = fmtTimeT(res.EstimatedArrivalAt)
	}
	a.record(ctx, "", role, "check_serviceability", "sample_type", req.SampleTypeID, true, map[string]interface{}{"serviceable": res.Serviceable, "reason": res.Reason})
	// Dry run: nothing is created.
	web.Data(w, http.StatusOK, out)
}

// -------- Create collection request --------

type createRequestReq struct {
	RequesterID             string            `json:"requesterId"`
	Origin                  domain.Coordinate `json:"origin"`
	OriginType              string            `json:"originType"`
	OriginNodeID            string            `json:"originNodeId"`
	RequestedAt             string            `json:"requestedAt"`
	DeliveryDeadline        string            `json:"deliveryDeadline"`
	EarliestCollectionAt    string            `json:"earliestCollectionAt"`
	LatestCollectionAt      string            `json:"latestCollectionAt"`
	SampleTypeID            string            `json:"sampleTypeId"`
	ContainerType           string            `json:"containerType"`
	TemperatureMinC         float64           `json:"temperatureMinC"`
	TemperatureMaxC         float64           `json:"temperatureMaxC"`
	IncompatibleSampleTypes []string          `json:"incompatibleSampleTypes"`
	IdempotencyKey          string            `json:"idempotencyKey"`
}

type createRequestResp struct {
	RequestID            string   `json:"requestId"`
	SampleID             string   `json:"sampleId"`
	Serviceability       string   `json:"serviceability"`
	ServiceabilityReason string   `json:"serviceabilityReason,omitempty"`
	ActiveAssignmentIDs  []string `json:"activeAssignmentIds"`
	EarliestCollectionAt string   `json:"earliestCollectionAt"`
	LatestCollectionAt   string   `json:"latestCollectionAt"`
	JourneyID            string   `json:"journeyId,omitempty"`
	TargetLaboratoryID   string   `json:"targetLaboratoryId,omitempty"`
	AlreadySealed        bool     `json:"alreadySealed,omitempty"`
	OriginType           string   `json:"originType,omitempty"`
}

func (a *App) CreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleRequester, auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req createRequestReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	requesterID := req.RequesterID
	if requesterID == "" {
		requesterID = u.UserID
	}
	// requesters may only create for themselves
	if role == auth.RoleRequester && requesterID != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "forbidden", "requester can only create own requests"))
		return
	}
	originType := req.OriginType
	if originType == "" {
		originType = "home"
	}
	if originType == "home" {
		// home origin requires a collection point in coverage
	}
	deadline, err := parseTime(req.DeliveryDeadline)
	if err != nil || deadline.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_deadline", "invalid deliveryDeadline"))
		return
	}
	requestedAt, err := parseTime(req.RequestedAt)
	if err != nil {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid requestedAt"))
		return
	}
	if requestedAt.IsZero() {
		requestedAt = time.Now().UTC()
	}
	if !deadline.After(requestedAt) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_deadline", "deadline must be after requestedAt"))
		return
	}
	var earliest, latest time.Time
	if req.EarliestCollectionAt != "" {
		earliest, _ = parseTime(req.EarliestCollectionAt)
	}
	if req.LatestCollectionAt != "" {
		latest, _ = parseTime(req.LatestCollectionAt)
	}
	if !earliest.IsZero() && !latest.IsZero() && earliest.After(latest) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_collection_window", "earliest after latest"))
		return
	}
	if earliest.IsZero() {
		earliest = requestedAt
	}
	if latest.IsZero() {
		latest = deadline
	}
	st, err := a.loadSampleType(r.Context(), req.SampleTypeID)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "sample type not found"))
		return
	}
	// handling rule consistency with sample type
	if st.RequiresCooledRoute && req.TemperatureMaxC > 8 {
		// cooled sample should have low temp range; soft check
	}
	if req.TemperatureMinC > req.TemperatureMaxC {
		writeErr(w, apiErr(http.StatusBadRequest, "handling_mismatch", "temp min > max"))
		return
	}
	ctx := r.Context()
	// Serviceability dry-run-equivalent check (real, since we are creating).
	res := a.Svc.Check(req.Origin, originType, req.OriginNodeID, req.SampleTypeID, st.RequiresCooledRoute, deadline, earliest)

	// Create request + sample.
	var requestID, sampleID string
	err = a.Pool.QueryRow(ctx,
		`INSERT INTO collection_requests (requester_id, origin_latitude, origin_longitude, origin_type, origin_node_id,
		   requested_at, delivery_deadline, earliest_collection_at, latest_collection_at, already_sealed)
		 VALUES ($1,$2,$3,$4,$5::uuid,$6,$7,$8,$9,$10) RETURNING request_id`,
		requesterID, req.Origin.Latitude, req.Origin.Longitude, originType, nullStr(req.OriginNodeID),
		requestedAt, deadline, earliest, latest, false,
	).Scan(&requestID)
	if err != nil {
		writeErr(w, err)
		return
	}
	incArr := pgStringArray(mergeInc(req.IncompatibleSampleTypes, st.IncompatibleSampleTypes))
	err = a.Pool.QueryRow(ctx,
		`INSERT INTO samples (request_id, sample_type_id, requester_id, container_type, temperature_min_c, temperature_max_c,
		   incompatible_sample_types, origin_latitude, origin_longitude, origin_type, origin_node_id,
		   requested_at, delivery_deadline, status, serviceable, target_laboratory_id)
		 VALUES ($1,$2,$3,$4,$5,$6,$7::uuid[],$8,$9,$10,$11::uuid,$12,$13,'requested',$14,$15::uuid) RETURNING sample_id`,
		requestID, req.SampleTypeID, requesterID, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC,
		incArr, req.Origin.Latitude, req.Origin.Longitude, originType, nullStr(req.OriginNodeID),
		requestedAt, deadline, res.Serviceable, nullStr(res.TargetLaboratoryID),
	).Scan(&sampleID)
	if err != nil {
		writeErr(w, err)
		return
	}

	activeAssignments := []string{}
	var journeyID string
	if res.Serviceable && res.Path != nil {
		j, aIDs, perr := a.createJourney(ctx, createJourneyInput{
			SampleID:        sampleID,
			SampleTypeID:    req.SampleTypeID,
			Origin:          req.Origin,
			OriginType:      originType,
			EntryNode:       res.CollectionPoint,
			Path:            res.Path,
			TargetLabID:     res.TargetLaboratoryID,
			Deadline:        deadline,
			Earliest:        earliest,
			RequiresCooled:  st.RequiresCooledRoute,
			BatchingAllowed: st.BatchingAllowed,
		})
		if perr == nil {
			journeyID = j
			activeAssignments = aIDs
		}
	}

	resp := createRequestResp{
		RequestID:            requestID,
		SampleID:             sampleID,
		Serviceability:       serviceabilityStr(res.Serviceable),
		ActiveAssignmentIDs:  activeAssignments,
		EarliestCollectionAt: fmtTimeT(earliest),
		LatestCollectionAt:   fmtTimeT(latest),
		JourneyID:            journeyID,
		OriginType:           originType,
	}
	if res.TargetLaboratoryID != "" {
		resp.TargetLaboratoryID = res.TargetLaboratoryID
	}
	if !res.Serviceable {
		resp.ServiceabilityReason = res.Reason
	}
	a.record(ctx, u.UserID, role, "create_collection_request", "sample", sampleID, true, map[string]interface{}{"requestId": requestID, "serviceable": res.Serviceable})
	a.emit(ctx, "sample.created", "sample", sampleID, map[string]interface{}{"requestId": requestID})
	web.Data(w, http.StatusCreated, resp)
}

// -------- Ingest presealed sample --------

type ingestPresealedReq struct {
	RequesterID             string            `json:"requesterId"`
	Origin                  domain.Coordinate `json:"origin"`
	OriginType              string            `json:"originType"`
	OriginNodeID            string            `json:"originNodeId"`
	RequestedAt             string            `json:"requestedAt"`
	DeliveryDeadline        string            `json:"deliveryDeadline"`
	EarliestCollectionAt    string            `json:"earliestCollectionAt"`
	LatestCollectionAt      string            `json:"latestCollectionAt"`
	SampleTypeID            string            `json:"sampleTypeId"`
	ContainerType           string            `json:"containerType"`
	TemperatureMinC         float64           `json:"temperatureMinC"`
	TemperatureMaxC         float64           `json:"temperatureMaxC"`
	IncompatibleSampleTypes []string          `json:"incompatibleSampleTypes"`
	IdempotencyKey          string            `json:"idempotencyKey"`
}

func (a *App) IngestPresealedSample(w http.ResponseWriter, r *http.Request) {
	// Pre-sealed ingestion: collection_professional, delivery_partner, node_handler, laboratory_team
	u, role, err := a.requireRole(r.Context(), auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam, auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req ingestPresealedReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	originType := req.OriginType
	if originType == "" {
		originType = "node"
	}
	if originType == "home" {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_origin_type", "presealed origin must be clinic or node"))
		return
	}
	// the registering person must currently hold it. Validate holder = caller.
	deadline, err := parseTime(req.DeliveryDeadline)
	if err != nil || deadline.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_deadline", "invalid deliveryDeadline"))
		return
	}
	requestedAt, _ := parseTime(req.RequestedAt)
	if requestedAt.IsZero() {
		requestedAt = time.Now().UTC()
	}
	var earliest, latest time.Time
	if req.EarliestCollectionAt != "" {
		earliest, _ = parseTime(req.EarliestCollectionAt)
	}
	if req.LatestCollectionAt != "" {
		latest, _ = parseTime(req.LatestCollectionAt)
	}
	if earliest.IsZero() {
		earliest = requestedAt
	}
	if latest.IsZero() {
		latest = deadline
	}
	st, err := a.loadSampleType(r.Context(), req.SampleTypeID)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "sample type not found"))
		return
	}
	originNodeID := req.OriginNodeID
	if originType == "node" && isBlank(originNodeID) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_origin", "originNodeId required"))
		return
	}
	if originType == "clinic" {
		// clinic must map to a collection point nearby
		cps := a.Svc.Current().Network.CollectionPoints(req.Origin.Latitude, req.Origin.Longitude, 5)
		if len(cps) == 0 {
			writeErr(w, apiErr(http.StatusBadRequest, "invalid_origin", "no collection point near clinic"))
			return
		}
		originNodeID = cps[0].LocationID
	}
	ctx := r.Context()
	res := a.Svc.Check(req.Origin, originType, originNodeID, req.SampleTypeID, st.RequiresCooledRoute, deadline, earliest)

	requesterID := req.RequesterID
	if requesterID == "" {
		requesterID = u.UserID
	}
	var requestID, sampleID string
	err = a.Pool.QueryRow(ctx,
		`INSERT INTO collection_requests (requester_id, origin_latitude, origin_longitude, origin_type, origin_node_id,
		   requested_at, delivery_deadline, earliest_collection_at, latest_collection_at, already_sealed)
		 VALUES ($1,$2,$3,$4,$5::uuid,$6,$7,$8,$9,true) RETURNING request_id`,
		requesterID, req.Origin.Latitude, req.Origin.Longitude, originType, nullStr(originNodeID),
		requestedAt, deadline, earliest, latest,
	).Scan(&requestID)
	if err != nil {
		writeErr(w, err)
		return
	}
	incArr := pgStringArray(mergeInc(req.IncompatibleSampleTypes, st.IncompatibleSampleTypes))
	err = a.Pool.QueryRow(ctx,
		`INSERT INTO samples (request_id, sample_type_id, requester_id, container_type, temperature_min_c, temperature_max_c,
		   incompatible_sample_types, origin_latitude, origin_longitude, origin_type, origin_node_id,
		   requested_at, delivery_deadline, status, sealed, sealed_at, sealed_by, serviceable, target_laboratory_id, current_holder_id)
		 VALUES ($1,$2,$3,$4,$5,$6,$7::uuid[],$8,$9,$10,$11::uuid,$12,$13,'sealed',true,$14,$3,$15,$16::uuid,$3) RETURNING sample_id`,
		requestID, req.SampleTypeID, requesterID, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC,
		incArr, req.Origin.Latitude, req.Origin.Longitude, originType, nullStr(originNodeID),
		requestedAt, deadline, time.Now().UTC(), res.Serviceable, nullStr(res.TargetLaboratoryID),
	).Scan(&sampleID)
	if err != nil {
		writeErr(w, err)
		return
	}

	activeAssignments := []string{}
	var journeyID string
	if res.Serviceable && res.Path != nil {
		j, aIDs, perr := a.createJourneyForPresealed(ctx, createJourneyInput{
			SampleID:        sampleID,
			SampleTypeID:    req.SampleTypeID,
			Origin:          req.Origin,
			OriginType:      originType,
			EntryNode:       res.CollectionPoint,
			Path:            res.Path,
			TargetLabID:     res.TargetLaboratoryID,
			Deadline:        deadline,
			Earliest:        earliest,
			RequiresCooled:  st.RequiresCooledRoute,
			BatchingAllowed: st.BatchingAllowed,
			HolderID:        u.UserID,
		})
		if perr == nil {
			journeyID = j
			activeAssignments = aIDs
		}
	}
	resp := createRequestResp{
		RequestID:            requestID,
		SampleID:             sampleID,
		Serviceability:       serviceabilityStr(res.Serviceable),
		ActiveAssignmentIDs:  activeAssignments,
		EarliestCollectionAt: fmtTimeT(earliest),
		LatestCollectionAt:   fmtTimeT(latest),
		JourneyID:            journeyID,
		AlreadySealed:        true,
		OriginType:           originType,
	}
	if res.TargetLaboratoryID != "" {
		resp.TargetLaboratoryID = res.TargetLaboratoryID
	}
	a.record(ctx, u.UserID, role, "ingest_presealed_sample", "sample", sampleID, true, map[string]interface{}{"holder": u.UserID})
	a.emit(ctx, "sample.ingested", "sample", sampleID, map[string]interface{}{"requestId": requestID})
	web.Data(w, http.StatusCreated, resp)
}

// -------- Journey creation (planning) --------

type createJourneyInput struct {
	SampleID        string
	SampleTypeID    string
	Origin          domain.Coordinate
	OriginType      string
	EntryNode       *routing.Node
	Path            *routing.Path
	TargetLabID     string
	Deadline        time.Time
	Earliest        time.Time
	RequiresCooled  bool
	BatchingAllowed bool
	HolderID        string
}

// createJourney builds a journey with collection + transport legs for a home/clinic request.
func (a *App) createJourney(ctx context.Context, in createJourneyInput) (string, []string, error) {
	// Determine route mode.
	mode := "direct"
	if len(in.Path.Edges) == 1 {
		mode = "direct"
	} else if len(in.Path.Edges) > 1 {
		mode = "multi_stop"
	}
	estimatedDelivery := in.Path.EarliestArrival(in.Earliest, 0)
	totalCost := in.Path.TotalCost

	var journeyID string
	err := a.Pool.QueryRow(ctx,
		`INSERT INTO journeys (route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, target_laboratory_id, valid)
		 VALUES ($1,'planned',$2,$3,$4,$5::uuid,true) RETURNING journey_id`,
		mode, estimatedDelivery, totalCost, 1, nullStr(in.TargetLabID),
	).Scan(&journeyID)
	if err != nil {
		return "", nil, err
	}

	// Link sample to journey.
	_, _ = a.Pool.Exec(ctx, `UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1`, in.SampleID, journeyID)

	// Stops: pickup at entry, then each intermediate node as handoff, delivery at lab.
	stops := buildStops(in.EntryNode, in.Path, in.Earliest)
	for _, st := range stops {
		_, _ = a.Pool.Exec(ctx,
			`INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
			 VALUES ($1,$2,$3,$4,$5,$6)`,
			journeyID, st.LocationID, st.StopType, st.Sequence, st.EstimatedAt, st.DwellMinutes)
	}

	// Create collection assignment (offered to a qualified collection professional).
	collAsgID := a.createAssignment(ctx, journeyID, in.SampleID, "collection", 0, in.EntryNode.LocationID, "", in.RequiresCooled)

	// Transport legs between consecutive path nodes.
	var assignmentIDs []string
	if collAsgID != "" {
		assignmentIDs = append(assignmentIDs, collAsgID)
	}
	nodes := in.Path.Nodes
	edges := in.Path.Edges
	for i, _ := range edges {
		seq := i + 1
		from := nodes[i].LocationID
		to := nodes[i+1].LocationID
		kind := "transport"
		if i == len(edges)-1 {
			// final leg ends at lab; add a laboratory assignment too (handled separately)
		}
		tAsg := a.createAssignment(ctx, journeyID, in.SampleID, kind, seq, from, to, in.RequiresCooled)
		if tAsg != "" {
			assignmentIDs = append(assignmentIDs, tAsg)
		}
	}
	// Node assignment for intermediate hubs.
	for i := 1; i < len(nodes)-1; i++ {
		a.createAssignment(ctx, journeyID, in.SampleID, "node", i, nodes[i].LocationID, "", in.RequiresCooled)
	}
	// Laboratory assignment at the final node.
	if len(nodes) > 0 {
		labNode := nodes[len(nodes)-1]
		a.createAssignment(ctx, journeyID, in.SampleID, "laboratory", len(edges)+1, labNode.LocationID, "", in.RequiresCooled)
	}

	// Reserve capacity on each traversed connection + destination nodes.
	a.reserveCapacity(ctx, journeyID, in.SampleID, in.Path, in.RequiresCooled)

	// Offer assignments to eligible workers (best-effort, one at a time).
	a.offerAssignments(ctx, journeyID)

	a.record(ctx, "", "system", "plan_journey", "journey", journeyID, true, map[string]interface{}{"mode": mode, "sampleId": in.SampleID})
	a.emit(ctx, "journey.planned", "journey", journeyID, map[string]interface{}{"sampleId": in.SampleID, "mode": mode})
	return journeyID, assignmentIDs, nil
}

// createJourneyForPresealed builds only transport legs from the entry node onward (no collection).
func (a *App) createJourneyForPresealed(ctx context.Context, in createJourneyInput) (string, []string, error) {
	mode := "direct"
	if len(in.Path.Edges) > 1 {
		mode = "multi_stop"
	}
	estimatedDelivery := in.Path.EarliestArrival(in.Earliest, 0)
	var journeyID string
	err := a.Pool.QueryRow(ctx,
		`INSERT INTO journeys (route_mode, status, estimated_delivery_at, total_cost_units, target_laboratory_id, valid)
		 VALUES ($1,'planned',$2,$3,$4::uuid,true) RETURNING journey_id`,
		mode, estimatedDelivery, in.Path.TotalCost, nullStr(in.TargetLabID),
	).Scan(&journeyID)
	if err != nil {
		return "", nil, err
	}
	_, _ = a.Pool.Exec(ctx, `UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1`, in.SampleID, journeyID)

	stops := buildStopsFromEntry(in.EntryNode, in.Path, in.Earliest)
	for _, st := range stops {
		_, _ = a.Pool.Exec(ctx,
			`INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
			 VALUES ($1,$2,$3,$4,$5,$6)`, journeyID, st.LocationID, st.StopType, st.Sequence, st.EstimatedAt, st.DwellMinutes)
	}

	nodes := in.Path.Nodes
	edges := in.Path.Edges
	var assignmentIDs []string
	for i, _ := range edges {
		seq := i + 1
		from := nodes[i].LocationID
		to := nodes[i+1].LocationID
		tAsg := a.createAssignment(ctx, journeyID, in.SampleID, "transport", seq, from, to, in.RequiresCooled)
		if tAsg != "" {
			assignmentIDs = append(assignmentIDs, tAsg)
		}
	}
	for i := 1; i < len(nodes)-1; i++ {
		a.createAssignment(ctx, journeyID, in.SampleID, "node", i, nodes[i].LocationID, "", in.RequiresCooled)
	}
	if len(nodes) > 0 {
		labNode := nodes[len(nodes)-1]
		a.createAssignment(ctx, journeyID, in.SampleID, "laboratory", len(edges)+1, labNode.LocationID, "", in.RequiresCooled)
	}
	a.reserveCapacity(ctx, journeyID, in.SampleID, in.Path, in.RequiresCooled)
	a.offerAssignments(ctx, journeyID)
	a.record(ctx, "", "system", "plan_journey", "journey", journeyID, true, map[string]interface{}{"presealed": true, "sampleId": in.SampleID})
	return journeyID, assignmentIDs, nil
}

type stopInfo struct {
	LocationID   string
	StopType     string
	Sequence     int
	EstimatedAt  time.Time
	DwellMinutes int
}

func buildStops(entry *routing.Node, path *routing.Path, earliest time.Time) []stopInfo {
	var stops []stopInfo
	t := earliest
	// pickup at entry collection point
	stops = append(stops, stopInfo{LocationID: entry.LocationID, StopType: "pickup", Sequence: 1, EstimatedAt: t, DwellMinutes: entry.HandlingMinutes})
	t = t.Add(time.Duration(entry.HandlingMinutes) * time.Minute)
	nodes := path.Nodes
	edges := path.Edges
	for i, e := range edges {
		t = t.Add(time.Duration(e.TravelMinutes) * time.Minute)
		node := nodes[i+1]
		stopType := "handoff"
		if i == len(edges)-1 {
			stopType = "delivery"
		}
		stops = append(stops, stopInfo{LocationID: node.LocationID, StopType: stopType, Sequence: len(stops) + 1, EstimatedAt: t, DwellMinutes: node.HandlingMinutes})
		t = t.Add(time.Duration(node.HandlingMinutes) * time.Minute)
	}
	return stops
}

func buildStopsFromEntry(entry *routing.Node, path *routing.Path, earliest time.Time) []stopInfo {
	var stops []stopInfo
	t := earliest
	// entry pickup is current node
	stops = append(stops, stopInfo{LocationID: entry.LocationID, StopType: "pickup", Sequence: 1, EstimatedAt: t, DwellMinutes: entry.HandlingMinutes})
	t = t.Add(time.Duration(entry.HandlingMinutes) * time.Minute)
	nodes := path.Nodes
	edges := path.Edges
	for i, e := range edges {
		t = t.Add(time.Duration(e.TravelMinutes) * time.Minute)
		node := nodes[i+1]
		stopType := "handoff"
		if i == len(edges)-1 {
			stopType = "delivery"
		}
		stops = append(stops, stopInfo{LocationID: node.LocationID, StopType: stopType, Sequence: len(stops) + 1, EstimatedAt: t, DwellMinutes: node.HandlingMinutes})
		t = t.Add(time.Duration(node.HandlingMinutes) * time.Minute)
	}
	return stops
}

func (a *App) createAssignment(ctx context.Context, journeyID, sampleID, kind string, seq int, fromLoc, toLoc string, requiresCooled bool) string {
	id := uuid.NewString()
	var fromI, toI interface{}
	if fromLoc != "" {
		fromI = fromLoc
	}
	if toLoc != "" {
		toI = toLoc
	}
	_, err := a.Pool.Exec(ctx,
		`INSERT INTO assignments (assignment_id, journey_id, sample_id, kind, sequence, from_location_id, to_location_id, status)
		 VALUES ($1,$2,$3,$4,$5,$6,$7,'offered')`,
		id, journeyID, sampleID, kind, seq, fromI, toI)
	if err != nil {
		return ""
	}
	return id
}

func (a *App) reserveCapacity(ctx context.Context, journeyID, sampleID string, path *routing.Path, requiresCooled bool) {
	for _, e := range path.Edges {
		_, _ = a.Pool.Exec(ctx,
			`INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, units, cooled)
			 VALUES ($1,$2,$3,1,$4)
			 ON CONFLICT DO NOTHING`,
			e.ConnectionID, journeyID, sampleID, requiresCooled)
		// increment reserved
		_, _ = a.Pool.Exec(ctx, `UPDATE capacities SET reserved_units = reserved_units + 1 WHERE resource_id=$1`, e.ConnectionID)
		if requiresCooled {
			_, _ = a.Pool.Exec(ctx, `UPDATE capacities SET cooled_reserved_units = cooled_reserved_units + 1 WHERE resource_id=$1`, e.ConnectionID)
		}
	}
	// destination lab node capacity
	if len(path.Nodes) > 0 {
		lab := path.Nodes[len(path.Nodes)-1].LocationID
		_, _ = a.Pool.Exec(ctx, `UPDATE capacities SET reserved_units = reserved_units + 1 WHERE resource_id=$1`, lab)
		if requiresCooled {
			_, _ = a.Pool.Exec(ctx, `UPDATE capacities SET cooled_reserved_units = cooled_reserved_units + 1 WHERE resource_id=$1`, lab)
		}
	}
}

func (a *App) releaseCapacity(ctx context.Context, journeyID string) {
	rows, _ := a.Pool.Query(ctx, `SELECT resource_id, cooled FROM capacity_reservations WHERE journey_id=$1`, journeyID)
	defer rows.Close()
	for rows.Next() {
		var resID string
		var cooled bool
		if rows.Scan(&resID, &cooled) != nil {
			continue
		}
		_, _ = a.Pool.Exec(ctx, `UPDATE capacities SET reserved_units = GREATEST(reserved_units - 1, 0) WHERE resource_id=$1`, resID)
		if cooled {
			_, _ = a.Pool.Exec(ctx, `UPDATE capacities SET cooled_reserved_units = GREATEST(cooled_reserved_units - 1, 0) WHERE resource_id=$1`, resID)
		}
	}
	_, _ = a.Pool.Exec(ctx, `DELETE FROM capacity_reservations WHERE journey_id=$1`, journeyID)
}

func mergeInc(a, b []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, x := range append(a, b...) {
		if x == "" {
			continue
		}
		if !seen[x] {
			seen[x] = true
			out = append(out, x)
		}
	}
	return out
}

