// Minimal typed API client for the pinned contract.
export interface DataEnvelope<T> { data: T }
export interface ErrorEnvelope { error: string; code: string }

const BASE = '/api'

function token(): string | null {
  return localStorage.getItem('sessionToken')
}

export async function apiCall<T>(path: string, body?: unknown): Promise<T> {
  const headers: Record<string, string> = { 'Content-Type': 'application/json' }
  const tok = token()
  if (tok) headers['Authorization'] = `Bearer ${tok}`
  const res = await fetch(`${BASE}${path}`, {
    method: 'POST',
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined
  })
  const text = await res.text()
  let json: any = null
  if (text) {
    try { json = JSON.parse(text) } catch { json = { error: text, code: 'invalid_json' } }
  }
  if (!res.ok) {
    const err = json as ErrorEnvelope
    const e: any = new Error(err?.error || `HTTP ${res.status}`)
    e.code = err?.code
    e.status = res.status
    throw e
  }
  return (json as DataEnvelope<T>).data
}

export async function apiGet<T>(path: string): Promise<T> {
  const headers: Record<string, string> = {}
  const tok = token()
  if (tok) headers['Authorization'] = `Bearer ${tok}`
  const res = await fetch(`${BASE}${path}`, { headers })
  const text = await res.text()
  let json: any = null
  if (text) { try { json = JSON.parse(text) } catch { json = { error: text, code: 'invalid_json' } } }
  if (!res.ok) {
    const err = json as ErrorEnvelope
    const e: any = new Error(err?.error || `HTTP ${res.status}`)
    e.code = err?.code; e.status = res.status
    throw e
  }
  return (json as DataEnvelope<T>).data
}

export interface AuthResp { sessionToken: string; userId: string; roles: string[]; activeRole: string }
export interface Bootstrap {
  user: { userId: string; username: string; fullName: string; roles: string[]; activeRole: string; roleSelectionRequired: boolean }
  serverTime: string
  requesterSamples?: any[]
  operations?: any
}

export const api = {
  authenticate: (u: string, p: string) =>
    fetch(`${BASE}/authenticate-user`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: u, password: p }) })
      .then(async r => { const j = await r.json(); if (!r.ok) throw j; return j.data as AuthResp }),
  bootstrap: () => apiGet<Bootstrap>('/ui/bootstrap'),
  selectRole: (role: string) => apiCall<{ activeRole: string; roles: string[] }>('/select-active-role', { role }),
  listRoleWork: (role?: string, status?: string) => apiCall('/list-role-work', { role, status }),
  readOperationsState: (filters?: any) => apiCall('/read-operations-state', { filters: filters || {} }),
  readSampleState: (sampleId: string) => apiGet(`/read-sample-state/${sampleId}`),
  readSampleLifecycle: (sampleId: string) => apiCall('/read-sample-lifecycle', { sampleId }),
  readJourneyPlan: (journeyId: string) => apiCall('/read-journey-plan', { journeyId }),
  searchAudit: (q: any) => apiCall('/search-audit-trail', q),
  checkServiceability: (b: any) => apiCall('/check-serviceability', b),
  createRequest: (b: any) => apiCall('/create-collection-request', b),
  ingestPresealed: (b: any) => apiCall('/ingest-presealed-sample', b),
  createLocation: (b: any) => apiCall('/create-location', b),
  updateLocation: (b: any) => apiCall('/update-location', b),
  setLocationStatus: (b: any) => apiCall('/set-location-status', b),
  createConnection: (b: any) => apiCall('/create-connection', b),
  setConnectionStatus: (b: any) => apiCall('/set-connection-status', b),
  createSampleType: (b: any) => apiCall('/create-sample-type', b),
  updateSampleType: (b: any) => apiCall('/update-sample-type', b),
  configureCapacity: (b: any) => apiCall('/configure-capacity', b),
  configureLabAcceptance: (b: any) => apiCall('/configure-laboratory-acceptance', b),
  setWorkerAvailability: (b: any) => apiCall('/set-worker-availability', b),
  createUser: (b: any) => apiCall('/create-user', b),
  updateUserAccess: (b: any) => apiCall('/update-user-access', b),
  readUser: (userId: string) => apiGet(`/read-user/${userId}`),
  acceptAssignment: (b: any) => apiCall('/accept-assignment', b),
  declineAssignment: (b: any) => apiCall('/decline-assignment', b),
  updateProgress: (b: any) => apiCall('/update-assignment-progress', b),
  collectAndSeal: (b: any) => apiCall('/collect-and-seal-sample', b),
  recordWorkerLocation: (b: any) => apiCall('/record-worker-location', b),
  recordCheckpoint: (b: any) => apiCall('/record-handling-checkpoint', b),
  initiateHandoff: (b: any) => apiCall('/initiate-handoff', b),
  confirmHandoff: (b: any) => apiCall('/confirm-handoff', b),
  confirmReceipt: (b: any) => apiCall('/confirm-laboratory-receipt', b),
  recordLabException: (b: any) => apiCall('/record-laboratory-exception', b),
  reportDisruption: (b: any) => apiCall('/report-disruption', b),
  reroute: (b: any) => apiCall('/reroute-journey', b),
  cancelJourney: (b: any) => apiCall('/cancel-journey', b),
  splitJourney: (b: any) => apiCall('/split-journey', b),
  mergeJourneys: (b: any) => apiCall('/merge-journeys', b),
  editActivePlan: (b: any) => apiCall('/edit-active-plan', b),
  readServiceabilitySnapshot: () => apiCall('/read-serviceability-snapshot', {})
}

export function logout() {
  localStorage.removeItem('sessionToken')
  localStorage.removeItem('user')
  location.href = '/'
}

