:root {
  --bg: #f5f4ef;
  --panel: #ffffff;
  --ink: #2b2b2b;
  --muted: #6b6b6b;
  --accent: #1f6feb;
  --danger: #c0392b;
  --ok: #1e8e3e;
  --warn: #b8860b;
  --border: #d8d4cc;
}
* { box-sizing: border-box; }
html, body, #app { height: 100%; margin: 0; }
body { font-family: 'Noto Sans', system-ui, sans-serif; background: var(--bg); color: var(--ink); }
a { color: var(--accent); text-decoration: none; }
button { font: inherit; cursor: pointer; border: 1px solid var(--border); background: var(--panel); padding: 6px 12px; border-radius: 6px; }
button.primary { background: var(--accent); color: white; border-color: var(--accent); }
button.danger { background: var(--danger); color: white; border-color: var(--danger); }
button:disabled { opacity: .5; cursor: default; }
input, select, textarea { font: inherit; padding: 6px 8px; border: 1px solid var(--border); border-radius: 6px; background: var(--panel); }
.panel { background: var(--panel); border: 1px solid var(--border); border-radius: 10px; padding: 16px; margin-bottom: 16px; }
.row { display: flex; gap: 12px; flex-wrap: wrap; align-items: center; }
.col { display: flex; flex-direction: column; gap: 8px; }
.muted { color: var(--muted); }
.tag { display: inline-block; padding: 2px 8px; border-radius: 999px; font-size: 12px; background: #eef; }
.tag.stale { background: #fde; color: var(--danger); }
.tag.exception { background: #fdd; color: var(--danger); }
.tag.ok { background: #e6f7e6; color: var(--ok); }
.layout { display: grid; grid-template-columns: 220px 1fr; min-height: 100vh; }
.sidebar { background: #23272e; color: #eee; padding: 16px; }
.sidebar a { color: #cdd; display: block; padding: 8px 10px; border-radius: 6px; }
.sidebar a.router-link-active { background: #333; }
.sidebar h2 { font-size: 16px; margin: 0 0 12px; }
.main { padding: 20px; overflow: auto; }
.topbar { display: flex; justify-content: space-between; align-items: center; padding: 12px 16px; background: var(--panel); border-bottom: 1px solid var(--border); }
table { width: 100%; border-collapse: collapse; }
th, td { text-align: left; padding: 8px; border-bottom: 1px solid var(--border); font-size: 14px; }
th { background: #f0eee8; }
.error { color: var(--danger); font-size: 14px; }
.timeline { list-style: none; padding: 0; margin: 0; }
.timeline li { padding: 6px 0; border-bottom: 1px dashed var(--border); font-size: 13px; }
.timeline .when { color: var(--muted); font-size: 12px; }
#map { width: 100%; height: 60vh; border-radius: 10px; }
.map-wrap { position: relative; }
.legend { position: absolute; bottom: 12px; left: 12px; background: rgba(255,255,255,.9); padding: 8px; border-radius: 6px; font-size: 12px; }

