.tag.stale { background: #fde; color: var(--danger); }
.tag.exception { background: #fdd; color: var(--danger); }
.tag.ok { background: #e6f7e6; color: var(--ok); }
.layout { display: grid; grid-template-columns: 220px 1fr; min-height: 100vh; }
