.sidebar h2 { font-size: 16px; margin: 0 0 12px; }
.main { padding: 20px; overflow: auto; }
.topbar { display: flex; justify-content: space-between; align-items: center; padding: 12px 16px; background: var(--panel); border-bottom: 1px solid var(--border); }
table { width: 100%; border-collapse: collapse; }
th, td { text-align: left; padding: 8px; border-bottom: 1px solid var(--border); font-size: 14px; }
th { background: #f0eee8; }
.error { color: var(--danger); font-size: 14px; }
.timeline { list-style: none; padding: 0; margin: 0; }
.timeline li { padding: 6px 0; border-bottom: 1px dashed var(--border); font-size: 13px; }
.timeline .when { color: var(--muted); font-size: 12px; }
#map { width: 100%; height: 60vh; border-radius: 10px; }
.map-wrap { position: relative; }
.legend { position: absolute; bottom: 12px; left: 12px; background: rgba(255,255,255,.9); padding: 8px; border-radius: 6px; font-size: 12px; }

