import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../api'

const router = useRouter()
const username = ref('admin')
const password = ref('')
const error = ref('')

async function submit() {
  error.value = ''
  try {
    const res = await api.authenticate(username.value, password.value)
    localStorage.setItem('sessionToken', res.sessionToken)
    localStorage.setItem('user', JSON.stringify({ userId: res.userId, roles: res.roles, activeRole: res.activeRole }))
    router.push('/dashboard')
  } catch (e: any) {
    error.value = e.error || 'Invalid credentials'
  }
}
</script>

<template>
  <div style="display:flex; align-items:center; justify-content:center; min-height:100vh;">
    <form class="panel" style="width:320px;" @submit.prevent="submit">
      <h2>Lab Sample Logistics</h2>
      <p class="muted">Sign in to continue</p>
      <div class="col">
        <label>Username
          <input v-model="username" autocomplete="username" aria-label="username" />
        </label>
        <label>Password
          <input v-model="password" type="password" autocomplete="current-password" aria-label="password" />
        </label>
        <button class="primary" type="submit">Sign in</button>
      </div>
      <p class="error" v-if="error" role="alert">{{ error }}</p>
    </form>
  </div>
</template>", "path": "/workspace/frontend/src/views/Login.vue"}

