import maplibregl from 'maplibre-gl'
import { Protocol } from 'pmtiles'
import 'maplibre-gl/dist/maplibre-gl.css'

let protocolRegistered = false

export function ensureProtocol() {
  if (protocolRegistered) return
  const proto = new Protocol()
  maplibregl.addProtocol('pmtiles', proto.tile)
  protocolRegistered = true
}

export function createMap(container: HTMLElement): maplibregl.Map {
  ensureProtocol()
  const map = new maplibregl.Map({
    container,
    style: '/map-assets/style.json',
    center: [77.5946, 12.9716],
    zoom: 10,
    hash: false
  })
  return map
}

export function addMarker(map: maplibregl.Map, lng: number, lat: number, color: string, popup?: string): maplibregl.Marker {
  const el = document.createElement('div')
  el.style.width = '12px'
  el.style.height = '12px'
  el.style.borderRadius = '50%'
  el.style.background = color
  el.style.border = '2px solid #fff'
  el.style.boxShadow = '0 0 2px #000'
  const m = new maplibregl.Marker(el).setLngLat([lng, lat]).addTo(map)
  if (popup) m.setPopup(new maplibregl.Popup().setHTML(popup))
  return m
}

