{"command": "create", "file_text": "<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount } from 'vue'
import { api } from '../api'
import { createMap, addMarker } from '../map'
import type maplibregl from 'maplibre-gl'

const container = ref<HTMLElement | null>(null)
const status = ref('loading')
let map: maplibregl.Map | null = null
const markers: any[] = []

onMounted(async () => {
  try {
    const ops = await api.readOperationsState({})
    map = createMap(container.value!)
    map.on('load', () => {
      // locations
      for (const loc of ops.locations || []) {
        const c = loc.coordinate
        const color = loc.functions.laboratory ? '#c0392b' : loc.functions.hub ? '#8e44ad' : loc.functions.collection_point ? '#1e8e3e' : '#1f6feb'
        addMarker(map!, c.longitude, c.latitude, color, `<b>${loc.name}</b><br>${loc.active ? 'active' : 'inactive'}`)
      }
      // worker locations
      for (const w of ops.workers || []) {
        if (w.latestLocation) {
          addMarker(map!, w.latestLocation.longitude, w.latestLocation.latitude, '#f39c12', `<b>${w.fullName || w.workerId}</b><br>${w.status}`)
        }
      }
      // sample locations
      for (const s of ops.samples || []) {
        if (s.latestLocation) {
          addMarker(map!, s.latestLocation.longitude, s.latestLocation.latitude, '#e67e22', `Sample ${s.sampleId.slice(0,8)}<br>${s.status}`)
        }
      }
      status.value = 'ready'
    })
  } catch (e: any) {
    status.value = 'error: ' + e.message
  }
})

onBeforeUnmount(() => { map?.remove() })
</script>

<template>
  <div>
    <h2>Live Map</h2>
    <p class="muted">Local PMTiles basemap (Bangalore). Markers: green=collection point, red=laboratory, purple=hub, orange=worker, sample=orange.</p>
    <div class="map-wrap">
      <div ref="container" id="map" aria-label="live map"></div>
      <div class="legend">
        <div><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#1e8e3e"></span> Collection point</div>
        <div><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#c0392b"></span> Laboratory</div>
        <div><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#f39c12"></span> Worker</div>
      </div>
    </div>
    <p class="muted">status: {{ status }}</p>
  </div>
</template>", "path": "/workspace/frontend/src/views/MapView.vue"}

