package web

import (
	"context"
	"net/http"
	"strings"

	"github.com/jackc/pgx/v5/pgxpool"

	"lablogistics/internal/auth"
)

// AuthMiddleware validates the bearer [REDACTED] (unless the path is public) and
// loads the session user + active role into the request context.
type AuthMiddleware struct {
	Pool        *pgxpool.Pool
	PublicPaths map[string]bool
}

func NewAuthMiddleware(pool *pgxpool.Pool) *AuthMiddleware {
	return &AuthMiddleware{
		Pool: pool,
		PublicPaths: map[string]bool{
			"/ready":                 true,
			"/api/authenticate-user": true,
			"/api/ui/bootstrap":      false, // requires auth
		},
	}
}

func (m *AuthMiddleware) Wrap(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		if path == "/ready" || path == "/api/authenticate-user" {
			next.ServeHTTP(w, r)
			return
		}
		token := auth.ExtractBearer(r)
		if token == "" {
			// allow websocket subprotocol token via header
			token = wsTokenFromHeader(r)
		}
		if token == "" {
			Error(w, http.StatusUnauthorized, "unauthorized", "missing token")
			return
		}
		var userID, username string
		var roles []string
		var activeRole *string
		err := m.Pool.QueryRow(r.Context(),
			`SELECT s.user_id, u.username, u.roles, s.active_role
			 FROM sessions s JOIN users u ON u.user_id=s.user_id
			 WHERE s.session_token=$1 AND s.expires_at > now() AND u.active=true`, token).
			Scan(&userID, &username, &roles, &activeRole)
		if err != nil {
			Error(w, http.StatusUnauthorized, "unauthorized", "invalid session")
			return
		}
		u := &auth.SessionUser{UserID: userID, Username: username, Roles: roles}
		ctx := auth.WithUser(r.Context(), u)
		if activeRole != nil && *activeRole != "" {
			ctx = auth.WithRole(ctx, *activeRole)
		}
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func wsTokenFromHeader(r *http.Request) string {
	proto := r.Header.Get("Sec-WebSocket-Protocol")
	parts := strings.Split(proto, ",")
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if strings.HasPrefix(p, "bearer.") {
			return strings.TrimPrefix(p, "bearer.")
		}
	}
	return ""
}

// CORS + JSON defaults middleware.
func DefaultMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Sec-WebSocket-Protocol")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
		if r.Method == http.MethodOptions {
			w.WriteHeader(http.StatusNoContent)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// CloseCtx returns a context that is cancelled when the server shuts down.
type key int

var reqKey key

func WithCtx(ctx context.Context) context.Context {
	return context.WithValue(ctx, reqKey, true)
}

