		return
	}
	var req checkpointReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.SampleID == "" || req.AssignmentID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	recordedAt, err := parseTime(req.RecordedAt)
	if err != nil || recordedAt.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid recordedAt"))
		return
	}
	ctx := r.Context()
	// must be current holder
	var holder string
	var status string
	err = a.Pool.QueryRow(ctx, `SELECT COALESCE(current_holder_id::text,''), status FROM samples WHERE sample_id=$1`, req.SampleID).Scan(&holder, &status)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "sample not found"))
		return
	}
	if holder != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "forbidden", "not the current holder"))
		return
	}
	if status == "received" || status == "cancelled" || status == "expired" {
		writeErr(w, apiErr(http.StatusConflict, "terminal_sample", "sample in terminal state"))
		return
	}
	st, _ := a.loadSampleType(ctx, sampleIDFromAssignment(ctx, a, req.AssignmentID))
	compliant := true
	if req.ObservedTemperatureC < st.TemperatureMinC || req.ObservedTemperatureC > st.TemperatureMaxC {
		compliant = false
	}
	checkpointID := uuid.NewString()
	_, err = a.Pool.Exec(ctx,
		`INSERT INTO handling_checkpoints (checkpoint_id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_by, recorded_at)
		 VALUES ($1,$2,$3,$4::uuid,$5,$6,$7,$8,$9)`,
