	if err != nil {
		writeErr(w, err)
		return
	}
	if !compliant {
		exc, _ := json.Marshal(map[string]interface{}{"reason": "handling_noncompliant", "observedTemperatureC": req.ObservedTemperatureC})
		_, _ = a.Pool.Exec(ctx, `UPDATE samples SET status='exception', exception=$2, updated_at=now() WHERE sample_id=$1`,
			req.SampleID, string(exc))
		a.record(ctx, u.UserID, role, "handling_exception", "sample", req.SampleID, false, map[string]interface{}{"compliant": false})
		a.emit(ctx, "sample.exception", "sample", req.SampleID, map[string]interface{}{"reason": "handling_noncompliant"})
	}
	sampleStatus := status
	if !compliant {
		sampleStatus = "exception"
	}
	a.record(ctx, u.UserID, role, "record_handling_checkpoint", "sample", req.SampleID, true, map[string]interface{}{"compliant": compliant})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"checkpointId": checkpointID, "sampleId": req.SampleID,
		"compliant": compliant, "sampleStatus": sampleStatus,
	})
}

