	exc, _ := json.Marshal(map[string]interface{}{"reason": req.Reason, "laboratoryId": req.LaboratoryID})
	_, _ = a.Pool.Exec(ctx, `UPDATE samples SET status='exception', exception=$2, updated_at=now() WHERE sample_id=$1`,
		req.SampleID, string(exc))
	a.record(ctx, u.UserID, role, "record_laboratory_exception", "sample", req.SampleID, true, map[string]interface{}{"reason": req.Reason})
	a.emit(ctx, "sample.exception", "sample", req.SampleID, map[string]interface{}{"reason": req.Reason, "laboratoryId": req.LaboratoryID})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"exceptionId": exceptionID, "sampleId": req.SampleID, "status": "exception", "reason": req.Reason,
	})
}

