	if !deadline.IsZero() && receivedAt.After(deadline) {
		// past deadline: still record but mark exception
		_, _ = a.Pool.Exec(ctx, `UPDATE samples SET status='exception', exception=$2, received_laboratory_id=$3, updated_at=now() WHERE sample_id=$1`,
			req.SampleID, `{"reason":"delivery_deadline_exceeded"}`, req.LaboratoryID)
		writeErr(w, apiErr(http.StatusConflict, "delivery_deadline_exceeded", "received after deadline"))
		return
	}
	_, _ = a.Pool.Exec(ctx, `UPDATE samples SET status='received', received_laboratory_id=$2, updated_at=now() WHERE sample_id=$1`, req.SampleID, req.LaboratoryID)
	// complete laboratory assignment for this sample
	_, _ = a.Pool.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=$2 WHERE sample_id=$1 AND kind='laboratory'`, req.SampleID, receivedAt)
	// complete delivery stop
	_, _ = a.Pool.Exec(ctx, `UPDATE journey_stops SET completed_at=$2 WHERE journey_id=(SELECT active_journey_id FROM samples WHERE sample_id=$1) AND stop_type='delivery' AND completed_at IS NULL`, req.SampleID, receivedAt)
	// mark journey completed
	_, _ = a.Pool.Exec(ctx, `UPDATE journeys SET status='completed', updated_at=now() WHERE journey_id=(SELECT active_journey_id FROM samples WHERE sample_id=$1) AND status NOT IN ('completed','cancelled')`, req.SampleID)
	a.releaseCapacity(ctx, journeyIDOfSample(ctx, a, req.SampleID))
	a.record(ctx, u.UserID, role, "confirm_laboratory_receipt", "sample", req.SampleID, true, map[string]interface{}{"laboratoryId": req.LaboratoryID})
	a.emit(ctx, "sample.received", "sample", req.SampleID, map[string]interface{}{"laboratoryId": req.LaboratoryID})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"sampleId": req.SampleID, "laboratoryId": req.LaboratoryID,
		"status": "received", "receivedAt": fmtTimeT(receivedAt),
	})
}

func journeyIDOfSample(ctx context.Context, a *App, sampleID string) string {
	var j string
	_ = a.Pool.QueryRow(ctx, `SELECT COALESCE(active_journey_id::text,'') FROM samples WHERE sample_id=$1`, sampleID).Scan(&j)
	return j
}

// ---------- Record handling checkpoint ----------

type checkpointReq struct {
	SampleID             string  `json:"sampleId"`
	AssignmentID         string  `json:"assignmentId"`
	LocationID           string  `json:"locationId"`
	ContainerType        string  `json:"containerType"`
	ObservedTemperatureC float64 `json:"observedTemperatureC"`
	RecordedAt           string  `json:"recordedAt"`
	IdempotencyKey       string  `json:"idempotencyKey"`
}

func (a *App) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req checkpointReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.SampleID == "" || req.AssignmentID == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	recordedAt, err := parseTime(req.RecordedAt)
	if err != nil || recordedAt.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid recordedAt"))
		return
	}
	ctx := r.Context()
	// must be current holder
	var holder string
	var status string
	err = a.Pool.QueryRow(ctx, `SELECT COALESCE(current_holder_id::text,''), status FROM samples WHERE sample_id=$1`, req.SampleID).Scan(&holder, &status)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "sample not found"))
		return
	}
	if holder != u.UserID {
		writeErr(w, apiErr(http.StatusForbidden, "forbidden", "not the current holder"))
		return
	}
	if status == "received" || status == "cancelled" || status == "expired" {
		writeErr(w, apiErr(http.StatusConflict, "terminal_sample", "sample in terminal state"))
		return
	}
	st, _ := a.loadSampleType(ctx, sampleTypeIDForAssignment(ctx, a, req.AssignmentID))
	compliant := true
	if req.ObservedTemperatureC < st.TemperatureMinC || req.ObservedTemperatureC > st.TemperatureMaxC {
		compliant = false
	}
	checkpointID := uuid.NewString()
	_, err = a.Pool.Exec(ctx,
		`INSERT INTO handling_checkpoints (checkpoint_id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_by, recorded_at)
		 VALUES ($1,$2,$3,$4::uuid,$5,$6,$7,$8,$9)`,
		checkpointID, req.SampleID, req.AssignmentID, nullStr(req.LocationID), req.ContainerType, req.ObservedTemperatureC, compliant, u.UserID, recordedAt)
	if err != nil {
		writeErr(w, err)
		return
	}
	if !compliant {
		exc, _ := json.Marshal(map[string]interface{}{"reason": "handling_noncompliant", "observedTemperatureC": req.ObservedTemperatureC})
		_, _ = a.Pool.Exec(ctx, `UPDATE samples SET status='exception', exception=$2, updated_at=now() WHERE sample_id=$1`,
			req.SampleID, string(exc))
		a.record(ctx, u.UserID, role, "handling_exception", "sample", req.SampleID, false, map[string]interface{}{"compliant": false})
		a.emit(ctx, "sample.exception", "sample", req.SampleID, map[string]interface{}{"reason": "handling_noncompliant"})
	}
	sampleStatus := status
	if !compliant {
		sampleStatus = "exception"
	}
	a.record(ctx, u.UserID, role, "record_handling_checkpoint", "sample", req.SampleID, true, map[string]interface{}{"compliant": compliant})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"checkpointId": checkpointID, "sampleId": req.SampleID,
		"compliant": compliant, "sampleStatus": sampleStatus,
	})
}

func formatFloat(f float64) string {
	b, _ := json.Marshal(f)
	return string(b)
}

// ---------- Record laboratory exception ----------

type labExceptionReq struct {
	SampleID       string `json:"sampleId"`
	LaboratoryID   string `json:"laboratoryId"`
	Reason         string `json:"reason"`
	ObservedAt     string `json:"observedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (a *App) RecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	u, role, err := a.requireRole(r.Context(), auth.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req labExceptionReq
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.SampleID == "" || req.LaboratoryID == "" || req.Reason == "" || req.IdempotencyKey == "" {
		writeErr(w, apiErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey required"))
		return
	}
	observedAt, err := parseTime(req.ObservedAt)
	if err != nil || observedAt.IsZero() {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_time", "invalid observedAt"))
		return
	}
	ctx := r.Context()
	var assigned *string
	_ = a.Pool.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE user_id=$1`, u.UserID).Scan(&assigned)
	if assigned == nil || *assigned != req.LaboratoryID {
		writeErr(w, apiErr(http.StatusForbidden, "wrong_laboratory_operator", "not your laboratory"))
		return
	}
	var status string
	err = a.Pool.QueryRow(ctx, `SELECT status FROM samples WHERE sample_id=$1`, req.SampleID).Scan(&status)
	if err != nil {
		writeErr(w, apiErr(http.StatusNotFound, "not_found", "sample not found"))
		return
	}
	exceptionID := uuid.NewString()
	exc, _ := json.Marshal(map[string]interface{}{"reason": req.Reason, "laboratoryId": req.LaboratoryID})
	_, _ = a.Pool.Exec(ctx, `UPDATE samples SET status='exception', exception=$2, updated_at=now() WHERE sample_id=$1`,
		req.SampleID, string(exc))
	a.record(ctx, u.UserID, role, "record_laboratory_exception", "sample", req.SampleID, true, map[string]interface{}{"reason": req.Reason})
	a.emit(ctx, "sample.exception", "sample", req.SampleID, map[string]interface{}{"reason": req.Reason, "laboratoryId": req.LaboratoryID})
	web.Data(w, http.StatusCreated, map[string]interface{}{
		"exceptionId": exceptionID, "sampleId": req.SampleID, "status": "exception", "reason": req.Reason,
	})
}

