package api

import (
	"context"
	"net/http"
	"time"

	"lablogistics/internal/audit"
	"lablogistics/internal/auth"
	"lablogistics/internal/domain"
	"lablogistics/internal/web"
)

// ---------- List role work ----------

func (a *App) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	u, _, err := a.requireAnyRole(r.Context(), auth.AllRoles)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	_ = web.DecodeJSON(r, &req)
	// Use the selected active role if not provided.
	role := req.Role
	if role == "" {
		role = auth.RoleFromContext(r.Context())
	}
	if role == "" {
		writeErr(w, apiErr(http.StatusConflict, "role_not_selected", "role not selected"))
		return
	}
	if !auth.IsValidRole(role) {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_role", "invalid role"))
		return
	}
	// ensure the user holds the role
	held := false
	for _, ro := range u.Roles {
		if ro == role {
			held = true
		}
	}
	if !held {
		writeErr(w, apiErr(http.StatusForbidden, "role_not_held", "role not held"))
		return
	}
	ctx := r.Context()
	work := domain.RoleWork{Pending: []map[string]interface{}{}, InProgress: []map[string]interface{}{}, Completed: []map[string]interface{}{}}
	switch role {
	case auth.RoleRequester:
		work = a.requesterRoleWork(ctx, u.UserID)
	case auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleNodeHandler, auth.RoleLaboratoryTeam:
		work = a.workerRoleWork(ctx, u.UserID, role)
	case auth.RoleDispatcher, auth.RoleAdministrator:
		work = a.dispatcherRoleWork(ctx)
	}
	web.Data(w, http.StatusOK, work)
}

func (a *App) requesterRoleWork(ctx context.Context, userID string) domain.RoleWork {
	w := domain.RoleWork{Pending: []map[string]interface{}{}, InProgress: []map[string]interface{}{}, Completed: []map[string]interface{}{}}
	rows, _ := a.Pool.Query(ctx,
		`SELECT sample_id, request_id, status, serviceable, requested_at, delivery_deadline,
		        active_journey_id::text, target_laboratory_id::text, location_recorded_at
		 FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, userID)
	defer rows.Close()
	for rows.Next() {
		var sampleID, requestID, status string
		var serviceable bool
		var requestedAt, deadline time.Time
		var journey, lab *string
		var locAt *time.Time
		if rows.Scan(&sampleID, &requestID, &status, &serviceable, &requestedAt, &deadline, &journey, &lab, &locAt) != nil {
			continue
		}
		hist, _ := a.Audit.Timeline(ctx, "sample", sampleID, 50)
		if hist == nil {
			hist = []domain.TimelineEntry{}
		}
		item := map[string]interface{}{
			"kind": "sample", "sampleId": sampleID, "requestId": requestID, "status": status,
			"serviceability": serviceabilityStr(serviceable), "requestedAt": fmtTimeT(requestedAt),
			"deliveryDeadline": fmtTimeT(deadline), "history": hist, "locationStale": stale(locAt, a.Cfg.StaleMinutes),
		}
		if journey != nil {
			item["activeJourneyId"] = *journey
		}
		if lab != nil {
			item["laboratoryId"] = *lab
		}
		if locAt != nil {
			item["locationRecordedAt"] = fmtTime(locAt)
		}
		bucket := &w.Completed
		if status == "requested" || status == "collected" || status == "in_transit" || status == "sealed" {
			bucket = &w.InProgress
		}
		*bucket = append(*bucket, item)
	}
	return w
}

func (a *App) workerRoleWork(ctx context.Context, userID, role string) domain.RoleWork {
	w := domain.RoleWork{Pending: []map[string]interface{}{}, InProgress: []map[string]interface{}{}, Completed: []map[string]interface{}{}}
	rows, _ := a.Pool.Query(ctx,
		`SELECT a.assignment_id, a.kind, a.status, a.sample_id, a.journey_id, a.from_location_id::text,
		        a.to_location_id::text, a.sequence, a.offer_expires_at, a.node_id::text, a.laboratory_id::text
		 FROM assignments a
		 JOIN samples s ON s.sample_id=a.sample_id
		 WHERE a.worker_id=$1 OR a.offered_to_worker_id=$1
		 ORDER BY a.created_at DESC`, userID)
	defer rows.Close()
	for rows.Next() {
		var asgID, kind, status, sampleID string
		var journeyID, from, to, nodeID, labID *string
		var seq int
		var offerExp *time.Time
		if rows.Scan(&asgID, &kind, &status, &sampleID, &journeyID, &from, &to, &seq, &offerExp, &nodeID, &labID) != nil {
			continue
		}
		hist, _ := a.Audit.Timeline(ctx, "assignment", asgID, 50)
		if hist == nil {
			hist = []domain.TimelineEntry{}
		}
		item := map[string]interface{}{
			"kind": kind, "assignmentId": asgID, "sampleId": sampleID, "status": status, "history": hist,
		}
		if journeyID != nil {
			item["journeyId"] = *journeyID
		}
		if from != nil {
			item["fromLocationId"] = *from
		}
		if to != nil {
			item["toLocationId"] = *to
		}
		item["sequence"] = seq
		if offerExp != nil {
			item["offerExpiresAt"] = fmtTime(offerExp)
		}
		if nodeID != nil {
			item["nodeId"] = *nodeID
		}
		if labID != nil {
			item["laboratoryId"] = *labID
		}
		bucket := &w.Completed
		if status == "offered" {
			bucket = &w.Pending
		} else if status == "accepted" || status == "active" {
			bucket = &w.InProgress
		}
		*bucket = append(*bucket, item)
	}
	return w
}

func (a *App) dispatcherRoleWork(ctx context.Context) domain.RoleWork {
	w := domain.RoleWork{Pending: []map[string]interface{}{}, InProgress: []map[string]interface{}{}, Completed: []map[string]interface{}{}}
	rows, _ := a.Pool.Query(ctx,
		`SELECT j.journey_id, j.status, j.route_mode, j.plan_version, j.estimated_delivery_at,
		        (SELECT count(*) FROM assignments WHERE journey_id=j.journey_id)
		 FROM journeys j ORDER BY j.created_at DESC LIMIT 500`)
	defer rows.Close()
	for rows.Next() {
		var jID, status, mode string
		var pv int
		var est time.Time
		var cnt int
		if rows.Scan(&jID, &status, &mode, &pv, &est, &cnt) != nil {
			continue
		}
		sampleIDs, _ := a.journeySampleIDs(ctx, jID)
		hist, _ := a.Audit.Timeline(ctx, "journey", jID, 30)
		if hist == nil {
			hist = []domain.TimelineEntry{}
		}
		item := map[string]interface{}{
			"kind": "journey", "journeyId": jID, "status": status, "routeMode": mode,
			"planVersion": pv, "estimatedDeliveryAt": fmtTimeT(est), "assignmentCount": cnt,
			"sampleIds": sampleIDs, "history": hist,
		}
		bucket := &w.Completed
		if status == "planned" {
			bucket = &w.Pending
		} else if status == "active" {
			bucket = &w.InProgress
		}
		*bucket = append(*bucket, item)
	}
	return w
}

func (a *App) journeySampleIDs(ctx context.Context, journeyID string) ([]string, error) {
	rows, err := a.Pool.Query(ctx, `SELECT sample_id::text FROM samples WHERE active_journey_id=$1`, journeyID)
	if err != nil {
		return []string{}, err
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var id string
		rows.Scan(&id)
		out = append(out, id)
	}
	if out == nil {
		out = []string{}
	}
	return out, nil
}

// ---------- Read serviceability snapshot ----------

func (a *App) ReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	_, _, err := a.requireRole(r.Context(), auth.RoleRequester, auth.RoleDispatcher, auth.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	snap := a.Svc.Current()
	out := map[string]interface{}{
		"version":                    snap.Version,
		"status":                     "complete",
		"computedAt":                 fmtTimeT(snap.ComputedAt),
		"networkRevision":            snap.NetworkRevision,
		"regions":                    snap.Regions,
		"activeCollectionPointCount": snap.ActiveCollectionPointCount,
	}
	if out["regions"] == nil {
		out["regions"] = []domain.ServiceabilityRegion{}
	}
	web.Data(w, http.StatusOK, out)
}

// ---------- Search audit trail ----------

func (a *App) SearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	_, _, err := a.requireRole(r.Context(), auth.RoleDispatcher, auth.RoleAdministrator, auth.RoleLaboratoryTeam, auth.RoleNodeHandler, auth.RoleCollectionProfessional, auth.RoleDeliveryPartner, auth.RoleRequester)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := web.DecodeJSON(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	limit := req.Limit
	if limit <= 0 {
		limit = 500
	}
	if limit > 5000 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_limit", "limit max 5000"))
		return
	}
	if req.Offset < 0 {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_offset", "offset min 0"))
		return
	}
	order := req.Order
	if order == "" {
		order = "newest_first"
	}
	if order != "newest_first" && order != "oldest_first" {
		writeErr(w, apiErr(http.StatusBadRequest, "invalid_order", "invalid order"))
		return
	}
	fromT, _ := parseTime(req.FromTime)
	toT, _ := parseTime(req.ToTime)
	q := audit.AuditQuery{
		Query: req.Query, ActorID: req.ActorID, EntityType: req.EntityType, EntityID: req.EntityID,
		Action: req.Action, Role: req.Role, Success: req.Success, FromTime: fromT, ToTime: toT,
		Limit: limit, Offset: req.Offset, Order: order,
	}
	res, err := a.Audit.Search(r.Context(), q)
	if err != nil {
		writeErr(w, err)
		return
	}
	web.Data(w, http.StatusOK, res)
}

