package routing

import "testing"

func TestHaversineKm(t *testing.T) {
	// Bangalore CP North (12.97, 77.59) to Central Lab (12.96, 77.60)
	d := HaversineKm(12.97, 77.59, 12.96, 77.60)
	if d <= 0 || d > 5 {
		t.Fatalf("expected short distance within 5km, got %f", d)
	}
}

func TestCollectionPointsCoverage(t *testing.T) {
	n := NewNetwork()
	n.AddNode(&Node{LocationID: "cp1", Name: "CP", Latitude: 12.97, Longitude: 77.59, CoverageKm: 5, Active: true, CollectionPoint: true})
	n.AddNode(&Node{LocationID: "lab", Latitude: 12.0, Longitude: 70.0, CoverageKm: 5, Active: true, Laboratory: true})
	cps := n.CollectionPoints(12.9701, 77.5901, 5)
	if len(cps) != 1 || cps[0].LocationID != "cp1" {
		t.Fatalf("expected cp1 only, got %v", cps)
	}
}

func TestFindPathDirect(t *testing.T) {
	n := NewNetwork()
	n.AddNode(&Node{LocationID: "cp", Latitude: 12.97, Longitude: 77.59, CoverageKm: 5, Active: true, CollectionPoint: true})
	n.AddNode(&Node{LocationID: "lab", Latitude: 12.96, Longitude: 77.60, CoverageKm: 5, Active: true, Laboratory: true})
	n.AddEdge(&Edge{ConnectionID: "c1", From: "cp", To: "lab", TravelMinutes: 20, CostUnits: 5, Cooled: false, Active: true})
	p := n.FindPath("cp", map[string]bool{"lab": true}, false, false)
	if p == nil || len(p.Edges) != 1 {
		t.Fatalf("expected one-edge path, got %v", p)
	}
	if p.Nodes[len(p.Nodes)-1].LocationID != "lab" {
		t.Fatalf("expected to reach lab")
	}
}

